// ParenExprLabel
// ───────────────────────────────────────────────────────────────────────────

/// Label discriminant enum for children of this node type.
///
/// Python-visible name is `ParenExpr_Label` (preserved for compatibility).
/// Rust consumers use the CamelCase `ParenExprLabel` name.
#[cfg(feature = "python")]
#[pyclass(frozen, from_py_object, name = "ParenExpr_Label")]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ParenExprLabel {
    #[pyo3(name = "INNER")]
    Inner,
}

#[cfg(not(feature = "python"))]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ParenExprLabel {
    Inner,
}

#[cfg(feature = "python")]
#[pymethods]
impl ParenExprLabel {
    fn __repr__(&self) -> &'static str {
        match self {
            ParenExprLabel::Inner => "ParenExpr.Label.INNER",
        }
    }

    #[getter]
    fn _fltk_canonical_name(&self) -> &'static str {
        self.__repr__()
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if let Ok(other_kind) = other.extract::<ParenExprLabel>() {
            return Ok((self == &other_kind).into_pyobject(py)?.to_owned().unbind().into_any());
        }
        if let Ok(cn) = other.getattr(pyo3::intern!(py, "_fltk_canonical_name")) {
            if let Ok(cn_str) = cn.extract::<&str>() {
                return Ok((self.__repr__() == cn_str).into_pyobject(py)?.to_owned().unbind().into_any());
            }
        }
        Ok(py.NotImplemented())
    }

    fn __hash__(&self, py: Python<'_>) -> pyo3::PyResult<isize> {
        pyo3::types::PyAnyMethods::hash(
            pyo3::types::PyString::new(py, self.__repr__()).as_any()
        )
    }
}

#[cfg(feature = "python")]
impl ParenExprLabel {
    /// The variant with this cross-backend canonical name, if any.
    fn from_canonical_name(name: &str) -> ::std::option::Option<Self> {
        match name {
            "ParenExpr.Label.INNER" => Some(ParenExprLabel::Inner),
            _ => None,
        }
    }
}

/// Child value enum for `ParenExpr` nodes.
///
/// Node-typed variants hold `Shared<T>` (`Arc<RwLock<T>>`); `Clone` is shallow
/// (increments the reference count, does not copy the node).
#[derive(Clone, Debug)]
pub enum ParenExprChild {
    Atom(Shared<Atom>),
    Trivia(Shared<Trivia>),
}

impl ::std::cmp::PartialEq for ParenExprChild {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (ParenExprChild::Atom(a), ParenExprChild::Atom(b)) => a == b,
            (ParenExprChild::Trivia(a), ParenExprChild::Trivia(b)) => a == b,
            _ => false,
        }
    }
}

impl ParenExprChild {
    fn into_drop_item(self) -> ::std::option::Option<DropWorklistItem> {
        match self {
            Self::Atom(s) => Some(DropWorklistItem::Atom(s)),
            Self::Trivia(s) => Some(DropWorklistItem::Trivia(s)),
        }
    }

    /// Shallow structural equality for one child pair.
    /// Span pair: compare directly. Node pair: ptr_eq short-circuit (skip enqueue)
    /// or enqueue for the worklist. Variant mismatch: return false.
    fn eq_shallow_enqueue(&self, other: &Self, worklist: &mut ::std::vec::Vec<EqWorklistItem>) -> bool {
        match (self, other) {
            (Self::Atom(a), Self::Atom(b)) => {
                if !a.ptr_eq(b) {
                    worklist.push(EqWorklistItem::Atom(a.clone(), b.clone()));
                }
                true
            }
            (Self::Trivia(a), Self::Trivia(b)) => {
                if !a.ptr_eq(b) {
                    worklist.push(EqWorklistItem::Trivia(a.clone(), b.clone()));
                }
                true
            }
            _ => false,
        }
    }
}

#[cfg(feature = "python")]
impl ParenExprChild {
    fn to_pyobject(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        match self {
            Self::Atom(shared) => {
                let addr = shared.arc_ptr();
                registry::get_or_insert_with(py, addr, || {
                    let handle = PyAtom { inner: shared.clone() };
                    Py::new(py, handle).map(|p| p.into_any())
                })
            }
            Self::Trivia(shared) => {
                let addr = shared.arc_ptr();
                registry::get_or_insert_with(py, addr, || {
                    let handle = PyTrivia { inner: shared.clone() };
                    Py::new(py, handle).map(|p| p.into_any())
                })
            }
        }
    }

    fn extract_from_pyobject(
        py: Python<'_>,
        obj: &Bound<'_, pyo3::PyAny>,
        _span_type: &Bound<'_, pyo3::types::PyType>,
    ) -> pyo3::PyResult<Self> {
        if obj.is_instance_of::<PyAtom>() {
            let handle: pyo3::PyRef<PyAtom> = obj.extract()?;
            let shared = handle.inner.clone();
            let addr = shared.arc_ptr();
            // Hand-in: register this Python handle as canonical for its Shared.
            drop(handle); // release the PyRef before calling Python
            // Propagate registry errors: a swallowed Err here would leave the
            // handle unregistered, causing the next wrap-out to mint a different
            // object and silently break is-stability.
            registry::register_if_absent(py, addr, obj)?;
            return Ok(Self::Atom(shared));
        }
        if obj.is_instance_of::<PyTrivia>() {
            let handle: pyo3::PyRef<PyTrivia> = obj.extract()?;
            let shared = handle.inner.clone();
            let addr = shared.arc_ptr();
            // Hand-in: register this Python handle as canonical for its Shared.
            drop(handle); // release the PyRef before calling Python
            // Propagate registry errors: a swallowed Err here would leave the
            // handle unregistered, causing the next wrap-out to mint a different
            // object and silently break is-stability.
            registry::register_if_absent(py, addr, obj)?;
            return Ok(Self::Trivia(shared));
        }
        let rejected_type = obj.get_type();
        Err(pyo3::exceptions::PyTypeError::new_err(format!(
            "ParenExpr: unsupported child type {}.{}",
            rejected_type.module()?,
            rejected_type.qualname()?
        )))
    }
}

// ───────────────────────────────────────────────────────────────────────────
// ParenExpr
// ───────────────────────────────────────────────────────────────────────────

/// CST data struct for `ParenExpr`. See [`fltk_cst_core::Shared`] for clone/equality/reference semantics.
///
/// `Debug` output is non-recursive: prints span + child count only. Traverse via `children()` to inspect subtrees.
/// Teardown is iterative: bounded stack at any depth.
/// Equality is iterative: bounded stack at any depth.
#[derive(Clone)]
pub struct ParenExpr {
    // Not pub: use span() / children() / push_child() — the stable accessor API.
    // Direct field access bypasses any future validation logic on setters.
    span: Span,
    children: ::std::vec::Vec<(::std::option::Option<ParenExprLabel>, ParenExprChild)>,
}

// Manual Debug: prints span + child COUNT, never recursing into children.
// A derived Debug would recurse through Shared<T> children with no depth
// bound; tree depth is attacker-controlled for parsers over untrusted
// input, so `{:?}` on a deep tree would abort the process (stack
// exhaustion, uncatchable). Mirrors the Python __repr__'s content.
impl fmt::Debug for ParenExpr {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("ParenExpr")
            .field("span", &self.span)
            .field("children", &format_args!("<{} child(ren)>", self.children.len()))
            .finish()
    }
}

// Iterative Drop: derived drop glue would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Drains the subtree via a worklist instead.
impl ::std::ops::Drop for ParenExpr {
    fn drop(&mut self) {
        if self.children.is_empty() {
            return; // also the recursion terminator for nodes drained by the worklist
        }
        // Worklist is allocated lazily: Vec::new() does not heap-allocate until
        // the first push.  drain_into pushes only when it steals (count == 1).
        // In the common backtracking case (shared/memoized children) no steal
        // occurs and no allocation happens.  Owned deep chains allocate once.
        let mut worklist: ::std::vec::Vec<DropWorklistItem> = ::std::vec::Vec::new();
        for (_, child) in self.children.drain(..) {
            if let Some(item) = child.into_drop_item() {
                item.drain_into(&mut worklist);
            }
        }
        while let Some(item) = worklist.pop() {
            item.drain_into(&mut worklist);
        }
    }
}

// Iterative PartialEq: the recursive version would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Uses an explicit worklist of node pairs.
impl ::std::cmp::PartialEq for ParenExpr {
    fn eq(&self, other: &Self) -> bool {
        if self.span != other.span || self.children.len() != other.children.len() {
            return false;
        }
        // Worklist allocated lazily (Vec::new does not heap-allocate until
        // first push); shallow trees and all-ptr_eq children never allocate.
        let mut worklist: ::std::vec::Vec<EqWorklistItem> = ::std::vec::Vec::new();
        for ((la, ca), (lb, cb)) in self.children.iter().zip(other.children.iter()) {
            if la != lb || !ca.eq_shallow_enqueue(cb, &mut worklist) {
                return false;
            }
        }
        while let Some(item) = worklist.pop() {
            if !item.compare(&mut worklist) {
                return false;
            }
        }
        true
    }
}

impl ParenExpr {
    /// Construct a node with the given span and no children. GIL-free.
    pub fn new(span: Span) -> Self {
        ParenExpr {
            span,
            children: ::std::vec::Vec::new(),
        }
    }

    /// Return the [`NodeKind`] discriminant for this node type.
    pub fn kind(&self) -> NodeKind {
        NodeKind::ParenExpr
    }

    /// Return a reference to the stored [`Span`].
    pub fn span(&self) -> &Span {
        &self.span
    }

    /// Replace the node's span.
    pub fn set_span(&mut self, span: Span) {
        self.span = span;
    }

    /// Return a slice of all children (unfiltered).
    ///
    /// Each entry is `(label, child)`. Use the per-label accessors
    /// (`children_<lbl>`, `child_<lbl>`, `maybe_<lbl>`) for type-safe access.
    pub fn children(&self) -> &[(::std::option::Option<ParenExprLabel>, ParenExprChild)] {
        self.children.as_slice()
    }

    /// Push a child onto the children `Vec`.
    ///
    /// No type-checking is performed: any child variant may be stored under
    /// any label. Per-label typed mutators (`append_<lbl>`, `extend_<lbl>`)
    /// provide type-constrained alternatives.
    pub fn push_child(&mut self, label: ::std::option::Option<ParenExprLabel>, child: ParenExprChild) {
        self.children.push((label, child));
    }

    /// Return the single child (any label), or `Err` if there is not exactly one.
    ///
    /// Mirrors the Python `child()` method: count violation → `CstError::ChildCount`.
    pub fn child(&self) -> ::std::result::Result<&(::std::option::Option<ParenExprLabel>, ParenExprChild), CstError> {
        match self.children.as_slice() {
            [single] => Ok(single),
            slice => Err(CstError::ChildCount {
                label: "<any>",
                expected: "1",
                found: slice.len(),
            }),
        }
    }

    /// Copy all children from `other` into `self`, sharing the `Shared<T>` arcs.
    ///
    /// Children are appended (Arc reference-count bumps, not deep copies),
    /// matching the Python backend's reference-copy behavior. Labels are preserved.
    ///
    /// The borrow checker prevents `self.extend_children(self)` at the data-struct
    /// level (`&mut` + `&` of the same value don't coexist). For self-extend from
    /// Python, the handle pymethod handles it via snapshotting.
    pub fn extend_children(&mut self, other: &Self) {
        self.children.extend(other.children.iter().cloned());
    }

    /// Return an iterator over `Shared<Atom>` children labelled `inner`.
    ///
    /// Off-type variants stored under the `inner` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_inner(&self) -> impl ::std::iter::Iterator<Item = &Shared<Atom>> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(ParenExprLabel::Inner))
            .filter_map(|(_, child)| match child {
                ParenExprChild::Atom(s) => Some(s),
                _ => None,
            })
    }

    /// Return the single child labelled `inner`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_inner(&self) -> ::std::result::Result<&Shared<Atom>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(ParenExprLabel::Inner));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                ParenExprChild::Atom(s) => Ok(s),
                _ => Err(CstError::UnexpectedChildType { label: "inner" }),
            },
            _ => Err(CstError::ChildCount {
                label: "inner",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(ParenExprLabel::Inner))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `inner`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_inner(&self) -> ::std::result::Result<::std::option::Option<&Shared<Atom>>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(ParenExprLabel::Inner));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                ParenExprChild::Atom(s) => Ok(Some(s)),
                _ => Err(CstError::UnexpectedChildType { label: "inner" }),
            },
            _ => Err(CstError::ChildCount {
                label: "inner",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(ParenExprLabel::Inner))
                    .count(),
            }),
        }
    }

    /// Append a child with label `inner`, accepting `Atom` or `Shared<Atom>`.
    pub fn append_inner(&mut self, child: impl ::std::convert::Into<Shared<Atom>>) {
        self.children.push((Some(ParenExprLabel::Inner), ParenExprChild::Atom(child.into())));
    }

    /// Append multiple children with label `inner`.
    pub fn extend_inner(&mut self, children: impl ::std::iter::IntoIterator<Item = impl ::std::convert::Into<Shared<Atom>>>) {
        self.children.extend(children.into_iter().map(|c| (Some(ParenExprLabel::Inner), ParenExprChild::Atom(c.into()))));
    }

    /// Return the child labelled `inner`.
    ///
    /// Panics unless exactly one is present; use `child_inner` for the checked form.
    pub fn inner(&self) -> &Shared<Atom> {
        self.child_inner()
            .unwrap_or_else(|e| panic!("ParenExpr.inner: {e}"))
    }

    /// Insert a child at `index` (Vec::insert semantics: panics if index > len).
    ///
    /// Python-facing clamping is in the `insert` pymethod; native callers must
    /// bounds-check. Unlike `list.insert`, Vec::insert panics on out-of-bounds.
    pub fn insert_child(&mut self, index: usize, label: ::std::option::Option<ParenExprLabel>, child: ParenExprChild) {
        self.children.insert(index, (label, child));
    }

    /// Remove and return the child at `index` (Vec::remove semantics: panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `remove_at` pymethod.
    pub fn remove_child(&mut self, index: usize) -> (::std::option::Option<ParenExprLabel>, ParenExprChild) {
        self.children.remove(index)
    }

    /// Replace the child at `index`, returning the old entry (panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `replace_at` pymethod.
    pub fn replace_child(
        &mut self, index: usize, label: ::std::option::Option<ParenExprLabel>, child: ParenExprChild,
    ) -> (::std::option::Option<ParenExprLabel>, ParenExprChild) {
        std::mem::replace(&mut self.children[index], (label, child))
    }

    /// Remove all children.
    pub fn clear_children(&mut self) {
        self.children.clear();
    }
}

#[cfg(feature = "python")]
#[pyclass(frozen, weakref, name = "ParenExpr")]
pub struct PyParenExpr {
    // Not pub: all external access goes through shared() or to_py_canonical().
    // A pub field would let mixed-app Rust code construct an unregistered handle
    // (Py::new(py, PyFoo { inner: s.clone() })), silently breaking is-stability.
    inner: Shared<ParenExpr>,
}

#[cfg(feature = "python")]
impl PyParenExpr {
    /// Return a reference to the inner `Shared<ParenExpr>`.
    pub fn shared(&self) -> &Shared<ParenExpr> {
        &self.inner
    }

    /// Wrap a `Shared<ParenExpr>` into a canonical Python handle,
    /// looking up the registry first so the same handle is returned
    /// for the same `Shared` allocation.
    pub fn to_py_canonical(py: Python<'_>, s: &Shared<ParenExpr>) -> pyo3::PyResult<Py<PyParenExpr>> {
        let addr = s.arc_ptr();
        let obj = registry::get_or_insert_with(py, addr, || {
            let handle = PyParenExpr { inner: s.clone() };
            Py::new(py, handle).map(|p| p.into_any())
        })?;
        obj.bind(py).cast::<PyParenExpr>().map(|b| b.clone().unbind()).map_err(|e| e.into())
    }

    /// Snapshot the children carrying `label` into a new Python list.
    fn py_children_snapshot(&self, py: Python<'_>, label: &ParenExprLabel) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Lock scope: filter by label under the read guard, cloning only matching
        // children (Arc bump or Span copy each); drop the guard before to_pyobject,
        // which performs Python work that must not happen while a node lock is held.
        let matching: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.iter()
                .filter(|(lbl, _)| lbl.as_ref() == Some(label))
                .map(|(_, child)| child.clone())
                .collect()
        };
        let result = pyo3::types::PyList::empty(py);
        for child in &matching {
            result.append(child.to_pyobject(py)?)?;
        }
        Ok(result.unbind())
    }
}

#[cfg(feature = "python")]
#[pymethods]
impl PyParenExpr {
    #[new]
    #[pyo3(signature = (*, span = None))]
    fn new(py: Python<'_>, span: ::std::option::Option<&Bound<'_, pyo3::PyAny>>) -> pyo3::PyResult<Py<PyParenExpr>> {
        let native_span = match span {
            Some(s) => extract_span(py, s)?,
            None => Span::unknown(),
        };
        let data = ParenExpr {
            span: native_span,
            children: ::std::vec::Vec::new(),
        };
        let shared = Shared::new(data);
        let addr = shared.arc_ptr();
        let handle = PyParenExpr { inner: shared };
        let py_obj = Py::new(py, handle)?;
        // Register as canonical — fresh Shared, no alias can exist yet.
        registry::force_register(py, addr, py_obj.bind(py))?;
        Ok(py_obj)
    }

    #[getter]
    fn span(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Snapshot the span under the read lock, then drop the guard before
        // calling span_to_pyobject — which performs Python work (Py::new or
        // Python method calls) that must not happen while a node lock is held.
        let span = self.inner.read().span.clone();
        span_to_pyobject(py, &span)
    }

    #[setter]
    fn set_span(&self, py: Python<'_>, value: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        self.inner.write().span = extract_span(py, value)?;
        Ok(())
    }

    #[getter]
    fn kind(&self) -> NodeKind {
        NodeKind::ParenExpr
    }

    #[classattr]
    #[allow(non_snake_case)]
    fn Label(py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        Ok(<ParenExprLabel as pyo3::PyTypeInfo>::type_object(py).into_any().unbind())
    }

    #[getter]
    fn children(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Snapshot the children vec (Arc clones for node children — O(n) refcount bumps).
        // Lock scope: acquire read, snapshot, release before touching Python.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.clone()
        };
        let result = pyo3::types::PyList::empty(py);
        for (label, child) in &snapshot {
            let label_obj: Py<pyo3::PyAny> = match label {
                None => py.None(),
                Some(lbl) => lbl.clone().into_pyobject(py)?.into_any().unbind(),
            };
            let child_obj = child.to_pyobject(py)?;
            let tup = pyo3::types::PyTuple::new(py, [label_obj, child_obj])?;
            result.append(tup)?;
        }
        Ok(result.unbind())
    }

    #[pyo3(signature = (child, label = None))]
    fn append(
        &self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>, label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<ParenExprLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| ParenExprLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "ParenExpr.append: label argument is not a ParenExpr_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = ParenExprChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((native_label, native_child));
        Ok(())
    }

    #[pyo3(signature = (children, label = None))]
    fn extend(
        &self,
        py: Python<'_>,
        children: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<ParenExprLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| ParenExprLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "ParenExpr.extend: label argument is not a ParenExpr_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must leave
        // the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = ParenExprChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((native_label.clone(), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn extend_children(&self, _py: Python<'_>, other: &PyParenExpr) -> pyo3::PyResult<()> {
        // Snapshot other's children first: the read guard is dropped at the end of
        // this block, so the write lock below is safe even when self and other are
        // the same node (self-extend). No ptr_eq call is needed here — the snapshot
        // approach handles self-extend structurally.
        // Lock scope: hold read only long enough to clone the Arc-based children vec.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = other.inner.read();
            guard.children.clone()
        };
        // Node-typed children are pushed directly as Shared<T> values.  Registry
        // consistency is maintained lazily: wrap-out registers on first Python read
        // via get_or_insert_with (registry.rs).  Eagerly registering here would be
        // a no-op — the WeakValueDictionary would evict handles held by nothing.
        self.inner.write().children.extend(snapshot);
        Ok(())
    }

    fn child(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: read len and clone at most the single entry under the guard;
        // drop the guard before any Python work (object conversion, exception raise).
        let (n, entry) = {
            let guard = self.inner.read();
            let n = guard.children.len();
            let entry = if n == 1 { Some(guard.children[0].clone()) } else { None };
            (n, entry)
        };
        let Some((label, child)) = entry else {
            return Err(PyValueError::new_err(format!(
                "Expected one child but have {n}"
            )));
        };
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn insert(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<ParenExprLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| ParenExprLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "ParenExpr.insert: label argument is not a ParenExpr_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = ParenExprChild::extract_from_pyobject(py, child, &span_type)?;
        // Index normalization via operator.index (PyNumber_Index semantics).
        // This raises TypeError (not AttributeError) for non-indexable inputs, matching Python's
        // operator.index contract. Must be done BEFORE taking any lock.
        // Overflow by sign: positive overflow clamps to len; negative overflow clamps to 0.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path for the common exact-int case; fall back to sign-based Python call for beyond-i64.
        let (is_negative_big, raw_i64) = if let Ok(i) = raw_idx.extract::<i64>() {
            (false, Some(i))
        } else {
            // Beyond i64: use Python __lt__ to determine sign.  The lt call is still outside
            // any lock, so lock discipline is maintained.
            let neg = raw_idx.lt(0i64)?;
            (neg, None)
        };
        // Now take a single write lock for the entire len-read + clamp + insert sequence.
        let mut guard = self.inner.write();
        let n = guard.children.len();
        let clamped: usize = match raw_i64 {
            Some(i) if i < 0 => {
                let normalized = n as i64 + i;
                if normalized < 0 { 0 } else { normalized as usize }
            }
            Some(i) => {
                let u = i as usize;
                if u > n { n } else { u }
            }
            None => if is_negative_big { 0 } else { n },
        };
        guard.children.insert(clamped, (native_label, native_child));
        Ok(())
    }

    fn remove_at(&self, py: Python<'_>, index: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Capture the caller's original string representation BEFORE normalization,
        // so error messages show the original value (e.g. `True` not `1`).
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError (not AttributeError) for
        // non-indexable inputs, matching Python's operator.index contract.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path: extract i64. Beyond i64 is always OOB for real trees.
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + Vec::remove atomically (no TOCTOU).
        // On OOB, capture n and return Err after releasing the guard.
        let result: ::std::result::Result<_, usize> = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            match resolved {
                Some(idx) => Ok(guard.children.remove(idx)),
                None => Err(n),
            }
        };
        let (label, child) = result.map_err(|n| {
            PyIndexError::new_err(format!(
                "ParenExpr.remove_at: index {} out of range ({} children)",
                orig_str, n
            ))
        })?;
        // Python wrap-out happens after the guard is released.
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn replace_at(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<ParenExprLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| ParenExprLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "ParenExpr.replace_at: label argument is not a ParenExpr_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = ParenExprChild::extract_from_pyobject(py, child, &span_type)?;
        // Capture the caller's original string representation BEFORE normalization.
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError for non-indexable inputs.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + mem::replace atomically (no TOCTOU).
        let old = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            let idx = match resolved {
                Some(i) => i,
                None => {
                    return Err(PyIndexError::new_err(format!(
                        "ParenExpr.replace_at: index {} out of range ({} children)",
                        orig_str, n
                    )));
                }
            };
            std::mem::replace(&mut guard.children[idx], (native_label, native_child))
        };
        // Drop old entry outside the lock to avoid recursive lock acquisition
        // if the child's drop chain re-enters Python.
        drop(old);
        Ok(())
    }

    fn clear(&self, _py: Python<'_>) -> pyo3::PyResult<()> {
        let old = {
            let mut guard = self.inner.write();
            std::mem::take(&mut guard.children)
        };
        // Drop old entries outside the lock.
        drop(old);
        Ok(())
    }

    fn append_inner(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = ParenExprChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(ParenExprLabel::Inner), native_child));
        Ok(())
    }

    fn extend_inner(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = ParenExprChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(ParenExprLabel::Inner), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_inner(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &ParenExprLabel::Inner)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_inner(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(ParenExprLabel::Inner) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one inner child but have {count}"
            )));
        }
        first.expect("invariant: ParenExpr.child_inner: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_inner(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(ParenExprLabel::Inner) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one inner child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn inner(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        self.child_inner(py)
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if !other.is_instance_of::<PyParenExpr>() {
            return Ok(py.NotImplemented());
        }
        let other_handle: pyo3::PyRef<PyParenExpr> = other.extract()?;
        // Delegate to Shared<T>::PartialEq which applies the ptr_eq short-circuit
        // (avoids same-lock re-entry on `x == x`) then deep structural comparison.
        let eq = self.inner == other_handle.inner;
        Ok(eq.into_pyobject(py)?.to_owned().unbind().into_any())
    }

    fn __hash__(&self) -> pyo3::PyResult<isize> {
        Err(PyTypeError::new_err("unhashable type: 'ParenExpr'"))
    }

    fn __repr__(&self, _py: Python<'_>) -> ::std::string::String {
        let guard = self.inner.read();
        let span_repr = format!("Span(start={}, end={})", guard.span.start(), guard.span.end());
        let children_len = guard.children.len();
        format!(
            "ParenExpr(span={span_repr}, children=[<{children_len} child(ren)>])"
        )
    }

}

// ───────────────────────────────────────────────────────────────────────────
// StmtLabel
// ───────────────────────────────────────────────────────────────────────────

/// Label discriminant enum for children of this node type.
///
/// Python-visible name is `Stmt_Label` (preserved for compatibility).
/// Rust consumers use the CamelCase `StmtLabel` name.
#[cfg(feature = "python")]
#[pyclass(frozen, from_py_object, name = "Stmt_Label")]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum StmtLabel {
    #[pyo3(name = "LHS")]
    Lhs,
    #[pyo3(name = "RHS")]
    Rhs,
}

#[cfg(not(feature = "python"))]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum StmtLabel {
    Lhs,
    Rhs,
}

#[cfg(feature = "python")]
#[pymethods]
impl StmtLabel {
    fn __repr__(&self) -> &'static str {
        match self {
            StmtLabel::Lhs => "Stmt.Label.LHS",
            StmtLabel::Rhs => "Stmt.Label.RHS",
        }
    }

    #[getter]
    fn _fltk_canonical_name(&self) -> &'static str {
        self.__repr__()
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if let Ok(other_kind) = other.extract::<StmtLabel>() {
            return Ok((self == &other_kind).into_pyobject(py)?.to_owned().unbind().into_any());
        }
        if let Ok(cn) = other.getattr(pyo3::intern!(py, "_fltk_canonical_name")) {
            if let Ok(cn_str) = cn.extract::<&str>() {
                return Ok((self.__repr__() == cn_str).into_pyobject(py)?.to_owned().unbind().into_any());
            }
        }
        Ok(py.NotImplemented())
    }

    fn __hash__(&self, py: Python<'_>) -> pyo3::PyResult<isize> {
        pyo3::types::PyAnyMethods::hash(
            pyo3::types::PyString::new(py, self.__repr__()).as_any()
        )
    }
}

#[cfg(feature = "python")]
impl StmtLabel {
    /// The variant with this cross-backend canonical name, if any.
    fn from_canonical_name(name: &str) -> ::std::option::Option<Self> {
        match name {
            "Stmt.Label.LHS" => Some(StmtLabel::Lhs),
            "Stmt.Label.RHS" => Some(StmtLabel::Rhs),
            _ => None,
        }
    }
}

/// Child value enum for `Stmt` nodes.
///
/// Node-typed variants hold `Shared<T>` (`Arc<RwLock<T>>`); `Clone` is shallow
/// (increments the reference count, does not copy the node).
#[derive(Clone, Debug)]
pub enum StmtChild {
    Atom(Shared<Atom>),
    Trivia(Shared<Trivia>),
}

impl ::std::cmp::PartialEq for StmtChild {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (StmtChild::Atom(a), StmtChild::Atom(b)) => a == b,
            (StmtChild::Trivia(a), StmtChild::Trivia(b)) => a == b,
            _ => false,
        }
    }
}

impl StmtChild {
    fn into_drop_item(self) -> ::std::option::Option<DropWorklistItem> {
        match self {
            Self::Atom(s) => Some(DropWorklistItem::Atom(s)),
            Self::Trivia(s) => Some(DropWorklistItem::Trivia(s)),
        }
    }

    /// Shallow structural equality for one child pair.
    /// Span pair: compare directly. Node pair: ptr_eq short-circuit (skip enqueue)
    /// or enqueue for the worklist. Variant mismatch: return false.
    fn eq_shallow_enqueue(&self, other: &Self, worklist: &mut ::std::vec::Vec<EqWorklistItem>) -> bool {
        match (self, other) {
            (Self::Atom(a), Self::Atom(b)) => {
                if !a.ptr_eq(b) {
                    worklist.push(EqWorklistItem::Atom(a.clone(), b.clone()));
                }
                true
            }
            (Self::Trivia(a), Self::Trivia(b)) => {
                if !a.ptr_eq(b) {
                    worklist.push(EqWorklistItem::Trivia(a.clone(), b.clone()));
                }
                true
            }
            _ => false,
        }
    }
}

#[cfg(feature = "python")]
impl StmtChild {
    fn to_pyobject(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        match self {
            Self::Atom(shared) => {
                let addr = shared.arc_ptr();
                registry::get_or_insert_with(py, addr, || {
                    let handle = PyAtom { inner: shared.clone() };
                    Py::new(py, handle).map(|p| p.into_any())
                })
            }
            Self::Trivia(shared) => {
                let addr = shared.arc_ptr();
                registry::get_or_insert_with(py, addr, || {
                    let handle = PyTrivia { inner: shared.clone() };
                    Py::new(py, handle).map(|p| p.into_any())
                })
            }
        }
    }

    fn extract_from_pyobject(
        py: Python<'_>,
        obj: &Bound<'_, pyo3::PyAny>,
        _span_type: &Bound<'_, pyo3::types::PyType>,
    ) -> pyo3::PyResult<Self> {
        if obj.is_instance_of::<PyAtom>() {
            let handle: pyo3::PyRef<PyAtom> = obj.extract()?;
            let shared = handle.inner.clone();
            let addr = shared.arc_ptr();
            // Hand-in: register this Python handle as canonical for its Shared.
            drop(handle); // release the PyRef before calling Python
            // Propagate registry errors: a swallowed Err here would leave the
            // handle unregistered, causing the next wrap-out to mint a different
            // object and silently break is-stability.
            registry::register_if_absent(py, addr, obj)?;
            return Ok(Self::Atom(shared));
        }
        if obj.is_instance_of::<PyTrivia>() {
            let handle: pyo3::PyRef<PyTrivia> = obj.extract()?;
            let shared = handle.inner.clone();
            let addr = shared.arc_ptr();
            // Hand-in: register this Python handle as canonical for its Shared.
            drop(handle); // release the PyRef before calling Python
            // Propagate registry errors: a swallowed Err here would leave the
            // handle unregistered, causing the next wrap-out to mint a different
            // object and silently break is-stability.
            registry::register_if_absent(py, addr, obj)?;
            return Ok(Self::Trivia(shared));
        }
        let rejected_type = obj.get_type();
        Err(pyo3::exceptions::PyTypeError::new_err(format!(
            "Stmt: unsupported child type {}.{}",
            rejected_type.module()?,
            rejected_type.qualname()?
        )))
    }
}

// ───────────────────────────────────────────────────────────────────────────
// Stmt
// ───────────────────────────────────────────────────────────────────────────

/// CST data struct for `Stmt`. See [`fltk_cst_core::Shared`] for clone/equality/reference semantics.
///
/// `Debug` output is non-recursive: prints span + child count only. Traverse via `children()` to inspect subtrees.
/// Teardown is iterative: bounded stack at any depth.
/// Equality is iterative: bounded stack at any depth.
#[derive(Clone)]
pub struct Stmt {
    // Not pub: use span() / children() / push_child() — the stable accessor API.
    // Direct field access bypasses any future validation logic on setters.
    span: Span,
    children: ::std::vec::Vec<(::std::option::Option<StmtLabel>, StmtChild)>,
}

// Manual Debug: prints span + child COUNT, never recursing into children.
// A derived Debug would recurse through Shared<T> children with no depth
// bound; tree depth is attacker-controlled for parsers over untrusted
// input, so `{:?}` on a deep tree would abort the process (stack
// exhaustion, uncatchable). Mirrors the Python __repr__'s content.
impl fmt::Debug for Stmt {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Stmt")
            .field("span", &self.span)
            .field("children", &format_args!("<{} child(ren)>", self.children.len()))
            .finish()
    }
}

// Iterative Drop: derived drop glue would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Drains the subtree via a worklist instead.
impl ::std::ops::Drop for Stmt {
    fn drop(&mut self) {
        if self.children.is_empty() {
            return; // also the recursion terminator for nodes drained by the worklist
        }
        // Worklist is allocated lazily: Vec::new() does not heap-allocate until
        // the first push.  drain_into pushes only when it steals (count == 1).
        // In the common backtracking case (shared/memoized children) no steal
        // occurs and no allocation happens.  Owned deep chains allocate once.
        let mut worklist: ::std::vec::Vec<DropWorklistItem> = ::std::vec::Vec::new();
        for (_, child) in self.children.drain(..) {
            if let Some(item) = child.into_drop_item() {
                item.drain_into(&mut worklist);
            }
        }
        while let Some(item) = worklist.pop() {
            item.drain_into(&mut worklist);
        }
    }
}

// Iterative PartialEq: the recursive version would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Uses an explicit worklist of node pairs.
impl ::std::cmp::PartialEq for Stmt {
    fn eq(&self, other: &Self) -> bool {
        if self.span != other.span || self.children.len() != other.children.len() {
            return false;
        }
        // Worklist allocated lazily (Vec::new does not heap-allocate until
        // first push); shallow trees and all-ptr_eq children never allocate.
        let mut worklist: ::std::vec::Vec<EqWorklistItem> = ::std::vec::Vec::new();
        for ((la, ca), (lb, cb)) in self.children.iter().zip(other.children.iter()) {
            if la != lb || !ca.eq_shallow_enqueue(cb, &mut worklist) {
                return false;
            }
        }
        while let Some(item) = worklist.pop() {
            if !item.compare(&mut worklist) {
                return false;
            }
        }
        true
    }
}

impl Stmt {
    /// Construct a node with the given span and no children. GIL-free.
    pub fn new(span: Span) -> Self {
        Stmt {
            span,
            children: ::std::vec::Vec::new(),
        }
    }

    /// Return the [`NodeKind`] discriminant for this node type.
    pub fn kind(&self) -> NodeKind {
        NodeKind::Stmt
    }

    /// Return a reference to the stored [`Span`].
    pub fn span(&self) -> &Span {
        &self.span
    }

    /// Replace the node's span.
    pub fn set_span(&mut self, span: Span) {
        self.span = span;
    }

    /// Return a slice of all children (unfiltered).
    ///
    /// Each entry is `(label, child)`. Use the per-label accessors
    /// (`children_<lbl>`, `child_<lbl>`, `maybe_<lbl>`) for type-safe access.
    pub fn children(&self) -> &[(::std::option::Option<StmtLabel>, StmtChild)] {
        self.children.as_slice()
    }

    /// Push a child onto the children `Vec`.
    ///
    /// No type-checking is performed: any child variant may be stored under
    /// any label. Per-label typed mutators (`append_<lbl>`, `extend_<lbl>`)
    /// provide type-constrained alternatives.
    pub fn push_child(&mut self, label: ::std::option::Option<StmtLabel>, child: StmtChild) {
        self.children.push((label, child));
    }

    /// Return the single child (any label), or `Err` if there is not exactly one.
    ///
    /// Mirrors the Python `child()` method: count violation → `CstError::ChildCount`.
    pub fn child(&self) -> ::std::result::Result<&(::std::option::Option<StmtLabel>, StmtChild), CstError> {
        match self.children.as_slice() {
            [single] => Ok(single),
            slice => Err(CstError::ChildCount {
                label: "<any>",
                expected: "1",
                found: slice.len(),
            }),
        }
    }

    /// Copy all children from `other` into `self`, sharing the `Shared<T>` arcs.
    ///
    /// Children are appended (Arc reference-count bumps, not deep copies),
    /// matching the Python backend's reference-copy behavior. Labels are preserved.
    ///
    /// The borrow checker prevents `self.extend_children(self)` at the data-struct
    /// level (`&mut` + `&` of the same value don't coexist). For self-extend from
    /// Python, the handle pymethod handles it via snapshotting.
    pub fn extend_children(&mut self, other: &Self) {
        self.children.extend(other.children.iter().cloned());
    }

    /// Return an iterator over `Shared<Atom>` children labelled `lhs`.
    ///
    /// Off-type variants stored under the `lhs` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_lhs(&self) -> impl ::std::iter::Iterator<Item = &Shared<Atom>> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(StmtLabel::Lhs))
            .filter_map(|(_, child)| match child {
                StmtChild::Atom(s) => Some(s),
                _ => None,
            })
    }

    /// Return the single child labelled `lhs`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_lhs(&self) -> ::std::result::Result<&Shared<Atom>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(StmtLabel::Lhs));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                StmtChild::Atom(s) => Ok(s),
                _ => Err(CstError::UnexpectedChildType { label: "lhs" }),
            },
            _ => Err(CstError::ChildCount {
                label: "lhs",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(StmtLabel::Lhs))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `lhs`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_lhs(&self) -> ::std::result::Result<::std::option::Option<&Shared<Atom>>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(StmtLabel::Lhs));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                StmtChild::Atom(s) => Ok(Some(s)),
                _ => Err(CstError::UnexpectedChildType { label: "lhs" }),
            },
            _ => Err(CstError::ChildCount {
                label: "lhs",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(StmtLabel::Lhs))
                    .count(),
            }),
        }
    }

    /// Append a child with label `lhs`, accepting `Atom` or `Shared<Atom>`.
    pub fn append_lhs(&mut self, child: impl ::std::convert::Into<Shared<Atom>>) {
        self.children.push((Some(StmtLabel::Lhs), StmtChild::Atom(child.into())));
    }

    /// Append multiple children with label `lhs`.
    pub fn extend_lhs(&mut self, children: impl ::std::iter::IntoIterator<Item = impl ::std::convert::Into<Shared<Atom>>>) {
        self.children.extend(children.into_iter().map(|c| (Some(StmtLabel::Lhs), StmtChild::Atom(c.into()))));
    }

    /// Return an iterator over `Shared<Atom>` children labelled `rhs`.
    ///
    /// Off-type variants stored under the `rhs` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_rhs(&self) -> impl ::std::iter::Iterator<Item = &Shared<Atom>> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(StmtLabel::Rhs))
            .filter_map(|(_, child)| match child {
                StmtChild::Atom(s) => Some(s),
                _ => None,
            })
    }

    /// Return the single child labelled `rhs`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_rhs(&self) -> ::std::result::Result<&Shared<Atom>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(StmtLabel::Rhs));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                StmtChild::Atom(s) => Ok(s),
                _ => Err(CstError::UnexpectedChildType { label: "rhs" }),
            },
            _ => Err(CstError::ChildCount {
                label: "rhs",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(StmtLabel::Rhs))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `rhs`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_rhs(&self) -> ::std::result::Result<::std::option::Option<&Shared<Atom>>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(StmtLabel::Rhs));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                StmtChild::Atom(s) => Ok(Some(s)),
                _ => Err(CstError::UnexpectedChildType { label: "rhs" }),
            },
            _ => Err(CstError::ChildCount {
                label: "rhs",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(StmtLabel::Rhs))
                    .count(),
            }),
        }
    }

    /// Append a child with label `rhs`, accepting `Atom` or `Shared<Atom>`.
    pub fn append_rhs(&mut self, child: impl ::std::convert::Into<Shared<Atom>>) {
        self.children.push((Some(StmtLabel::Rhs), StmtChild::Atom(child.into())));
    }

    /// Append multiple children with label `rhs`.
    pub fn extend_rhs(&mut self, children: impl ::std::iter::IntoIterator<Item = impl ::std::convert::Into<Shared<Atom>>>) {
        self.children.extend(children.into_iter().map(|c| (Some(StmtLabel::Rhs), StmtChild::Atom(c.into()))));
    }

    /// Return the child labelled `lhs`.
    ///
    /// Panics unless exactly one is present; use `child_lhs` for the checked form.
    pub fn lhs(&self) -> &Shared<Atom> {
        self.child_lhs()
            .unwrap_or_else(|e| panic!("Stmt.lhs: {e}"))
    }

    /// Return the child labelled `rhs`.
    ///
    /// Panics unless exactly one is present; use `child_rhs` for the checked form.
    pub fn rhs(&self) -> &Shared<Atom> {
        self.child_rhs()
            .unwrap_or_else(|e| panic!("Stmt.rhs: {e}"))
    }

    /// Insert a child at `index` (Vec::insert semantics: panics if index > len).
    ///
    /// Python-facing clamping is in the `insert` pymethod; native callers must
    /// bounds-check. Unlike `list.insert`, Vec::insert panics on out-of-bounds.
    pub fn insert_child(&mut self, index: usize, label: ::std::option::Option<StmtLabel>, child: StmtChild) {
        self.children.insert(index, (label, child));
    }

    /// Remove and return the child at `index` (Vec::remove semantics: panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `remove_at` pymethod.
    pub fn remove_child(&mut self, index: usize) -> (::std::option::Option<StmtLabel>, StmtChild) {
        self.children.remove(index)
    }

    /// Replace the child at `index`, returning the old entry (panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `replace_at` pymethod.
    pub fn replace_child(
        &mut self, index: usize, label: ::std::option::Option<StmtLabel>, child: StmtChild,
    ) -> (::std::option::Option<StmtLabel>, StmtChild) {
        std::mem::replace(&mut self.children[index], (label, child))
    }

    /// Remove all children.
    pub fn clear_children(&mut self) {
        self.children.clear();
    }
}

#[cfg(feature = "python")]
#[pyclass(frozen, weakref, name = "Stmt")]
pub struct PyStmt {
    // Not pub: all external access goes through shared() or to_py_canonical().
    // A pub field would let mixed-app Rust code construct an unregistered handle
    // (Py::new(py, PyFoo { inner: s.clone() })), silently breaking is-stability.
    inner: Shared<Stmt>,
}

#[cfg(feature = "python")]
impl PyStmt {
    /// Return a reference to the inner `Shared<Stmt>`.
    pub fn shared(&self) -> &Shared<Stmt> {
        &self.inner
    }

    /// Wrap a `Shared<Stmt>` into a canonical Python handle,
    /// looking up the registry first so the same handle is returned
    /// for the same `Shared` allocation.
    pub fn to_py_canonical(py: Python<'_>, s: &Shared<Stmt>) -> pyo3::PyResult<Py<PyStmt>> {
        let addr = s.arc_ptr();
        let obj = registry::get_or_insert_with(py, addr, || {
            let handle = PyStmt { inner: s.clone() };
            Py::new(py, handle).map(|p| p.into_any())
        })?;
        obj.bind(py).cast::<PyStmt>().map(|b| b.clone().unbind()).map_err(|e| e.into())
    }

    /// Snapshot the children carrying `label` into a new Python list.
    fn py_children_snapshot(&self, py: Python<'_>, label: &StmtLabel) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Lock scope: filter by label under the read guard, cloning only matching
        // children (Arc bump or Span copy each); drop the guard before to_pyobject,
        // which performs Python work that must not happen while a node lock is held.
        let matching: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.iter()
                .filter(|(lbl, _)| lbl.as_ref() == Some(label))
                .map(|(_, child)| child.clone())
                .collect()
        };
        let result = pyo3::types::PyList::empty(py);
        for child in &matching {
            result.append(child.to_pyobject(py)?)?;
        }
        Ok(result.unbind())
    }
}

#[cfg(feature = "python")]
#[pymethods]
impl PyStmt {
    #[new]
    #[pyo3(signature = (*, span = None))]
    fn new(py: Python<'_>, span: ::std::option::Option<&Bound<'_, pyo3::PyAny>>) -> pyo3::PyResult<Py<PyStmt>> {
        let native_span = match span {
            Some(s) => extract_span(py, s)?,
            None => Span::unknown(),
        };
        let data = Stmt {
            span: native_span,
            children: ::std::vec::Vec::new(),
        };
        let shared = Shared::new(data);
        let addr = shared.arc_ptr();
        let handle = PyStmt { inner: shared };
        let py_obj = Py::new(py, handle)?;
        // Register as canonical — fresh Shared, no alias can exist yet.
        registry::force_register(py, addr, py_obj.bind(py))?;
        Ok(py_obj)
    }

    #[getter]
    fn span(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Snapshot the span under the read lock, then drop the guard before
        // calling span_to_pyobject — which performs Python work (Py::new or
        // Python method calls) that must not happen while a node lock is held.
        let span = self.inner.read().span.clone();
        span_to_pyobject(py, &span)
    }

    #[setter]
    fn set_span(&self, py: Python<'_>, value: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        self.inner.write().span = extract_span(py, value)?;
        Ok(())
    }

    #[getter]
    fn kind(&self) -> NodeKind {
        NodeKind::Stmt
    }

    #[classattr]
    #[allow(non_snake_case)]
    fn Label(py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        Ok(<StmtLabel as pyo3::PyTypeInfo>::type_object(py).into_any().unbind())
    }

    #[getter]
    fn children(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Snapshot the children vec (Arc clones for node children — O(n) refcount bumps).
        // Lock scope: acquire read, snapshot, release before touching Python.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.clone()
        };
        let result = pyo3::types::PyList::empty(py);
        for (label, child) in &snapshot {
            let label_obj: Py<pyo3::PyAny> = match label {
                None => py.None(),
                Some(lbl) => lbl.clone().into_pyobject(py)?.into_any().unbind(),
            };
            let child_obj = child.to_pyobject(py)?;
            let tup = pyo3::types::PyTuple::new(py, [label_obj, child_obj])?;
            result.append(tup)?;
        }
        Ok(result.unbind())
    }

    #[pyo3(signature = (child, label = None))]
    fn append(
        &self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>, label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<StmtLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| StmtLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Stmt.append: label argument is not a Stmt_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = StmtChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((native_label, native_child));
        Ok(())
    }

    #[pyo3(signature = (children, label = None))]
    fn extend(
        &self,
        py: Python<'_>,
        children: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<StmtLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| StmtLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Stmt.extend: label argument is not a Stmt_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must leave
        // the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = StmtChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((native_label.clone(), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn extend_children(&self, _py: Python<'_>, other: &PyStmt) -> pyo3::PyResult<()> {
        // Snapshot other's children first: the read guard is dropped at the end of
        // this block, so the write lock below is safe even when self and other are
        // the same node (self-extend). No ptr_eq call is needed here — the snapshot
        // approach handles self-extend structurally.
        // Lock scope: hold read only long enough to clone the Arc-based children vec.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = other.inner.read();
            guard.children.clone()
        };
        // Node-typed children are pushed directly as Shared<T> values.  Registry
        // consistency is maintained lazily: wrap-out registers on first Python read
        // via get_or_insert_with (registry.rs).  Eagerly registering here would be
        // a no-op — the WeakValueDictionary would evict handles held by nothing.
        self.inner.write().children.extend(snapshot);
        Ok(())
    }

    fn child(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: read len and clone at most the single entry under the guard;
        // drop the guard before any Python work (object conversion, exception raise).
        let (n, entry) = {
            let guard = self.inner.read();
            let n = guard.children.len();
            let entry = if n == 1 { Some(guard.children[0].clone()) } else { None };
            (n, entry)
        };
        let Some((label, child)) = entry else {
            return Err(PyValueError::new_err(format!(
                "Expected one child but have {n}"
            )));
        };
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn insert(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<StmtLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| StmtLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Stmt.insert: label argument is not a Stmt_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = StmtChild::extract_from_pyobject(py, child, &span_type)?;
        // Index normalization via operator.index (PyNumber_Index semantics).
        // This raises TypeError (not AttributeError) for non-indexable inputs, matching Python's
        // operator.index contract. Must be done BEFORE taking any lock.
        // Overflow by sign: positive overflow clamps to len; negative overflow clamps to 0.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path for the common exact-int case; fall back to sign-based Python call for beyond-i64.
        let (is_negative_big, raw_i64) = if let Ok(i) = raw_idx.extract::<i64>() {
            (false, Some(i))
        } else {
            // Beyond i64: use Python __lt__ to determine sign.  The lt call is still outside
            // any lock, so lock discipline is maintained.
            let neg = raw_idx.lt(0i64)?;
            (neg, None)
        };
        // Now take a single write lock for the entire len-read + clamp + insert sequence.
        let mut guard = self.inner.write();
        let n = guard.children.len();
        let clamped: usize = match raw_i64 {
            Some(i) if i < 0 => {
                let normalized = n as i64 + i;
                if normalized < 0 { 0 } else { normalized as usize }
            }
            Some(i) => {
                let u = i as usize;
                if u > n { n } else { u }
            }
            None => if is_negative_big { 0 } else { n },
        };
        guard.children.insert(clamped, (native_label, native_child));
        Ok(())
    }

    fn remove_at(&self, py: Python<'_>, index: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Capture the caller's original string representation BEFORE normalization,
        // so error messages show the original value (e.g. `True` not `1`).
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError (not AttributeError) for
        // non-indexable inputs, matching Python's operator.index contract.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path: extract i64. Beyond i64 is always OOB for real trees.
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + Vec::remove atomically (no TOCTOU).
        // On OOB, capture n and return Err after releasing the guard.
        let result: ::std::result::Result<_, usize> = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            match resolved {
                Some(idx) => Ok(guard.children.remove(idx)),
                None => Err(n),
            }
        };
        let (label, child) = result.map_err(|n| {
            PyIndexError::new_err(format!(
                "Stmt.remove_at: index {} out of range ({} children)",
                orig_str, n
            ))
        })?;
        // Python wrap-out happens after the guard is released.
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn replace_at(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<StmtLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| StmtLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Stmt.replace_at: label argument is not a Stmt_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = StmtChild::extract_from_pyobject(py, child, &span_type)?;
        // Capture the caller's original string representation BEFORE normalization.
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError for non-indexable inputs.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + mem::replace atomically (no TOCTOU).
        let old = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            let idx = match resolved {
                Some(i) => i,
                None => {
                    return Err(PyIndexError::new_err(format!(
                        "Stmt.replace_at: index {} out of range ({} children)",
                        orig_str, n
                    )));
                }
            };
            std::mem::replace(&mut guard.children[idx], (native_label, native_child))
        };
        // Drop old entry outside the lock to avoid recursive lock acquisition
        // if the child's drop chain re-enters Python.
        drop(old);
        Ok(())
    }

    fn clear(&self, _py: Python<'_>) -> pyo3::PyResult<()> {
        let old = {
            let mut guard = self.inner.write();
            std::mem::take(&mut guard.children)
        };
        // Drop old entries outside the lock.
        drop(old);
        Ok(())
    }

    fn append_lhs(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = StmtChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(StmtLabel::Lhs), native_child));
        Ok(())
    }

    fn extend_lhs(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = StmtChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(StmtLabel::Lhs), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_lhs(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &StmtLabel::Lhs)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_lhs(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(StmtLabel::Lhs) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one lhs child but have {count}"
            )));
        }
        first.expect("invariant: Stmt.child_lhs: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_lhs(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(StmtLabel::Lhs) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one lhs child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn append_rhs(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = StmtChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(StmtLabel::Rhs), native_child));
        Ok(())
    }

    fn extend_rhs(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = StmtChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(StmtLabel::Rhs), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_rhs(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &StmtLabel::Rhs)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_rhs(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(StmtLabel::Rhs) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one rhs child but have {count}"
            )));
        }
        first.expect("invariant: Stmt.child_rhs: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_rhs(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(StmtLabel::Rhs) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one rhs child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn lhs(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        self.child_lhs(py)
    }

    fn rhs(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        self.child_rhs(py)
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if !other.is_instance_of::<PyStmt>() {
            return Ok(py.NotImplemented());
        }
        let other_handle: pyo3::PyRef<PyStmt> = other.extract()?;
        // Delegate to Shared<T>::PartialEq which applies the ptr_eq short-circuit
        // (avoids same-lock re-entry on `x == x`) then deep structural comparison.
        let eq = self.inner == other_handle.inner;
        Ok(eq.into_pyobject(py)?.to_owned().unbind().into_any())
    }

    fn __hash__(&self) -> pyo3::PyResult<isize> {
        Err(PyTypeError::new_err("unhashable type: 'Stmt'"))
    }

    fn __repr__(&self, _py: Python<'_>) -> ::std::string::String {
        let guard = self.inner.read();
        let span_repr = format!("Span(start={}, end={})", guard.span.start(), guard.span.end());
        let children_len = guard.children.len();
        format!(
            "Stmt(span={span_repr}, children=[<{children_len} child(ren)>])"
        )
    }

}

// ───────────────────────────────────────────────────────────────────────────
// ItemsLabel
// ───────────────────────────────────────────────────────────────────────────

/// Label discriminant enum for children of this node type.
///
/// Python-visible name is `Items_Label` (preserved for compatibility).
/// Rust consumers use the CamelCase `ItemsLabel` name.
#[cfg(feature = "python")]
#[pyclass(frozen, from_py_object, name = "Items_Label")]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ItemsLabel {
    #[pyo3(name = "ITEM")]
    Item,
}

#[cfg(not(feature = "python"))]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ItemsLabel {
    Item,
}

#[cfg(feature = "python")]
#[pymethods]
impl ItemsLabel {
    fn __repr__(&self) -> &'static str {
        match self {
            ItemsLabel::Item => "Items.Label.ITEM",
        }
    }

    #[getter]
    fn _fltk_canonical_name(&self) -> &'static str {
        self.__repr__()
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if let Ok(other_kind) = other.extract::<ItemsLabel>() {
            return Ok((self == &other_kind).into_pyobject(py)?.to_owned().unbind().into_any());
        }
        if let Ok(cn) = other.getattr(pyo3::intern!(py, "_fltk_canonical_name")) {
            if let Ok(cn_str) = cn.extract::<&str>() {
                return Ok((self.__repr__() == cn_str).into_pyobject(py)?.to_owned().unbind().into_any());
            }
        }
        Ok(py.NotImplemented())
    }

    fn __hash__(&self, py: Python<'_>) -> pyo3::PyResult<isize> {
        pyo3::types::PyAnyMethods::hash(
            pyo3::types::PyString::new(py, self.__repr__()).as_any()
        )
    }
}

#[cfg(feature = "python")]
impl ItemsLabel {
    /// The variant with this cross-backend canonical name, if any.
    fn from_canonical_name(name: &str) -> ::std::option::Option<Self> {
        match name {
            "Items.Label.ITEM" => Some(ItemsLabel::Item),
            _ => None,
        }
    }
}

/// Child value enum for `Items` nodes.
///
/// Node-typed variants hold `Shared<T>` (`Arc<RwLock<T>>`); `Clone` is shallow
/// (increments the reference count, does not copy the node).
#[derive(Clone, Debug)]
pub enum ItemsChild {
    Atom(Shared<Atom>),
}

impl ::std::cmp::PartialEq for ItemsChild {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (ItemsChild::Atom(a), ItemsChild::Atom(b)) => a == b,
        }
    }
}

impl ItemsChild {
    fn into_drop_item(self) -> ::std::option::Option<DropWorklistItem> {
        match self {
            Self::Atom(s) => Some(DropWorklistItem::Atom(s)),
        }
    }

    /// Shallow structural equality for one child pair.
    /// Span pair: compare directly. Node pair: ptr_eq short-circuit (skip enqueue)
    /// or enqueue for the worklist. Variant mismatch: return false.
    fn eq_shallow_enqueue(&self, other: &Self, worklist: &mut ::std::vec::Vec<EqWorklistItem>) -> bool {
        match (self, other) {
            (Self::Atom(a), Self::Atom(b)) => {
                if !a.ptr_eq(b) {
                    worklist.push(EqWorklistItem::Atom(a.clone(), b.clone()));
                }
                true
            }
        }
    }
}

#[cfg(feature = "python")]
impl ItemsChild {
    fn to_pyobject(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        match self {
            Self::Atom(shared) => {
                let addr = shared.arc_ptr();
                registry::get_or_insert_with(py, addr, || {
                    let handle = PyAtom { inner: shared.clone() };
                    Py::new(py, handle).map(|p| p.into_any())
                })
            }
        }
    }

    fn extract_from_pyobject(
        py: Python<'_>,
        obj: &Bound<'_, pyo3::PyAny>,
        _span_type: &Bound<'_, pyo3::types::PyType>,
    ) -> pyo3::PyResult<Self> {
        if obj.is_instance_of::<PyAtom>() {
            let handle: pyo3::PyRef<PyAtom> = obj.extract()?;
            let shared = handle.inner.clone();
            let addr = shared.arc_ptr();
            // Hand-in: register this Python handle as canonical for its Shared.
            drop(handle); // release the PyRef before calling Python
            // Propagate registry errors: a swallowed Err here would leave the
            // handle unregistered, causing the next wrap-out to mint a different
            // object and silently break is-stability.
            registry::register_if_absent(py, addr, obj)?;
            return Ok(Self::Atom(shared));
        }
        let rejected_type = obj.get_type();
        Err(pyo3::exceptions::PyTypeError::new_err(format!(
            "Items: unsupported child type {}.{}",
            rejected_type.module()?,
            rejected_type.qualname()?
        )))
    }
}

// ───────────────────────────────────────────────────────────────────────────
// Items
// ───────────────────────────────────────────────────────────────────────────

/// CST data struct for `Items`. See [`fltk_cst_core::Shared`] for clone/equality/reference semantics.
///
/// `Debug` output is non-recursive: prints span + child count only. Traverse via `children()` to inspect subtrees.
/// Teardown is iterative: bounded stack at any depth.
/// Equality is iterative: bounded stack at any depth.
#[derive(Clone)]
pub struct Items {
    // Not pub: use span() / children() / push_child() — the stable accessor API.
    // Direct field access bypasses any future validation logic on setters.
    span: Span,
    children: ::std::vec::Vec<(::std::option::Option<ItemsLabel>, ItemsChild)>,
}

// Manual Debug: prints span + child COUNT, never recursing into children.
// A derived Debug would recurse through Shared<T> children with no depth
// bound; tree depth is attacker-controlled for parsers over untrusted
// input, so `{:?}` on a deep tree would abort the process (stack
// exhaustion, uncatchable). Mirrors the Python __repr__'s content.
impl fmt::Debug for Items {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Items")
            .field("span", &self.span)
            .field("children", &format_args!("<{} child(ren)>", self.children.len()))
            .finish()
    }
}

// Iterative Drop: derived drop glue would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Drains the subtree via a worklist instead.
impl ::std::ops::Drop for Items {
    fn drop(&mut self) {
        if self.children.is_empty() {
            return; // also the recursion terminator for nodes drained by the worklist
        }
        // Worklist is allocated lazily: Vec::new() does not heap-allocate until
        // the first push.  drain_into pushes only when it steals (count == 1).
        // In the common backtracking case (shared/memoized children) no steal
        // occurs and no allocation happens.  Owned deep chains allocate once.
        let mut worklist: ::std::vec::Vec<DropWorklistItem> = ::std::vec::Vec::new();
        for (_, child) in self.children.drain(..) {
            if let Some(item) = child.into_drop_item() {
                item.drain_into(&mut worklist);
            }
        }
        while let Some(item) = worklist.pop() {
            item.drain_into(&mut worklist);
        }
    }
}

// Iterative PartialEq: the recursive version would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Uses an explicit worklist of node pairs.
impl ::std::cmp::PartialEq for Items {
    fn eq(&self, other: &Self) -> bool {
        if self.span != other.span || self.children.len() != other.children.len() {
            return false;
        }
        // Worklist allocated lazily (Vec::new does not heap-allocate until
        // first push); shallow trees and all-ptr_eq children never allocate.
        let mut worklist: ::std::vec::Vec<EqWorklistItem> = ::std::vec::Vec::new();
        for ((la, ca), (lb, cb)) in self.children.iter().zip(other.children.iter()) {
            if la != lb || !ca.eq_shallow_enqueue(cb, &mut worklist) {
                return false;
            }
        }
        while let Some(item) = worklist.pop() {
            if !item.compare(&mut worklist) {
                return false;
            }
        }
        true
    }
}

impl Items {
    /// Construct a node with the given span and no children. GIL-free.
    pub fn new(span: Span) -> Self {
        Items {
            span,
            children: ::std::vec::Vec::new(),
        }
    }

    /// Return the [`NodeKind`] discriminant for this node type.
    pub fn kind(&self) -> NodeKind {
        NodeKind::Items
    }

    /// Return a reference to the stored [`Span`].
    pub fn span(&self) -> &Span {
        &self.span
    }

    /// Replace the node's span.
    pub fn set_span(&mut self, span: Span) {
        self.span = span;
    }

    /// Return a slice of all children (unfiltered).
    ///
    /// Each entry is `(label, child)`. Use the per-label accessors
    /// (`children_<lbl>`, `child_<lbl>`, `maybe_<lbl>`) for type-safe access.
    pub fn children(&self) -> &[(::std::option::Option<ItemsLabel>, ItemsChild)] {
        self.children.as_slice()
    }

    /// Push a child onto the children `Vec`.
    ///
    /// No type-checking is performed: any child variant may be stored under
    /// any label. Per-label typed mutators (`append_<lbl>`, `extend_<lbl>`)
    /// provide type-constrained alternatives.
    pub fn push_child(&mut self, label: ::std::option::Option<ItemsLabel>, child: ItemsChild) {
        self.children.push((label, child));
    }

    /// Return the single child (any label), or `Err` if there is not exactly one.
    ///
    /// Mirrors the Python `child()` method: count violation → `CstError::ChildCount`.
    pub fn child(&self) -> ::std::result::Result<&(::std::option::Option<ItemsLabel>, ItemsChild), CstError> {
        match self.children.as_slice() {
            [single] => Ok(single),
            slice => Err(CstError::ChildCount {
                label: "<any>",
                expected: "1",
                found: slice.len(),
            }),
        }
    }

    /// Copy all children from `other` into `self`, sharing the `Shared<T>` arcs.
    ///
    /// Children are appended (Arc reference-count bumps, not deep copies),
    /// matching the Python backend's reference-copy behavior. Labels are preserved.
    ///
    /// The borrow checker prevents `self.extend_children(self)` at the data-struct
    /// level (`&mut` + `&` of the same value don't coexist). For self-extend from
    /// Python, the handle pymethod handles it via snapshotting.
    pub fn extend_children(&mut self, other: &Self) {
        self.children.extend(other.children.iter().cloned());
    }

    /// Return an iterator over `Shared<Atom>` children labelled `item`.
    ///
    /// Off-type variants stored under the `item` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_item(&self) -> impl ::std::iter::Iterator<Item = &Shared<Atom>> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(ItemsLabel::Item))
            .map(|(_, child)| match child { ItemsChild::Atom(s) => s })
    }

    /// Return the single child labelled `item`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_item(&self) -> ::std::result::Result<&Shared<Atom>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(ItemsLabel::Item));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                ItemsChild::Atom(s) => Ok(s),
            },
            _ => Err(CstError::ChildCount {
                label: "item",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(ItemsLabel::Item))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `item`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_item(&self) -> ::std::result::Result<::std::option::Option<&Shared<Atom>>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(ItemsLabel::Item));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                ItemsChild::Atom(s) => Ok(Some(s)),
            },
            _ => Err(CstError::ChildCount {
                label: "item",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(ItemsLabel::Item))
                    .count(),
            }),
        }
    }

    /// Append a child with label `item`, accepting `Atom` or `Shared<Atom>`.
    pub fn append_item(&mut self, child: impl ::std::convert::Into<Shared<Atom>>) {
        self.children.push((Some(ItemsLabel::Item), ItemsChild::Atom(child.into())));
    }

    /// Append multiple children with label `item`.
    pub fn extend_item(&mut self, children: impl ::std::iter::IntoIterator<Item = impl ::std::convert::Into<Shared<Atom>>>) {
        self.children.extend(children.into_iter().map(|c| (Some(ItemsLabel::Item), ItemsChild::Atom(c.into()))));
    }

    /// Return an iterator over the children labelled `item`.
    ///
    /// Arity-named alias of `children_item`.
    pub fn item(&self) -> impl ::std::iter::Iterator<Item = &Shared<Atom>> + '_ {
        self.children_item()
    }

    /// Insert a child at `index` (Vec::insert semantics: panics if index > len).
    ///
    /// Python-facing clamping is in the `insert` pymethod; native callers must
    /// bounds-check. Unlike `list.insert`, Vec::insert panics on out-of-bounds.
    pub fn insert_child(&mut self, index: usize, label: ::std::option::Option<ItemsLabel>, child: ItemsChild) {
        self.children.insert(index, (label, child));
    }

    /// Remove and return the child at `index` (Vec::remove semantics: panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `remove_at` pymethod.
    pub fn remove_child(&mut self, index: usize) -> (::std::option::Option<ItemsLabel>, ItemsChild) {
        self.children.remove(index)
    }

    /// Replace the child at `index`, returning the old entry (panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `replace_at` pymethod.
    pub fn replace_child(
        &mut self, index: usize, label: ::std::option::Option<ItemsLabel>, child: ItemsChild,
    ) -> (::std::option::Option<ItemsLabel>, ItemsChild) {
        std::mem::replace(&mut self.children[index], (label, child))
    }

    /// Remove all children.
    pub fn clear_children(&mut self) {
        self.children.clear();
    }
}

#[cfg(feature = "python")]
#[pyclass(frozen, weakref, name = "Items")]
pub struct PyItems {
    // Not pub: all external access goes through shared() or to_py_canonical().
    // A pub field would let mixed-app Rust code construct an unregistered handle
    // (Py::new(py, PyFoo { inner: s.clone() })), silently breaking is-stability.
    inner: Shared<Items>,
}

#[cfg(feature = "python")]
impl PyItems {
    /// Return a reference to the inner `Shared<Items>`.
    pub fn shared(&self) -> &Shared<Items> {
        &self.inner
    }

    /// Wrap a `Shared<Items>` into a canonical Python handle,
    /// looking up the registry first so the same handle is returned
    /// for the same `Shared` allocation.
    pub fn to_py_canonical(py: Python<'_>, s: &Shared<Items>) -> pyo3::PyResult<Py<PyItems>> {
        let addr = s.arc_ptr();
        let obj = registry::get_or_insert_with(py, addr, || {
            let handle = PyItems { inner: s.clone() };
            Py::new(py, handle).map(|p| p.into_any())
        })?;
        obj.bind(py).cast::<PyItems>().map(|b| b.clone().unbind()).map_err(|e| e.into())
    }

    /// Snapshot the children carrying `label` into a new Python list.
    fn py_children_snapshot(&self, py: Python<'_>, label: &ItemsLabel) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Lock scope: filter by label under the read guard, cloning only matching
        // children (Arc bump or Span copy each); drop the guard before to_pyobject,
        // which performs Python work that must not happen while a node lock is held.
        let matching: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.iter()
                .filter(|(lbl, _)| lbl.as_ref() == Some(label))
                .map(|(_, child)| child.clone())
                .collect()
        };
        let result = pyo3::types::PyList::empty(py);
        for child in &matching {
            result.append(child.to_pyobject(py)?)?;
        }
        Ok(result.unbind())
    }
}

#[cfg(feature = "python")]
#[pymethods]
impl PyItems {
    #[new]
    #[pyo3(signature = (*, span = None))]
    fn new(py: Python<'_>, span: ::std::option::Option<&Bound<'_, pyo3::PyAny>>) -> pyo3::PyResult<Py<PyItems>> {
        let native_span = match span {
            Some(s) => extract_span(py, s)?,
            None => Span::unknown(),
        };
        let data = Items {
            span: native_span,
            children: ::std::vec::Vec::new(),
        };
        let shared = Shared::new(data);
        let addr = shared.arc_ptr();
        let handle = PyItems { inner: shared };
        let py_obj = Py::new(py, handle)?;
        // Register as canonical — fresh Shared, no alias can exist yet.
        registry::force_register(py, addr, py_obj.bind(py))?;
        Ok(py_obj)
    }

    #[getter]
    fn span(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Snapshot the span under the read lock, then drop the guard before
        // calling span_to_pyobject — which performs Python work (Py::new or
        // Python method calls) that must not happen while a node lock is held.
        let span = self.inner.read().span.clone();
        span_to_pyobject(py, &span)
    }

    #[setter]
    fn set_span(&self, py: Python<'_>, value: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        self.inner.write().span = extract_span(py, value)?;
        Ok(())
    }

    #[getter]
    fn kind(&self) -> NodeKind {
        NodeKind::Items
    }

    #[classattr]
    #[allow(non_snake_case)]
    fn Label(py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        Ok(<ItemsLabel as pyo3::PyTypeInfo>::type_object(py).into_any().unbind())
    }

    #[getter]
    fn children(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Snapshot the children vec (Arc clones for node children — O(n) refcount bumps).
        // Lock scope: acquire read, snapshot, release before touching Python.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.clone()
        };
        let result = pyo3::types::PyList::empty(py);
        for (label, child) in &snapshot {
            let label_obj: Py<pyo3::PyAny> = match label {
                None => py.None(),
                Some(lbl) => lbl.clone().into_pyobject(py)?.into_any().unbind(),
            };
            let child_obj = child.to_pyobject(py)?;
            let tup = pyo3::types::PyTuple::new(py, [label_obj, child_obj])?;
            result.append(tup)?;
        }
        Ok(result.unbind())
    }

    #[pyo3(signature = (child, label = None))]
    fn append(
        &self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>, label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<ItemsLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| ItemsLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Items.append: label argument is not a Items_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = ItemsChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((native_label, native_child));
        Ok(())
    }

    #[pyo3(signature = (children, label = None))]
    fn extend(
        &self,
        py: Python<'_>,
        children: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<ItemsLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| ItemsLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Items.extend: label argument is not a Items_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must leave
        // the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = ItemsChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((native_label.clone(), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn extend_children(&self, _py: Python<'_>, other: &PyItems) -> pyo3::PyResult<()> {
        // Snapshot other's children first: the read guard is dropped at the end of
        // this block, so the write lock below is safe even when self and other are
        // the same node (self-extend). No ptr_eq call is needed here — the snapshot
        // approach handles self-extend structurally.
        // Lock scope: hold read only long enough to clone the Arc-based children vec.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = other.inner.read();
            guard.children.clone()
        };
        // Node-typed children are pushed directly as Shared<T> values.  Registry
        // consistency is maintained lazily: wrap-out registers on first Python read
        // via get_or_insert_with (registry.rs).  Eagerly registering here would be
        // a no-op — the WeakValueDictionary would evict handles held by nothing.
        self.inner.write().children.extend(snapshot);
        Ok(())
    }

    fn child(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: read len and clone at most the single entry under the guard;
        // drop the guard before any Python work (object conversion, exception raise).
        let (n, entry) = {
            let guard = self.inner.read();
            let n = guard.children.len();
            let entry = if n == 1 { Some(guard.children[0].clone()) } else { None };
            (n, entry)
        };
        let Some((label, child)) = entry else {
            return Err(PyValueError::new_err(format!(
                "Expected one child but have {n}"
            )));
        };
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn insert(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<ItemsLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| ItemsLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Items.insert: label argument is not a Items_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = ItemsChild::extract_from_pyobject(py, child, &span_type)?;
        // Index normalization via operator.index (PyNumber_Index semantics).
        // This raises TypeError (not AttributeError) for non-indexable inputs, matching Python's
        // operator.index contract. Must be done BEFORE taking any lock.
        // Overflow by sign: positive overflow clamps to len; negative overflow clamps to 0.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path for the common exact-int case; fall back to sign-based Python call for beyond-i64.
        let (is_negative_big, raw_i64) = if let Ok(i) = raw_idx.extract::<i64>() {
            (false, Some(i))
        } else {
            // Beyond i64: use Python __lt__ to determine sign.  The lt call is still outside
            // any lock, so lock discipline is maintained.
            let neg = raw_idx.lt(0i64)?;
            (neg, None)
        };
        // Now take a single write lock for the entire len-read + clamp + insert sequence.
        let mut guard = self.inner.write();
        let n = guard.children.len();
        let clamped: usize = match raw_i64 {
            Some(i) if i < 0 => {
                let normalized = n as i64 + i;
                if normalized < 0 { 0 } else { normalized as usize }
            }
            Some(i) => {
                let u = i as usize;
                if u > n { n } else { u }
            }
            None => if is_negative_big { 0 } else { n },
        };
        guard.children.insert(clamped, (native_label, native_child));
        Ok(())
    }

    fn remove_at(&self, py: Python<'_>, index: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Capture the caller's original string representation BEFORE normalization,
        // so error messages show the original value (e.g. `True` not `1`).
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError (not AttributeError) for
        // non-indexable inputs, matching Python's operator.index contract.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path: extract i64. Beyond i64 is always OOB for real trees.
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + Vec::remove atomically (no TOCTOU).
        // On OOB, capture n and return Err after releasing the guard.
        let result: ::std::result::Result<_, usize> = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            match resolved {
                Some(idx) => Ok(guard.children.remove(idx)),
                None => Err(n),
            }
        };
        let (label, child) = result.map_err(|n| {
            PyIndexError::new_err(format!(
                "Items.remove_at: index {} out of range ({} children)",
                orig_str, n
            ))
        })?;
        // Python wrap-out happens after the guard is released.
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn replace_at(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<ItemsLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| ItemsLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Items.replace_at: label argument is not a Items_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = ItemsChild::extract_from_pyobject(py, child, &span_type)?;
        // Capture the caller's original string representation BEFORE normalization.
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError for non-indexable inputs.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + mem::replace atomically (no TOCTOU).
        let old = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            let idx = match resolved {
                Some(i) => i,
                None => {
                    return Err(PyIndexError::new_err(format!(
                        "Items.replace_at: index {} out of range ({} children)",
                        orig_str, n
                    )));
                }
            };
            std::mem::replace(&mut guard.children[idx], (native_label, native_child))
        };
        // Drop old entry outside the lock to avoid recursive lock acquisition
        // if the child's drop chain re-enters Python.
        drop(old);
        Ok(())
    }

    fn clear(&self, _py: Python<'_>) -> pyo3::PyResult<()> {
        let old = {
            let mut guard = self.inner.write();
            std::mem::take(&mut guard.children)
        };
        // Drop old entries outside the lock.
        drop(old);
        Ok(())
    }

    fn append_item(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = ItemsChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(ItemsLabel::Item), native_child));
        Ok(())
    }

    fn extend_item(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = ItemsChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(ItemsLabel::Item), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_item(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &ItemsLabel::Item)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_item(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(ItemsLabel::Item) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one item child but have {count}"
            )));
        }
        first.expect("invariant: Items.child_item: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_item(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(ItemsLabel::Item) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one item child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn item(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        self.py_children_snapshot(py, &ItemsLabel::Item)
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if !other.is_instance_of::<PyItems>() {
            return Ok(py.NotImplemented());
        }
        let other_handle: pyo3::PyRef<PyItems> = other.extract()?;
        // Delegate to Shared<T>::PartialEq which applies the ptr_eq short-circuit
        // (avoids same-lock re-entry on `x == x`) then deep structural comparison.
        let eq = self.inner == other_handle.inner;
        Ok(eq.into_pyobject(py)?.to_owned().unbind().into_any())
    }

    fn __hash__(&self) -> pyo3::PyResult<isize> {
        Err(PyTypeError::new_err("unhashable type: 'Items'"))
    }

    fn __repr__(&self, _py: Python<'_>) -> ::std::string::String {
        let guard = self.inner.read();
        let span_repr = format!("Span(start={}, end={})", guard.span.start(), guard.span.end());
        let children_len = guard.children.len();
        format!(
            "Items(span={span_repr}, children=[<{children_len} child(ren)>])"
        )
    }

}

// ───────────────────────────────────────────────────────────────────────────
// OptItemLabel
// ───────────────────────────────────────────────────────────────────────────

/// Label discriminant enum for children of this node type.
///
/// Python-visible name is `OptItem_Label` (preserved for compatibility).
/// Rust consumers use the CamelCase `OptItemLabel` name.
#[cfg(feature = "python")]
#[pyclass(frozen, from_py_object, name = "OptItem_Label")]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum OptItemLabel {
    #[pyo3(name = "ITEM")]
    Item,
}

#[cfg(not(feature = "python"))]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum OptItemLabel {
    Item,
}

#[cfg(feature = "python")]
#[pymethods]
impl OptItemLabel {
    fn __repr__(&self) -> &'static str {
        match self {
            OptItemLabel::Item => "OptItem.Label.ITEM",
        }
    }

    #[getter]
    fn _fltk_canonical_name(&self) -> &'static str {
        self.__repr__()
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if let Ok(other_kind) = other.extract::<OptItemLabel>() {
            return Ok((self == &other_kind).into_pyobject(py)?.to_owned().unbind().into_any());
        }
        if let Ok(cn) = other.getattr(pyo3::intern!(py, "_fltk_canonical_name")) {
            if let Ok(cn_str) = cn.extract::<&str>() {
                return Ok((self.__repr__() == cn_str).into_pyobject(py)?.to_owned().unbind().into_any());
            }
        }
        Ok(py.NotImplemented())
    }

    fn __hash__(&self, py: Python<'_>) -> pyo3::PyResult<isize> {
        pyo3::types::PyAnyMethods::hash(
            pyo3::types::PyString::new(py, self.__repr__()).as_any()
        )
    }
}

#[cfg(feature = "python")]
impl OptItemLabel {
    /// The variant with this cross-backend canonical name, if any.
    fn from_canonical_name(name: &str) -> ::std::option::Option<Self> {
        match name {
            "OptItem.Label.ITEM" => Some(OptItemLabel::Item),
            _ => None,
        }
    }
}

/// Child value enum for `OptItem` nodes.
///
/// Node-typed variants hold `Shared<T>` (`Arc<RwLock<T>>`); `Clone` is shallow
/// (increments the reference count, does not copy the node).
#[derive(Clone, Debug)]
pub enum OptItemChild {
    Atom(Shared<Atom>),
}

impl ::std::cmp::PartialEq for OptItemChild {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (OptItemChild::Atom(a), OptItemChild::Atom(b)) => a == b,
        }
    }
}

impl OptItemChild {
    fn into_drop_item(self) -> ::std::option::Option<DropWorklistItem> {
        match self {
            Self::Atom(s) => Some(DropWorklistItem::Atom(s)),
        }
    }

    /// Shallow structural equality for one child pair.
    /// Span pair: compare directly. Node pair: ptr_eq short-circuit (skip enqueue)
    /// or enqueue for the worklist. Variant mismatch: return false.
    fn eq_shallow_enqueue(&self, other: &Self, worklist: &mut ::std::vec::Vec<EqWorklistItem>) -> bool {
        match (self, other) {
            (Self::Atom(a), Self::Atom(b)) => {
                if !a.ptr_eq(b) {
                    worklist.push(EqWorklistItem::Atom(a.clone(), b.clone()));
                }
                true
            }
        }
    }
}

#[cfg(feature = "python")]
impl OptItemChild {
    fn to_pyobject(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        match self {
            Self::Atom(shared) => {
                let addr = shared.arc_ptr();
                registry::get_or_insert_with(py, addr, || {
                    let handle = PyAtom { inner: shared.clone() };
                    Py::new(py, handle).map(|p| p.into_any())
                })
            }
        }
    }

    fn extract_from_pyobject(
        py: Python<'_>,
        obj: &Bound<'_, pyo3::PyAny>,
        _span_type: &Bound<'_, pyo3::types::PyType>,
    ) -> pyo3::PyResult<Self> {
        if obj.is_instance_of::<PyAtom>() {
            let handle: pyo3::PyRef<PyAtom> = obj.extract()?;
            let shared = handle.inner.clone();
            let addr = shared.arc_ptr();
            // Hand-in: register this Python handle as canonical for its Shared.
            drop(handle); // release the PyRef before calling Python
            // Propagate registry errors: a swallowed Err here would leave the
            // handle unregistered, causing the next wrap-out to mint a different
            // object and silently break is-stability.
            registry::register_if_absent(py, addr, obj)?;
            return Ok(Self::Atom(shared));
        }
        let rejected_type = obj.get_type();
        Err(pyo3::exceptions::PyTypeError::new_err(format!(
            "OptItem: unsupported child type {}.{}",
            rejected_type.module()?,
            rejected_type.qualname()?
        )))
    }
}

// ───────────────────────────────────────────────────────────────────────────
// OptItem
// ───────────────────────────────────────────────────────────────────────────

/// CST data struct for `OptItem`. See [`fltk_cst_core::Shared`] for clone/equality/reference semantics.
///
/// `Debug` output is non-recursive: prints span + child count only. Traverse via `children()` to inspect subtrees.
/// Teardown is iterative: bounded stack at any depth.
/// Equality is iterative: bounded stack at any depth.
#[derive(Clone)]
pub struct OptItem {
    // Not pub: use span() / children() / push_child() — the stable accessor API.
    // Direct field access bypasses any future validation logic on setters.
    span: Span,
    children: ::std::vec::Vec<(::std::option::Option<OptItemLabel>, OptItemChild)>,
}

// Manual Debug: prints span + child COUNT, never recursing into children.
// A derived Debug would recurse through Shared<T> children with no depth
// bound; tree depth is attacker-controlled for parsers over untrusted
// input, so `{:?}` on a deep tree would abort the process (stack
// exhaustion, uncatchable). Mirrors the Python __repr__'s content.
impl fmt::Debug for OptItem {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("OptItem")
            .field("span", &self.span)
            .field("children", &format_args!("<{} child(ren)>", self.children.len()))
            .finish()
    }
}

// Iterative Drop: derived drop glue would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Drains the subtree via a worklist instead.
impl ::std::ops::Drop for OptItem {
    fn drop(&mut self) {
        if self.children.is_empty() {
            return; // also the recursion terminator for nodes drained by the worklist
        }
        // Worklist is allocated lazily: Vec::new() does not heap-allocate until
        // the first push.  drain_into pushes only when it steals (count == 1).
        // In the common backtracking case (shared/memoized children) no steal
        // occurs and no allocation happens.  Owned deep chains allocate once.
        let mut worklist: ::std::vec::Vec<DropWorklistItem> = ::std::vec::Vec::new();
        for (_, child) in self.children.drain(..) {
            if let Some(item) = child.into_drop_item() {
                item.drain_into(&mut worklist);
            }
        }
        while let Some(item) = worklist.pop() {
            item.drain_into(&mut worklist);
        }
    }
}

// Iterative PartialEq: the recursive version would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Uses an explicit worklist of node pairs.
impl ::std::cmp::PartialEq for OptItem {
    fn eq(&self, other: &Self) -> bool {
        if self.span != other.span || self.children.len() != other.children.len() {
            return false;
        }
        // Worklist allocated lazily (Vec::new does not heap-allocate until
        // first push); shallow trees and all-ptr_eq children never allocate.
        let mut worklist: ::std::vec::Vec<EqWorklistItem> = ::std::vec::Vec::new();
        for ((la, ca), (lb, cb)) in self.children.iter().zip(other.children.iter()) {
            if la != lb || !ca.eq_shallow_enqueue(cb, &mut worklist) {
                return false;
            }
        }
        while let Some(item) = worklist.pop() {
            if !item.compare(&mut worklist) {
                return false;
            }
        }
        true
    }
}

impl OptItem {
    /// Construct a node with the given span and no children. GIL-free.
    pub fn new(span: Span) -> Self {
        OptItem {
            span,
            children: ::std::vec::Vec::new(),
        }
    }

    /// Return the [`NodeKind`] discriminant for this node type.
    pub fn kind(&self) -> NodeKind {
        NodeKind::OptItem
    }

    /// Return a reference to the stored [`Span`].
    pub fn span(&self) -> &Span {
        &self.span
    }

    /// Replace the node's span.
    pub fn set_span(&mut self, span: Span) {
        self.span = span;
    }

    /// Return a slice of all children (unfiltered).
    ///
    /// Each entry is `(label, child)`. Use the per-label accessors
    /// (`children_<lbl>`, `child_<lbl>`, `maybe_<lbl>`) for type-safe access.
    pub fn children(&self) -> &[(::std::option::Option<OptItemLabel>, OptItemChild)] {
        self.children.as_slice()
    }

    /// Push a child onto the children `Vec`.
    ///
    /// No type-checking is performed: any child variant may be stored under
    /// any label. Per-label typed mutators (`append_<lbl>`, `extend_<lbl>`)
    /// provide type-constrained alternatives.
    pub fn push_child(&mut self, label: ::std::option::Option<OptItemLabel>, child: OptItemChild) {
        self.children.push((label, child));
    }

    /// Return the single child (any label), or `Err` if there is not exactly one.
    ///
    /// Mirrors the Python `child()` method: count violation → `CstError::ChildCount`.
    pub fn child(&self) -> ::std::result::Result<&(::std::option::Option<OptItemLabel>, OptItemChild), CstError> {
        match self.children.as_slice() {
            [single] => Ok(single),
            slice => Err(CstError::ChildCount {
                label: "<any>",
                expected: "1",
                found: slice.len(),
            }),
        }
    }

    /// Copy all children from `other` into `self`, sharing the `Shared<T>` arcs.
    ///
    /// Children are appended (Arc reference-count bumps, not deep copies),
    /// matching the Python backend's reference-copy behavior. Labels are preserved.
    ///
    /// The borrow checker prevents `self.extend_children(self)` at the data-struct
    /// level (`&mut` + `&` of the same value don't coexist). For self-extend from
    /// Python, the handle pymethod handles it via snapshotting.
    pub fn extend_children(&mut self, other: &Self) {
        self.children.extend(other.children.iter().cloned());
    }

    /// Return an iterator over `Shared<Atom>` children labelled `item`.
    ///
    /// Off-type variants stored under the `item` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_item(&self) -> impl ::std::iter::Iterator<Item = &Shared<Atom>> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(OptItemLabel::Item))
            .map(|(_, child)| match child { OptItemChild::Atom(s) => s })
    }

    /// Return the single child labelled `item`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_item(&self) -> ::std::result::Result<&Shared<Atom>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(OptItemLabel::Item));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                OptItemChild::Atom(s) => Ok(s),
            },
            _ => Err(CstError::ChildCount {
                label: "item",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(OptItemLabel::Item))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `item`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_item(&self) -> ::std::result::Result<::std::option::Option<&Shared<Atom>>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(OptItemLabel::Item));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                OptItemChild::Atom(s) => Ok(Some(s)),
            },
            _ => Err(CstError::ChildCount {
                label: "item",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(OptItemLabel::Item))
                    .count(),
            }),
        }
    }

    /// Append a child with label `item`, accepting `Atom` or `Shared<Atom>`.
    pub fn append_item(&mut self, child: impl ::std::convert::Into<Shared<Atom>>) {
        self.children.push((Some(OptItemLabel::Item), OptItemChild::Atom(child.into())));
    }

    /// Append multiple children with label `item`.
    pub fn extend_item(&mut self, children: impl ::std::iter::IntoIterator<Item = impl ::std::convert::Into<Shared<Atom>>>) {
        self.children.extend(children.into_iter().map(|c| (Some(OptItemLabel::Item), OptItemChild::Atom(c.into()))));
    }

    /// Return the optional child labelled `item`.
    ///
    /// Panics if more than one is present; use `maybe_item` for the checked form.
    pub fn item(&self) -> ::std::option::Option<&Shared<Atom>> {
        self.maybe_item()
            .unwrap_or_else(|e| panic!("OptItem.item: {e}"))
    }

    /// Insert a child at `index` (Vec::insert semantics: panics if index > len).
    ///
    /// Python-facing clamping is in the `insert` pymethod; native callers must
    /// bounds-check. Unlike `list.insert`, Vec::insert panics on out-of-bounds.
    pub fn insert_child(&mut self, index: usize, label: ::std::option::Option<OptItemLabel>, child: OptItemChild) {
        self.children.insert(index, (label, child));
    }

    /// Remove and return the child at `index` (Vec::remove semantics: panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `remove_at` pymethod.
    pub fn remove_child(&mut self, index: usize) -> (::std::option::Option<OptItemLabel>, OptItemChild) {
        self.children.remove(index)
    }

    /// Replace the child at `index`, returning the old entry (panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `replace_at` pymethod.
    pub fn replace_child(
        &mut self, index: usize, label: ::std::option::Option<OptItemLabel>, child: OptItemChild,
    ) -> (::std::option::Option<OptItemLabel>, OptItemChild) {
        std::mem::replace(&mut self.children[index], (label, child))
    }

    /// Remove all children.
    pub fn clear_children(&mut self) {
        self.children.clear();
    }
}

#[cfg(feature = "python")]
#[pyclass(frozen, weakref, name = "OptItem")]
pub struct PyOptItem {
    // Not pub: all external access goes through shared() or to_py_canonical().
    // A pub field would let mixed-app Rust code construct an unregistered handle
    // (Py::new(py, PyFoo { inner: s.clone() })), silently breaking is-stability.
    inner: Shared<OptItem>,
}

#[cfg(feature = "python")]
impl PyOptItem {
    /// Return a reference to the inner `Shared<OptItem>`.
    pub fn shared(&self) -> &Shared<OptItem> {
        &self.inner
    }

    /// Wrap a `Shared<OptItem>` into a canonical Python handle,
    /// looking up the registry first so the same handle is returned
    /// for the same `Shared` allocation.
    pub fn to_py_canonical(py: Python<'_>, s: &Shared<OptItem>) -> pyo3::PyResult<Py<PyOptItem>> {
        let addr = s.arc_ptr();
        let obj = registry::get_or_insert_with(py, addr, || {
            let handle = PyOptItem { inner: s.clone() };
            Py::new(py, handle).map(|p| p.into_any())
        })?;
        obj.bind(py).cast::<PyOptItem>().map(|b| b.clone().unbind()).map_err(|e| e.into())
    }

    /// Snapshot the children carrying `label` into a new Python list.
    fn py_children_snapshot(&self, py: Python<'_>, label: &OptItemLabel) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Lock scope: filter by label under the read guard, cloning only matching
        // children (Arc bump or Span copy each); drop the guard before to_pyobject,
        // which performs Python work that must not happen while a node lock is held.
        let matching: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.iter()
                .filter(|(lbl, _)| lbl.as_ref() == Some(label))
                .map(|(_, child)| child.clone())
                .collect()
        };
        let result = pyo3::types::PyList::empty(py);
        for child in &matching {
            result.append(child.to_pyobject(py)?)?;
        }
        Ok(result.unbind())
    }
}

#[cfg(feature = "python")]
#[pymethods]
impl PyOptItem {
    #[new]
    #[pyo3(signature = (*, span = None))]
    fn new(py: Python<'_>, span: ::std::option::Option<&Bound<'_, pyo3::PyAny>>) -> pyo3::PyResult<Py<PyOptItem>> {
        let native_span = match span {
            Some(s) => extract_span(py, s)?,
            None => Span::unknown(),
        };
        let data = OptItem {
            span: native_span,
            children: ::std::vec::Vec::new(),
        };
        let shared = Shared::new(data);
        let addr = shared.arc_ptr();
        let handle = PyOptItem { inner: shared };
        let py_obj = Py::new(py, handle)?;
        // Register as canonical — fresh Shared, no alias can exist yet.
        registry::force_register(py, addr, py_obj.bind(py))?;
        Ok(py_obj)
    }

    #[getter]
    fn span(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Snapshot the span under the read lock, then drop the guard before
        // calling span_to_pyobject — which performs Python work (Py::new or
        // Python method calls) that must not happen while a node lock is held.
        let span = self.inner.read().span.clone();
        span_to_pyobject(py, &span)
    }

    #[setter]
    fn set_span(&self, py: Python<'_>, value: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        self.inner.write().span = extract_span(py, value)?;
        Ok(())
    }

    #[getter]
    fn kind(&self) -> NodeKind {
        NodeKind::OptItem
    }

    #[classattr]
    #[allow(non_snake_case)]
    fn Label(py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        Ok(<OptItemLabel as pyo3::PyTypeInfo>::type_object(py).into_any().unbind())
    }

    #[getter]
    fn children(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Snapshot the children vec (Arc clones for node children — O(n) refcount bumps).
        // Lock scope: acquire read, snapshot, release before touching Python.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.clone()
        };
        let result = pyo3::types::PyList::empty(py);
        for (label, child) in &snapshot {
            let label_obj: Py<pyo3::PyAny> = match label {
                None => py.None(),
                Some(lbl) => lbl.clone().into_pyobject(py)?.into_any().unbind(),
            };
            let child_obj = child.to_pyobject(py)?;
            let tup = pyo3::types::PyTuple::new(py, [label_obj, child_obj])?;
            result.append(tup)?;
        }
        Ok(result.unbind())
    }

    #[pyo3(signature = (child, label = None))]
    fn append(
        &self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>, label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<OptItemLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| OptItemLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "OptItem.append: label argument is not a OptItem_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = OptItemChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((native_label, native_child));
        Ok(())
    }

    #[pyo3(signature = (children, label = None))]
    fn extend(
        &self,
        py: Python<'_>,
        children: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<OptItemLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| OptItemLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "OptItem.extend: label argument is not a OptItem_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must leave
        // the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = OptItemChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((native_label.clone(), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn extend_children(&self, _py: Python<'_>, other: &PyOptItem) -> pyo3::PyResult<()> {
        // Snapshot other's children first: the read guard is dropped at the end of
        // this block, so the write lock below is safe even when self and other are
        // the same node (self-extend). No ptr_eq call is needed here — the snapshot
        // approach handles self-extend structurally.
        // Lock scope: hold read only long enough to clone the Arc-based children vec.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = other.inner.read();
            guard.children.clone()
        };
        // Node-typed children are pushed directly as Shared<T> values.  Registry
        // consistency is maintained lazily: wrap-out registers on first Python read
        // via get_or_insert_with (registry.rs).  Eagerly registering here would be
        // a no-op — the WeakValueDictionary would evict handles held by nothing.
        self.inner.write().children.extend(snapshot);
        Ok(())
    }

    fn child(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: read len and clone at most the single entry under the guard;
        // drop the guard before any Python work (object conversion, exception raise).
        let (n, entry) = {
            let guard = self.inner.read();
            let n = guard.children.len();
            let entry = if n == 1 { Some(guard.children[0].clone()) } else { None };
            (n, entry)
        };
        let Some((label, child)) = entry else {
            return Err(PyValueError::new_err(format!(
                "Expected one child but have {n}"
            )));
        };
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn insert(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<OptItemLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| OptItemLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "OptItem.insert: label argument is not a OptItem_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = OptItemChild::extract_from_pyobject(py, child, &span_type)?;
        // Index normalization via operator.index (PyNumber_Index semantics).
        // This raises TypeError (not AttributeError) for non-indexable inputs, matching Python's
        // operator.index contract. Must be done BEFORE taking any lock.
        // Overflow by sign: positive overflow clamps to len; negative overflow clamps to 0.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path for the common exact-int case; fall back to sign-based Python call for beyond-i64.
        let (is_negative_big, raw_i64) = if let Ok(i) = raw_idx.extract::<i64>() {
            (false, Some(i))
        } else {
            // Beyond i64: use Python __lt__ to determine sign.  The lt call is still outside
            // any lock, so lock discipline is maintained.
            let neg = raw_idx.lt(0i64)?;
            (neg, None)
        };
        // Now take a single write lock for the entire len-read + clamp + insert sequence.
        let mut guard = self.inner.write();
        let n = guard.children.len();
        let clamped: usize = match raw_i64 {
            Some(i) if i < 0 => {
                let normalized = n as i64 + i;
                if normalized < 0 { 0 } else { normalized as usize }
            }
            Some(i) => {
                let u = i as usize;
                if u > n { n } else { u }
            }
            None => if is_negative_big { 0 } else { n },
        };
        guard.children.insert(clamped, (native_label, native_child));
        Ok(())
    }

    fn remove_at(&self, py: Python<'_>, index: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Capture the caller's original string representation BEFORE normalization,
        // so error messages show the original value (e.g. `True` not `1`).
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError (not AttributeError) for
        // non-indexable inputs, matching Python's operator.index contract.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path: extract i64. Beyond i64 is always OOB for real trees.
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + Vec::remove atomically (no TOCTOU).
        // On OOB, capture n and return Err after releasing the guard.
        let result: ::std::result::Result<_, usize> = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            match resolved {
                Some(idx) => Ok(guard.children.remove(idx)),
                None => Err(n),
            }
        };
        let (label, child) = result.map_err(|n| {
            PyIndexError::new_err(format!(
                "OptItem.remove_at: index {} out of range ({} children)",
                orig_str, n
            ))
        })?;
        // Python wrap-out happens after the guard is released.
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn replace_at(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<OptItemLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| OptItemLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "OptItem.replace_at: label argument is not a OptItem_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = OptItemChild::extract_from_pyobject(py, child, &span_type)?;
        // Capture the caller's original string representation BEFORE normalization.
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError for non-indexable inputs.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + mem::replace atomically (no TOCTOU).
        let old = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            let idx = match resolved {
                Some(i) => i,
                None => {
                    return Err(PyIndexError::new_err(format!(
                        "OptItem.replace_at: index {} out of range ({} children)",
                        orig_str, n
                    )));
                }
            };
            std::mem::replace(&mut guard.children[idx], (native_label, native_child))
        };
        // Drop old entry outside the lock to avoid recursive lock acquisition
        // if the child's drop chain re-enters Python.
        drop(old);
        Ok(())
    }

    fn clear(&self, _py: Python<'_>) -> pyo3::PyResult<()> {
        let old = {
            let mut guard = self.inner.write();
            std::mem::take(&mut guard.children)
        };
        // Drop old entries outside the lock.
        drop(old);
        Ok(())
    }

    fn append_item(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = OptItemChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(OptItemLabel::Item), native_child));
        Ok(())
    }

    fn extend_item(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = OptItemChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(OptItemLabel::Item), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_item(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &OptItemLabel::Item)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_item(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(OptItemLabel::Item) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one item child but have {count}"
            )));
        }
        first.expect("invariant: OptItem.child_item: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_item(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(OptItemLabel::Item) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one item child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn item(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        self.maybe_item(py)
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if !other.is_instance_of::<PyOptItem>() {
            return Ok(py.NotImplemented());
        }
        let other_handle: pyo3::PyRef<PyOptItem> = other.extract()?;
        // Delegate to Shared<T>::PartialEq which applies the ptr_eq short-circuit
        // (avoids same-lock re-entry on `x == x`) then deep structural comparison.
        let eq = self.inner == other_handle.inner;
        Ok(eq.into_pyobject(py)?.to_owned().unbind().into_any())
    }

    fn __hash__(&self) -> pyo3::PyResult<isize> {
        Err(PyTypeError::new_err("unhashable type: 'OptItem'"))
    }

    fn __repr__(&self, _py: Python<'_>) -> ::std::string::String {
        let guard = self.inner.read();
        let span_repr = format!("Span(start={}, end={})", guard.span.start(), guard.span.end());
        let children_len = guard.children.len();
        format!(
            "OptItem(span={span_repr}, children=[<{children_len} child(ren)>])"
        )
    }

}

