/// Child value enum for `NcGroupAlt` nodes.
///
/// Node-typed variants hold `Shared<T>` (`Arc<RwLock<T>>`); `Clone` is shallow
/// (increments the reference count, does not copy the node).
#[derive(Clone, Debug)]
pub enum NcGroupAltChild {
    Span(Span),
}

impl ::std::cmp::PartialEq for NcGroupAltChild {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (NcGroupAltChild::Span(a), NcGroupAltChild::Span(b)) => a == b,
        }
    }
}

#[cfg(feature = "python")]
impl NcGroupAltChild {
    fn to_pyobject(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        match self {
            Self::Span(s) => {
                span_to_pyobject(py, s)
            }
        }
    }

    fn extract_from_pyobject(
        py: Python<'_>,
        obj: &Bound<'_, pyo3::PyAny>,
        span_type: &Bound<'_, pyo3::types::PyType>,
    ) -> pyo3::PyResult<Self> {
        // Try Span (terminal child) first — handles cross-cdylib span instances.
        if obj.is_instance_of::<Span>() || obj.is_instance(span_type)? {
            return extract_span(py, obj).map(Self::Span);
        }
        let rejected_type = obj.get_type();
        Err(pyo3::exceptions::PyTypeError::new_err(format!(
            "NcGroupAlt: unsupported child type {}.{}",
            rejected_type.module()?,
            rejected_type.qualname()?
        )))
    }
}

// ───────────────────────────────────────────────────────────────────────────
// NcGroupAlt
// ───────────────────────────────────────────────────────────────────────────

/// CST data struct for `NcGroupAlt`. See [`fltk_cst_core::Shared`] for clone/equality/reference semantics.
///
/// `Debug` output is non-recursive: prints span + child count only. Traverse via `children()` to inspect subtrees.
#[derive(Clone)]
pub struct NcGroupAlt {
    // Not pub: use span() / children() / push_child() — the stable accessor API.
    // Direct field access bypasses any future validation logic on setters.
    span: Span,
    children: ::std::vec::Vec<(::std::option::Option<NcGroupAltLabel>, NcGroupAltChild)>,
}

// Manual Debug: prints span + child COUNT, never recursing into children.
// A derived Debug would recurse through Shared<T> children with no depth
// bound; tree depth is attacker-controlled for parsers over untrusted
// input, so `{:?}` on a deep tree would abort the process (stack
// exhaustion, uncatchable). Mirrors the Python __repr__'s content.
impl fmt::Debug for NcGroupAlt {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("NcGroupAlt")
            .field("span", &self.span)
            .field("children", &format_args!("<{} child(ren)>", self.children.len()))
            .finish()
    }
}

// Span-only PartialEq: no node-typed children, so this cannot recurse — depth-safe.
impl ::std::cmp::PartialEq for NcGroupAlt {
    fn eq(&self, other: &Self) -> bool {
        self.span == other.span && self.children == other.children
    }
}

impl NcGroupAlt {
    /// Construct a node with the given span and no children. GIL-free.
    pub fn new(span: Span) -> Self {
        NcGroupAlt {
            span,
            children: ::std::vec::Vec::new(),
        }
    }

    /// Return the [`NodeKind`] discriminant for this node type.
    pub fn kind(&self) -> NodeKind {
        NodeKind::NcGroupAlt
    }

    /// Return a reference to the stored [`Span`].
    pub fn span(&self) -> &Span {
        &self.span
    }

    /// Replace the node's span.
    pub fn set_span(&mut self, span: Span) {
        self.span = span;
    }

    /// Return a slice of all children (unfiltered).
    ///
    /// Each entry is `(label, child)`. Use the per-label accessors
    /// (`children_<lbl>`, `child_<lbl>`, `maybe_<lbl>`) for type-safe access.
    pub fn children(&self) -> &[(::std::option::Option<NcGroupAltLabel>, NcGroupAltChild)] {
        self.children.as_slice()
    }

    /// Push a child onto the children `Vec`.
    ///
    /// No type-checking is performed: any child variant may be stored under
    /// any label. Per-label typed mutators (`append_<lbl>`, `extend_<lbl>`)
    /// provide type-constrained alternatives.
    pub fn push_child(&mut self, label: ::std::option::Option<NcGroupAltLabel>, child: NcGroupAltChild) {
        self.children.push((label, child));
    }

    /// Return the single child (any label), or `Err` if there is not exactly one.
    ///
    /// Mirrors the Python `child()` method: count violation → `CstError::ChildCount`.
    pub fn child(&self) -> ::std::result::Result<&(::std::option::Option<NcGroupAltLabel>, NcGroupAltChild), CstError> {
        match self.children.as_slice() {
            [single] => Ok(single),
            slice => Err(CstError::ChildCount {
                label: "<any>",
                expected: "1",
                found: slice.len(),
            }),
        }
    }

    /// Copy all children from `other` into `self`, sharing the `Shared<T>` arcs.
    ///
    /// Children are appended (Arc reference-count bumps, not deep copies),
    /// matching the Python backend's reference-copy behavior. Labels are preserved.
    ///
    /// The borrow checker prevents `self.extend_children(self)` at the data-struct
    /// level (`&mut` + `&` of the same value don't coexist). For self-extend from
    /// Python, the handle pymethod handles it via snapshotting.
    pub fn extend_children(&mut self, other: &Self) {
        self.children.extend(other.children.iter().cloned());
    }

    /// Return an iterator over `Span` children labelled `value`.
    ///
    /// Off-type variants stored under the `value` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_value(&self) -> impl ::std::iter::Iterator<Item = &Span> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(NcGroupAltLabel::Value))
            .map(|(_, child)| match child { NcGroupAltChild::Span(s) => s })
    }

    /// Return the single child labelled `value`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_value(&self) -> ::std::result::Result<&Span, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(NcGroupAltLabel::Value));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                NcGroupAltChild::Span(s) => Ok(s),
            },
            _ => Err(CstError::ChildCount {
                label: "value",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(NcGroupAltLabel::Value))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `value`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_value(&self) -> ::std::result::Result<::std::option::Option<&Span>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(NcGroupAltLabel::Value));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                NcGroupAltChild::Span(s) => Ok(Some(s)),
            },
            _ => Err(CstError::ChildCount {
                label: "value",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(NcGroupAltLabel::Value))
                    .count(),
            }),
        }
    }

    /// Append a `Span` child with label `value`.
    pub fn append_value(&mut self, span: Span) {
        self.children.push((Some(NcGroupAltLabel::Value), NcGroupAltChild::Span(span)));
    }

    /// Append multiple `Span` children with label `value`.
    pub fn extend_value(&mut self, spans: impl ::std::iter::IntoIterator<Item = Span>) {
        self.children.extend(spans.into_iter().map(|s| (Some(NcGroupAltLabel::Value), NcGroupAltChild::Span(s))));
    }

    /// Return the child labelled `value`.
    ///
    /// Panics unless exactly one is present; use `child_value` for the checked form.
    pub fn value(&self) -> &Span {
        self.child_value()
            .unwrap_or_else(|e| panic!("NcGroupAlt.value: {e}"))
    }

    /// Return the source text of the child labelled `value`.
    ///
    /// Borrows from the span's source; panics if the child is absent or its span
    /// carries no usable source.
    pub fn value_text(&self) -> &str {
        self.child_value()
            .unwrap_or_else(|e| panic!("NcGroupAlt.value_text: {e}"))
            .text_or_message()
            .unwrap_or_else(|e| panic!("NcGroupAlt.value_text: {e}"))
    }

    /// Return this node's own source text.
    ///
    /// Covers suppressed content inside the node's span; panics if the span carries no
    /// usable source.
    pub fn text(&self) -> &str {
        self.span
            .text_or_message()
            .unwrap_or_else(|e| panic!("NcGroupAlt.text: {e}"))
    }

    /// Insert a child at `index` (Vec::insert semantics: panics if index > len).
    ///
    /// Python-facing clamping is in the `insert` pymethod; native callers must
    /// bounds-check. Unlike `list.insert`, Vec::insert panics on out-of-bounds.
    pub fn insert_child(&mut self, index: usize, label: ::std::option::Option<NcGroupAltLabel>, child: NcGroupAltChild) {
        self.children.insert(index, (label, child));
    }

    /// Remove and return the child at `index` (Vec::remove semantics: panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `remove_at` pymethod.
    pub fn remove_child(&mut self, index: usize) -> (::std::option::Option<NcGroupAltLabel>, NcGroupAltChild) {
        self.children.remove(index)
    }

    /// Replace the child at `index`, returning the old entry (panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `replace_at` pymethod.
    pub fn replace_child(
        &mut self, index: usize, label: ::std::option::Option<NcGroupAltLabel>, child: NcGroupAltChild,
    ) -> (::std::option::Option<NcGroupAltLabel>, NcGroupAltChild) {
        std::mem::replace(&mut self.children[index], (label, child))
    }

    /// Remove all children.
    pub fn clear_children(&mut self) {
        self.children.clear();
    }
}

#[cfg(feature = "python")]
#[pyclass(frozen, weakref, name = "NcGroupAlt")]
pub struct PyNcGroupAlt {
    // Not pub: all external access goes through shared() or to_py_canonical().
    // A pub field would let mixed-app Rust code construct an unregistered handle
    // (Py::new(py, PyFoo { inner: s.clone() })), silently breaking is-stability.
    inner: Shared<NcGroupAlt>,
}

#[cfg(feature = "python")]
impl PyNcGroupAlt {
    /// Return a reference to the inner `Shared<NcGroupAlt>`.
    pub fn shared(&self) -> &Shared<NcGroupAlt> {
        &self.inner
    }

    /// Wrap a `Shared<NcGroupAlt>` into a canonical Python handle,
    /// looking up the registry first so the same handle is returned
    /// for the same `Shared` allocation.
    pub fn to_py_canonical(py: Python<'_>, s: &Shared<NcGroupAlt>) -> pyo3::PyResult<Py<PyNcGroupAlt>> {
        let addr = s.arc_ptr();
        let obj = registry::get_or_insert_with(py, addr, || {
            let handle = PyNcGroupAlt { inner: s.clone() };
            Py::new(py, handle).map(|p| p.into_any())
        })?;
        obj.bind(py).cast::<PyNcGroupAlt>().map(|b| b.clone().unbind()).map_err(|e| e.into())
    }

    /// Snapshot the children carrying `label` into a new Python list.
    fn py_children_snapshot(&self, py: Python<'_>, label: &NcGroupAltLabel) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Lock scope: filter by label under the read guard, cloning only matching
        // children (Arc bump or Span copy each); drop the guard before to_pyobject,
        // which performs Python work that must not happen while a node lock is held.
        let matching: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.iter()
                .filter(|(lbl, _)| lbl.as_ref() == Some(label))
                .map(|(_, child)| child.clone())
                .collect()
        };
        let result = pyo3::types::PyList::empty(py);
        for child in &matching {
            result.append(child.to_pyobject(py)?)?;
        }
        Ok(result.unbind())
    }
}

#[cfg(feature = "python")]
#[pymethods]
impl PyNcGroupAlt {
    #[new]
    #[pyo3(signature = (*, span = None))]
    fn new(py: Python<'_>, span: ::std::option::Option<&Bound<'_, pyo3::PyAny>>) -> pyo3::PyResult<Py<PyNcGroupAlt>> {
        let native_span = match span {
            Some(s) => extract_span(py, s)?,
            None => Span::unknown(),
        };
        let data = NcGroupAlt {
            span: native_span,
            children: ::std::vec::Vec::new(),
        };
        let shared = Shared::new(data);
        let addr = shared.arc_ptr();
        let handle = PyNcGroupAlt { inner: shared };
        let py_obj = Py::new(py, handle)?;
        // Register as canonical — fresh Shared, no alias can exist yet.
        registry::force_register(py, addr, py_obj.bind(py))?;
        Ok(py_obj)
    }

    #[getter]
    fn span(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Snapshot the span under the read lock, then drop the guard before
        // calling span_to_pyobject — which performs Python work (Py::new or
        // Python method calls) that must not happen while a node lock is held.
        let span = self.inner.read().span.clone();
        span_to_pyobject(py, &span)
    }

    #[setter]
    fn set_span(&self, py: Python<'_>, value: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        self.inner.write().span = extract_span(py, value)?;
        Ok(())
    }

    #[getter]
    fn kind(&self) -> NodeKind {
        NodeKind::NcGroupAlt
    }

    #[classattr]
    #[allow(non_snake_case)]
    fn Label(py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        Ok(<NcGroupAltLabel as pyo3::PyTypeInfo>::type_object(py).into_any().unbind())
    }

    #[getter]
    fn children(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Snapshot the children vec (Arc clones for node children — O(n) refcount bumps).
        // Lock scope: acquire read, snapshot, release before touching Python.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.clone()
        };
        let result = pyo3::types::PyList::empty(py);
        for (label, child) in &snapshot {
            let label_obj: Py<pyo3::PyAny> = match label {
                None => py.None(),
                Some(lbl) => lbl.clone().into_pyobject(py)?.into_any().unbind(),
            };
            let child_obj = child.to_pyobject(py)?;
            let tup = pyo3::types::PyTuple::new(py, [label_obj, child_obj])?;
            result.append(tup)?;
        }
        Ok(result.unbind())
    }

    #[pyo3(signature = (child, label = None))]
    fn append(
        &self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>, label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<NcGroupAltLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| NcGroupAltLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "NcGroupAlt.append: label argument is not a NcGroupAlt_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = NcGroupAltChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((native_label, native_child));
        Ok(())
    }

    #[pyo3(signature = (children, label = None))]
    fn extend(
        &self,
        py: Python<'_>,
        children: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<NcGroupAltLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| NcGroupAltLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "NcGroupAlt.extend: label argument is not a NcGroupAlt_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must leave
        // the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = NcGroupAltChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((native_label.clone(), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn extend_children(&self, _py: Python<'_>, other: &PyNcGroupAlt) -> pyo3::PyResult<()> {
        // Snapshot other's children first: the read guard is dropped at the end of
        // this block, so the write lock below is safe even when self and other are
        // the same node (self-extend). No ptr_eq call is needed here — the snapshot
        // approach handles self-extend structurally.
        // Lock scope: hold read only long enough to clone the Arc-based children vec.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = other.inner.read();
            guard.children.clone()
        };
        // Node-typed children are pushed directly as Shared<T> values.  Registry
        // consistency is maintained lazily: wrap-out registers on first Python read
        // via get_or_insert_with (registry.rs).  Eagerly registering here would be
        // a no-op — the WeakValueDictionary would evict handles held by nothing.
        self.inner.write().children.extend(snapshot);
        Ok(())
    }

    fn child(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: read len and clone at most the single entry under the guard;
        // drop the guard before any Python work (object conversion, exception raise).
        let (n, entry) = {
            let guard = self.inner.read();
            let n = guard.children.len();
            let entry = if n == 1 { Some(guard.children[0].clone()) } else { None };
            (n, entry)
        };
        let Some((label, child)) = entry else {
            return Err(PyValueError::new_err(format!(
                "Expected one child but have {n}"
            )));
        };
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn insert(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<NcGroupAltLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| NcGroupAltLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "NcGroupAlt.insert: label argument is not a NcGroupAlt_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = NcGroupAltChild::extract_from_pyobject(py, child, &span_type)?;
        // Index normalization via operator.index (PyNumber_Index semantics).
        // This raises TypeError (not AttributeError) for non-indexable inputs, matching Python's
        // operator.index contract. Must be done BEFORE taking any lock.
        // Overflow by sign: positive overflow clamps to len; negative overflow clamps to 0.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path for the common exact-int case; fall back to sign-based Python call for beyond-i64.
        let (is_negative_big, raw_i64) = if let Ok(i) = raw_idx.extract::<i64>() {
            (false, Some(i))
        } else {
            // Beyond i64: use Python __lt__ to determine sign.  The lt call is still outside
            // any lock, so lock discipline is maintained.
            let neg = raw_idx.lt(0i64)?;
            (neg, None)
        };
        // Now take a single write lock for the entire len-read + clamp + insert sequence.
        let mut guard = self.inner.write();
        let n = guard.children.len();
        let clamped: usize = match raw_i64 {
            Some(i) if i < 0 => {
                let normalized = n as i64 + i;
                if normalized < 0 { 0 } else { normalized as usize }
            }
            Some(i) => {
                let u = i as usize;
                if u > n { n } else { u }
            }
            None => if is_negative_big { 0 } else { n },
        };
        guard.children.insert(clamped, (native_label, native_child));
        Ok(())
    }

    fn remove_at(&self, py: Python<'_>, index: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Capture the caller's original string representation BEFORE normalization,
        // so error messages show the original value (e.g. `True` not `1`).
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError (not AttributeError) for
        // non-indexable inputs, matching Python's operator.index contract.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path: extract i64. Beyond i64 is always OOB for real trees.
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + Vec::remove atomically (no TOCTOU).
        // On OOB, capture n and return Err after releasing the guard.
        let result: ::std::result::Result<_, usize> = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            match resolved {
                Some(idx) => Ok(guard.children.remove(idx)),
                None => Err(n),
            }
        };
        let (label, child) = result.map_err(|n| {
            PyIndexError::new_err(format!(
                "NcGroupAlt.remove_at: index {} out of range ({} children)",
                orig_str, n
            ))
        })?;
        // Python wrap-out happens after the guard is released.
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn replace_at(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<NcGroupAltLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| NcGroupAltLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "NcGroupAlt.replace_at: label argument is not a NcGroupAlt_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = NcGroupAltChild::extract_from_pyobject(py, child, &span_type)?;
        // Capture the caller's original string representation BEFORE normalization.
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError for non-indexable inputs.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + mem::replace atomically (no TOCTOU).
        let old = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            let idx = match resolved {
                Some(i) => i,
                None => {
                    return Err(PyIndexError::new_err(format!(
                        "NcGroupAlt.replace_at: index {} out of range ({} children)",
                        orig_str, n
                    )));
                }
            };
            std::mem::replace(&mut guard.children[idx], (native_label, native_child))
        };
        // Drop old entry outside the lock to avoid recursive lock acquisition
        // if the child's drop chain re-enters Python.
        drop(old);
        Ok(())
    }

    fn clear(&self, _py: Python<'_>) -> pyo3::PyResult<()> {
        let old = {
            let mut guard = self.inner.write();
            std::mem::take(&mut guard.children)
        };
        // Drop old entries outside the lock.
        drop(old);
        Ok(())
    }

    fn append_value(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = NcGroupAltChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(NcGroupAltLabel::Value), native_child));
        Ok(())
    }

    fn extend_value(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = NcGroupAltChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(NcGroupAltLabel::Value), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_value(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &NcGroupAltLabel::Value)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_value(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(NcGroupAltLabel::Value) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one value child but have {count}"
            )));
        }
        first.expect("invariant: NcGroupAlt.child_value: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_value(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(NcGroupAltLabel::Value) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one value child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn value(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        self.child_value(py)
    }

    fn value_text(&self) -> pyo3::PyResult<::std::string::String> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(NcGroupAltLabel::Value) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one value child but have {count}"
            )));
        }
        match first
            .expect("invariant: NcGroupAlt.value_text: count==1 but first==None; logic error")
        {
            NcGroupAltChild::Span(s) => s
                .text_or_message()
                .map(str::to_owned)
                .map_err(PyValueError::new_err),
        }
    }

    fn text(&self) -> pyo3::PyResult<::std::string::String> {
        // Clone the span under the read guard, then release it before raising.
        let span = self.inner.read().span.clone();
        span.text_or_message()
            .map(str::to_owned)
            .map_err(PyValueError::new_err)
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if !other.is_instance_of::<PyNcGroupAlt>() {
            return Ok(py.NotImplemented());
        }
        let other_handle: pyo3::PyRef<PyNcGroupAlt> = other.extract()?;
        // Delegate to Shared<T>::PartialEq which applies the ptr_eq short-circuit
        // (avoids same-lock re-entry on `x == x`) then deep structural comparison.
        let eq = self.inner == other_handle.inner;
        Ok(eq.into_pyobject(py)?.to_owned().unbind().into_any())
    }

    fn __hash__(&self) -> pyo3::PyResult<isize> {
        Err(PyTypeError::new_err("unhashable type: 'NcGroupAlt'"))
    }

    fn __repr__(&self, _py: Python<'_>) -> ::std::string::String {
        let guard = self.inner.read();
        let span_repr = format!("Span(start={}, end={})", guard.span.start(), guard.span.end());
        let children_len = guard.children.len();
        format!(
            "NcGroupAlt(span={span_repr}, children=[<{children_len} child(ren)>])"
        )
    }

}

// ───────────────────────────────────────────────────────────────────────────
// CaseInsensitiveLabel
// ───────────────────────────────────────────────────────────────────────────

/// Label discriminant enum for children of this node type.
///
/// Python-visible name is `CaseInsensitive_Label` (preserved for compatibility).
/// Rust consumers use the CamelCase `CaseInsensitiveLabel` name.
#[cfg(feature = "python")]
#[pyclass(frozen, from_py_object, name = "CaseInsensitive_Label")]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum CaseInsensitiveLabel {
    #[pyo3(name = "VALUE")]
    Value,
}

#[cfg(not(feature = "python"))]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum CaseInsensitiveLabel {
    Value,
}

#[cfg(feature = "python")]
#[pymethods]
impl CaseInsensitiveLabel {
    fn __repr__(&self) -> &'static str {
        match self {
            CaseInsensitiveLabel::Value => "CaseInsensitive.Label.VALUE",
        }
    }

    #[getter]
    fn _fltk_canonical_name(&self) -> &'static str {
        self.__repr__()
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if let Ok(other_kind) = other.extract::<CaseInsensitiveLabel>() {
            return Ok((self == &other_kind).into_pyobject(py)?.to_owned().unbind().into_any());
        }
        if let Ok(cn) = other.getattr(pyo3::intern!(py, "_fltk_canonical_name")) {
            if let Ok(cn_str) = cn.extract::<&str>() {
                return Ok((self.__repr__() == cn_str).into_pyobject(py)?.to_owned().unbind().into_any());
            }
        }
        Ok(py.NotImplemented())
    }

    fn __hash__(&self, py: Python<'_>) -> pyo3::PyResult<isize> {
        pyo3::types::PyAnyMethods::hash(
            pyo3::types::PyString::new(py, self.__repr__()).as_any()
        )
    }
}

#[cfg(feature = "python")]
impl CaseInsensitiveLabel {
    /// The variant with this cross-backend canonical name, if any.
    fn from_canonical_name(name: &str) -> ::std::option::Option<Self> {
        match name {
            "CaseInsensitive.Label.VALUE" => Some(CaseInsensitiveLabel::Value),
            _ => None,
        }
    }
}

/// Child value enum for `CaseInsensitive` nodes.
///
/// Node-typed variants hold `Shared<T>` (`Arc<RwLock<T>>`); `Clone` is shallow
/// (increments the reference count, does not copy the node).
#[derive(Clone, Debug)]
pub enum CaseInsensitiveChild {
    Span(Span),
}

impl ::std::cmp::PartialEq for CaseInsensitiveChild {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (CaseInsensitiveChild::Span(a), CaseInsensitiveChild::Span(b)) => a == b,
        }
    }
}

#[cfg(feature = "python")]
impl CaseInsensitiveChild {
    fn to_pyobject(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        match self {
            Self::Span(s) => {
                span_to_pyobject(py, s)
            }
        }
    }

    fn extract_from_pyobject(
        py: Python<'_>,
        obj: &Bound<'_, pyo3::PyAny>,
        span_type: &Bound<'_, pyo3::types::PyType>,
    ) -> pyo3::PyResult<Self> {
        // Try Span (terminal child) first — handles cross-cdylib span instances.
        if obj.is_instance_of::<Span>() || obj.is_instance(span_type)? {
            return extract_span(py, obj).map(Self::Span);
        }
        let rejected_type = obj.get_type();
        Err(pyo3::exceptions::PyTypeError::new_err(format!(
            "CaseInsensitive: unsupported child type {}.{}",
            rejected_type.module()?,
            rejected_type.qualname()?
        )))
    }
}

// ───────────────────────────────────────────────────────────────────────────
// CaseInsensitive
// ───────────────────────────────────────────────────────────────────────────

/// CST data struct for `CaseInsensitive`. See [`fltk_cst_core::Shared`] for clone/equality/reference semantics.
///
/// `Debug` output is non-recursive: prints span + child count only. Traverse via `children()` to inspect subtrees.
#[derive(Clone)]
pub struct CaseInsensitive {
    // Not pub: use span() / children() / push_child() — the stable accessor API.
    // Direct field access bypasses any future validation logic on setters.
    span: Span,
    children: ::std::vec::Vec<(::std::option::Option<CaseInsensitiveLabel>, CaseInsensitiveChild)>,
}

// Manual Debug: prints span + child COUNT, never recursing into children.
// A derived Debug would recurse through Shared<T> children with no depth
// bound; tree depth is attacker-controlled for parsers over untrusted
// input, so `{:?}` on a deep tree would abort the process (stack
// exhaustion, uncatchable). Mirrors the Python __repr__'s content.
impl fmt::Debug for CaseInsensitive {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("CaseInsensitive")
            .field("span", &self.span)
            .field("children", &format_args!("<{} child(ren)>", self.children.len()))
            .finish()
    }
}

// Span-only PartialEq: no node-typed children, so this cannot recurse — depth-safe.
impl ::std::cmp::PartialEq for CaseInsensitive {
    fn eq(&self, other: &Self) -> bool {
        self.span == other.span && self.children == other.children
    }
}

impl CaseInsensitive {
    /// Construct a node with the given span and no children. GIL-free.
    pub fn new(span: Span) -> Self {
        CaseInsensitive {
            span,
            children: ::std::vec::Vec::new(),
        }
    }

    /// Return the [`NodeKind`] discriminant for this node type.
    pub fn kind(&self) -> NodeKind {
        NodeKind::CaseInsensitive
    }

    /// Return a reference to the stored [`Span`].
    pub fn span(&self) -> &Span {
        &self.span
    }

    /// Replace the node's span.
    pub fn set_span(&mut self, span: Span) {
        self.span = span;
    }

    /// Return a slice of all children (unfiltered).
    ///
    /// Each entry is `(label, child)`. Use the per-label accessors
    /// (`children_<lbl>`, `child_<lbl>`, `maybe_<lbl>`) for type-safe access.
    pub fn children(&self) -> &[(::std::option::Option<CaseInsensitiveLabel>, CaseInsensitiveChild)] {
        self.children.as_slice()
    }

    /// Push a child onto the children `Vec`.
    ///
    /// No type-checking is performed: any child variant may be stored under
    /// any label. Per-label typed mutators (`append_<lbl>`, `extend_<lbl>`)
    /// provide type-constrained alternatives.
    pub fn push_child(&mut self, label: ::std::option::Option<CaseInsensitiveLabel>, child: CaseInsensitiveChild) {
        self.children.push((label, child));
    }

    /// Return the single child (any label), or `Err` if there is not exactly one.
    ///
    /// Mirrors the Python `child()` method: count violation → `CstError::ChildCount`.
    pub fn child(&self) -> ::std::result::Result<&(::std::option::Option<CaseInsensitiveLabel>, CaseInsensitiveChild), CstError> {
        match self.children.as_slice() {
            [single] => Ok(single),
            slice => Err(CstError::ChildCount {
                label: "<any>",
                expected: "1",
                found: slice.len(),
            }),
        }
    }

    /// Copy all children from `other` into `self`, sharing the `Shared<T>` arcs.
    ///
    /// Children are appended (Arc reference-count bumps, not deep copies),
    /// matching the Python backend's reference-copy behavior. Labels are preserved.
    ///
    /// The borrow checker prevents `self.extend_children(self)` at the data-struct
    /// level (`&mut` + `&` of the same value don't coexist). For self-extend from
    /// Python, the handle pymethod handles it via snapshotting.
    pub fn extend_children(&mut self, other: &Self) {
        self.children.extend(other.children.iter().cloned());
    }

    /// Return an iterator over `Span` children labelled `value`.
    ///
    /// Off-type variants stored under the `value` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_value(&self) -> impl ::std::iter::Iterator<Item = &Span> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(CaseInsensitiveLabel::Value))
            .map(|(_, child)| match child { CaseInsensitiveChild::Span(s) => s })
    }

    /// Return the single child labelled `value`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_value(&self) -> ::std::result::Result<&Span, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(CaseInsensitiveLabel::Value));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                CaseInsensitiveChild::Span(s) => Ok(s),
            },
            _ => Err(CstError::ChildCount {
                label: "value",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(CaseInsensitiveLabel::Value))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `value`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_value(&self) -> ::std::result::Result<::std::option::Option<&Span>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(CaseInsensitiveLabel::Value));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                CaseInsensitiveChild::Span(s) => Ok(Some(s)),
            },
            _ => Err(CstError::ChildCount {
                label: "value",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(CaseInsensitiveLabel::Value))
                    .count(),
            }),
        }
    }

    /// Append a `Span` child with label `value`.
    pub fn append_value(&mut self, span: Span) {
        self.children.push((Some(CaseInsensitiveLabel::Value), CaseInsensitiveChild::Span(span)));
    }

    /// Append multiple `Span` children with label `value`.
    pub fn extend_value(&mut self, spans: impl ::std::iter::IntoIterator<Item = Span>) {
        self.children.extend(spans.into_iter().map(|s| (Some(CaseInsensitiveLabel::Value), CaseInsensitiveChild::Span(s))));
    }

    /// Return the child labelled `value`.
    ///
    /// Panics unless exactly one is present; use `child_value` for the checked form.
    pub fn value(&self) -> &Span {
        self.child_value()
            .unwrap_or_else(|e| panic!("CaseInsensitive.value: {e}"))
    }

    /// Return the source text of the child labelled `value`.
    ///
    /// Borrows from the span's source; panics if the child is absent or its span
    /// carries no usable source.
    pub fn value_text(&self) -> &str {
        self.child_value()
            .unwrap_or_else(|e| panic!("CaseInsensitive.value_text: {e}"))
            .text_or_message()
            .unwrap_or_else(|e| panic!("CaseInsensitive.value_text: {e}"))
    }

    /// Return this node's own source text.
    ///
    /// Covers suppressed content inside the node's span; panics if the span carries no
    /// usable source.
    pub fn text(&self) -> &str {
        self.span
            .text_or_message()
            .unwrap_or_else(|e| panic!("CaseInsensitive.text: {e}"))
    }

    /// Insert a child at `index` (Vec::insert semantics: panics if index > len).
    ///
    /// Python-facing clamping is in the `insert` pymethod; native callers must
    /// bounds-check. Unlike `list.insert`, Vec::insert panics on out-of-bounds.
    pub fn insert_child(&mut self, index: usize, label: ::std::option::Option<CaseInsensitiveLabel>, child: CaseInsensitiveChild) {
        self.children.insert(index, (label, child));
    }

    /// Remove and return the child at `index` (Vec::remove semantics: panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `remove_at` pymethod.
    pub fn remove_child(&mut self, index: usize) -> (::std::option::Option<CaseInsensitiveLabel>, CaseInsensitiveChild) {
        self.children.remove(index)
    }

    /// Replace the child at `index`, returning the old entry (panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `replace_at` pymethod.
    pub fn replace_child(
        &mut self, index: usize, label: ::std::option::Option<CaseInsensitiveLabel>, child: CaseInsensitiveChild,
    ) -> (::std::option::Option<CaseInsensitiveLabel>, CaseInsensitiveChild) {
        std::mem::replace(&mut self.children[index], (label, child))
    }

    /// Remove all children.
    pub fn clear_children(&mut self) {
        self.children.clear();
    }
}

#[cfg(feature = "python")]
#[pyclass(frozen, weakref, name = "CaseInsensitive")]
pub struct PyCaseInsensitive {
    // Not pub: all external access goes through shared() or to_py_canonical().
    // A pub field would let mixed-app Rust code construct an unregistered handle
    // (Py::new(py, PyFoo { inner: s.clone() })), silently breaking is-stability.
    inner: Shared<CaseInsensitive>,
}

#[cfg(feature = "python")]
impl PyCaseInsensitive {
    /// Return a reference to the inner `Shared<CaseInsensitive>`.
    pub fn shared(&self) -> &Shared<CaseInsensitive> {
        &self.inner
    }

    /// Wrap a `Shared<CaseInsensitive>` into a canonical Python handle,
    /// looking up the registry first so the same handle is returned
    /// for the same `Shared` allocation.
    pub fn to_py_canonical(py: Python<'_>, s: &Shared<CaseInsensitive>) -> pyo3::PyResult<Py<PyCaseInsensitive>> {
        let addr = s.arc_ptr();
        let obj = registry::get_or_insert_with(py, addr, || {
            let handle = PyCaseInsensitive { inner: s.clone() };
            Py::new(py, handle).map(|p| p.into_any())
        })?;
        obj.bind(py).cast::<PyCaseInsensitive>().map(|b| b.clone().unbind()).map_err(|e| e.into())
    }

    /// Snapshot the children carrying `label` into a new Python list.
    fn py_children_snapshot(&self, py: Python<'_>, label: &CaseInsensitiveLabel) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Lock scope: filter by label under the read guard, cloning only matching
        // children (Arc bump or Span copy each); drop the guard before to_pyobject,
        // which performs Python work that must not happen while a node lock is held.
        let matching: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.iter()
                .filter(|(lbl, _)| lbl.as_ref() == Some(label))
                .map(|(_, child)| child.clone())
                .collect()
        };
        let result = pyo3::types::PyList::empty(py);
        for child in &matching {
            result.append(child.to_pyobject(py)?)?;
        }
        Ok(result.unbind())
    }
}

#[cfg(feature = "python")]
#[pymethods]
impl PyCaseInsensitive {
    #[new]
    #[pyo3(signature = (*, span = None))]
    fn new(py: Python<'_>, span: ::std::option::Option<&Bound<'_, pyo3::PyAny>>) -> pyo3::PyResult<Py<PyCaseInsensitive>> {
        let native_span = match span {
            Some(s) => extract_span(py, s)?,
            None => Span::unknown(),
        };
        let data = CaseInsensitive {
            span: native_span,
            children: ::std::vec::Vec::new(),
        };
        let shared = Shared::new(data);
        let addr = shared.arc_ptr();
        let handle = PyCaseInsensitive { inner: shared };
        let py_obj = Py::new(py, handle)?;
        // Register as canonical — fresh Shared, no alias can exist yet.
        registry::force_register(py, addr, py_obj.bind(py))?;
        Ok(py_obj)
    }

    #[getter]
    fn span(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Snapshot the span under the read lock, then drop the guard before
        // calling span_to_pyobject — which performs Python work (Py::new or
        // Python method calls) that must not happen while a node lock is held.
        let span = self.inner.read().span.clone();
        span_to_pyobject(py, &span)
    }

    #[setter]
    fn set_span(&self, py: Python<'_>, value: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        self.inner.write().span = extract_span(py, value)?;
        Ok(())
    }

    #[getter]
    fn kind(&self) -> NodeKind {
        NodeKind::CaseInsensitive
    }

    #[classattr]
    #[allow(non_snake_case)]
    fn Label(py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        Ok(<CaseInsensitiveLabel as pyo3::PyTypeInfo>::type_object(py).into_any().unbind())
    }

    #[getter]
    fn children(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Snapshot the children vec (Arc clones for node children — O(n) refcount bumps).
        // Lock scope: acquire read, snapshot, release before touching Python.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.clone()
        };
        let result = pyo3::types::PyList::empty(py);
        for (label, child) in &snapshot {
            let label_obj: Py<pyo3::PyAny> = match label {
                None => py.None(),
                Some(lbl) => lbl.clone().into_pyobject(py)?.into_any().unbind(),
            };
            let child_obj = child.to_pyobject(py)?;
            let tup = pyo3::types::PyTuple::new(py, [label_obj, child_obj])?;
            result.append(tup)?;
        }
        Ok(result.unbind())
    }

    #[pyo3(signature = (child, label = None))]
    fn append(
        &self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>, label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<CaseInsensitiveLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| CaseInsensitiveLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "CaseInsensitive.append: label argument is not a CaseInsensitive_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = CaseInsensitiveChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((native_label, native_child));
        Ok(())
    }

    #[pyo3(signature = (children, label = None))]
    fn extend(
        &self,
        py: Python<'_>,
        children: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<CaseInsensitiveLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| CaseInsensitiveLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "CaseInsensitive.extend: label argument is not a CaseInsensitive_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must leave
        // the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = CaseInsensitiveChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((native_label.clone(), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn extend_children(&self, _py: Python<'_>, other: &PyCaseInsensitive) -> pyo3::PyResult<()> {
        // Snapshot other's children first: the read guard is dropped at the end of
        // this block, so the write lock below is safe even when self and other are
        // the same node (self-extend). No ptr_eq call is needed here — the snapshot
        // approach handles self-extend structurally.
        // Lock scope: hold read only long enough to clone the Arc-based children vec.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = other.inner.read();
            guard.children.clone()
        };
        // Node-typed children are pushed directly as Shared<T> values.  Registry
        // consistency is maintained lazily: wrap-out registers on first Python read
        // via get_or_insert_with (registry.rs).  Eagerly registering here would be
        // a no-op — the WeakValueDictionary would evict handles held by nothing.
        self.inner.write().children.extend(snapshot);
        Ok(())
    }

    fn child(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: read len and clone at most the single entry under the guard;
        // drop the guard before any Python work (object conversion, exception raise).
        let (n, entry) = {
            let guard = self.inner.read();
            let n = guard.children.len();
            let entry = if n == 1 { Some(guard.children[0].clone()) } else { None };
            (n, entry)
        };
        let Some((label, child)) = entry else {
            return Err(PyValueError::new_err(format!(
                "Expected one child but have {n}"
            )));
        };
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn insert(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<CaseInsensitiveLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| CaseInsensitiveLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "CaseInsensitive.insert: label argument is not a CaseInsensitive_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = CaseInsensitiveChild::extract_from_pyobject(py, child, &span_type)?;
        // Index normalization via operator.index (PyNumber_Index semantics).
        // This raises TypeError (not AttributeError) for non-indexable inputs, matching Python's
        // operator.index contract. Must be done BEFORE taking any lock.
        // Overflow by sign: positive overflow clamps to len; negative overflow clamps to 0.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path for the common exact-int case; fall back to sign-based Python call for beyond-i64.
        let (is_negative_big, raw_i64) = if let Ok(i) = raw_idx.extract::<i64>() {
            (false, Some(i))
        } else {
            // Beyond i64: use Python __lt__ to determine sign.  The lt call is still outside
            // any lock, so lock discipline is maintained.
            let neg = raw_idx.lt(0i64)?;
            (neg, None)
        };
        // Now take a single write lock for the entire len-read + clamp + insert sequence.
        let mut guard = self.inner.write();
        let n = guard.children.len();
        let clamped: usize = match raw_i64 {
            Some(i) if i < 0 => {
                let normalized = n as i64 + i;
                if normalized < 0 { 0 } else { normalized as usize }
            }
            Some(i) => {
                let u = i as usize;
                if u > n { n } else { u }
            }
            None => if is_negative_big { 0 } else { n },
        };
        guard.children.insert(clamped, (native_label, native_child));
        Ok(())
    }

    fn remove_at(&self, py: Python<'_>, index: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Capture the caller's original string representation BEFORE normalization,
        // so error messages show the original value (e.g. `True` not `1`).
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError (not AttributeError) for
        // non-indexable inputs, matching Python's operator.index contract.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path: extract i64. Beyond i64 is always OOB for real trees.
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + Vec::remove atomically (no TOCTOU).
        // On OOB, capture n and return Err after releasing the guard.
        let result: ::std::result::Result<_, usize> = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            match resolved {
                Some(idx) => Ok(guard.children.remove(idx)),
                None => Err(n),
            }
        };
        let (label, child) = result.map_err(|n| {
            PyIndexError::new_err(format!(
                "CaseInsensitive.remove_at: index {} out of range ({} children)",
                orig_str, n
            ))
        })?;
        // Python wrap-out happens after the guard is released.
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn replace_at(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<CaseInsensitiveLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| CaseInsensitiveLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "CaseInsensitive.replace_at: label argument is not a CaseInsensitive_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = CaseInsensitiveChild::extract_from_pyobject(py, child, &span_type)?;
        // Capture the caller's original string representation BEFORE normalization.
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError for non-indexable inputs.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + mem::replace atomically (no TOCTOU).
        let old = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            let idx = match resolved {
                Some(i) => i,
                None => {
                    return Err(PyIndexError::new_err(format!(
                        "CaseInsensitive.replace_at: index {} out of range ({} children)",
                        orig_str, n
                    )));
                }
            };
            std::mem::replace(&mut guard.children[idx], (native_label, native_child))
        };
        // Drop old entry outside the lock to avoid recursive lock acquisition
        // if the child's drop chain re-enters Python.
        drop(old);
        Ok(())
    }

    fn clear(&self, _py: Python<'_>) -> pyo3::PyResult<()> {
        let old = {
            let mut guard = self.inner.write();
            std::mem::take(&mut guard.children)
        };
        // Drop old entries outside the lock.
        drop(old);
        Ok(())
    }

    fn append_value(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = CaseInsensitiveChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(CaseInsensitiveLabel::Value), native_child));
        Ok(())
    }

    fn extend_value(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = CaseInsensitiveChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(CaseInsensitiveLabel::Value), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_value(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &CaseInsensitiveLabel::Value)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_value(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(CaseInsensitiveLabel::Value) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one value child but have {count}"
            )));
        }
        first.expect("invariant: CaseInsensitive.child_value: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_value(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(CaseInsensitiveLabel::Value) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one value child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn value(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        self.child_value(py)
    }

    fn value_text(&self) -> pyo3::PyResult<::std::string::String> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(CaseInsensitiveLabel::Value) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one value child but have {count}"
            )));
        }
        match first
            .expect("invariant: CaseInsensitive.value_text: count==1 but first==None; logic error")
        {
            CaseInsensitiveChild::Span(s) => s
                .text_or_message()
                .map(str::to_owned)
                .map_err(PyValueError::new_err),
        }
    }

    fn text(&self) -> pyo3::PyResult<::std::string::String> {
        // Clone the span under the read guard, then release it before raising.
        let span = self.inner.read().span.clone();
        span.text_or_message()
            .map(str::to_owned)
            .map_err(PyValueError::new_err)
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if !other.is_instance_of::<PyCaseInsensitive>() {
            return Ok(py.NotImplemented());
        }
        let other_handle: pyo3::PyRef<PyCaseInsensitive> = other.extract()?;
        // Delegate to Shared<T>::PartialEq which applies the ptr_eq short-circuit
        // (avoids same-lock re-entry on `x == x`) then deep structural comparison.
        let eq = self.inner == other_handle.inner;
        Ok(eq.into_pyobject(py)?.to_owned().unbind().into_any())
    }

    fn __hash__(&self) -> pyo3::PyResult<isize> {
        Err(PyTypeError::new_err("unhashable type: 'CaseInsensitive'"))
    }

    fn __repr__(&self, _py: Python<'_>) -> ::std::string::String {
        let guard = self.inner.read();
        let span_repr = format!("Span(start={}, end={})", guard.span.start(), guard.span.end());
        let children_len = guard.children.len();
        format!(
            "CaseInsensitive(span={span_repr}, children=[<{children_len} child(ren)>])"
        )
    }

}

// ───────────────────────────────────────────────────────────────────────────
// AnchoredWordLabel
// ───────────────────────────────────────────────────────────────────────────

/// Label discriminant enum for children of this node type.
///
/// Python-visible name is `AnchoredWord_Label` (preserved for compatibility).
/// Rust consumers use the CamelCase `AnchoredWordLabel` name.
#[cfg(feature = "python")]
#[pyclass(frozen, from_py_object, name = "AnchoredWord_Label")]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum AnchoredWordLabel {
    #[pyo3(name = "VALUE")]
    Value,
}

#[cfg(not(feature = "python"))]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum AnchoredWordLabel {
    Value,
}

#[cfg(feature = "python")]
#[pymethods]
impl AnchoredWordLabel {
    fn __repr__(&self) -> &'static str {
        match self {
            AnchoredWordLabel::Value => "AnchoredWord.Label.VALUE",
        }
    }

    #[getter]
    fn _fltk_canonical_name(&self) -> &'static str {
        self.__repr__()
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if let Ok(other_kind) = other.extract::<AnchoredWordLabel>() {
            return Ok((self == &other_kind).into_pyobject(py)?.to_owned().unbind().into_any());
        }
        if let Ok(cn) = other.getattr(pyo3::intern!(py, "_fltk_canonical_name")) {
            if let Ok(cn_str) = cn.extract::<&str>() {
                return Ok((self.__repr__() == cn_str).into_pyobject(py)?.to_owned().unbind().into_any());
            }
        }
        Ok(py.NotImplemented())
    }

    fn __hash__(&self, py: Python<'_>) -> pyo3::PyResult<isize> {
        pyo3::types::PyAnyMethods::hash(
            pyo3::types::PyString::new(py, self.__repr__()).as_any()
        )
    }
}

#[cfg(feature = "python")]
impl AnchoredWordLabel {
    /// The variant with this cross-backend canonical name, if any.
    fn from_canonical_name(name: &str) -> ::std::option::Option<Self> {
        match name {
            "AnchoredWord.Label.VALUE" => Some(AnchoredWordLabel::Value),
            _ => None,
        }
    }
}

/// Child value enum for `AnchoredWord` nodes.
///
/// Node-typed variants hold `Shared<T>` (`Arc<RwLock<T>>`); `Clone` is shallow
/// (increments the reference count, does not copy the node).
#[derive(Clone, Debug)]
pub enum AnchoredWordChild {
    Span(Span),
}

impl ::std::cmp::PartialEq for AnchoredWordChild {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (AnchoredWordChild::Span(a), AnchoredWordChild::Span(b)) => a == b,
        }
    }
}

#[cfg(feature = "python")]
impl AnchoredWordChild {
    fn to_pyobject(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        match self {
            Self::Span(s) => {
                span_to_pyobject(py, s)
            }
        }
    }

    fn extract_from_pyobject(
        py: Python<'_>,
        obj: &Bound<'_, pyo3::PyAny>,
        span_type: &Bound<'_, pyo3::types::PyType>,
    ) -> pyo3::PyResult<Self> {
        // Try Span (terminal child) first — handles cross-cdylib span instances.
        if obj.is_instance_of::<Span>() || obj.is_instance(span_type)? {
            return extract_span(py, obj).map(Self::Span);
        }
        let rejected_type = obj.get_type();
        Err(pyo3::exceptions::PyTypeError::new_err(format!(
            "AnchoredWord: unsupported child type {}.{}",
            rejected_type.module()?,
            rejected_type.qualname()?
        )))
    }
}

// ───────────────────────────────────────────────────────────────────────────
// AnchoredWord
// ───────────────────────────────────────────────────────────────────────────

/// CST data struct for `AnchoredWord`. See [`fltk_cst_core::Shared`] for clone/equality/reference semantics.
///
/// `Debug` output is non-recursive: prints span + child count only. Traverse via `children()` to inspect subtrees.
#[derive(Clone)]
pub struct AnchoredWord {
    // Not pub: use span() / children() / push_child() — the stable accessor API.
    // Direct field access bypasses any future validation logic on setters.
    span: Span,
    children: ::std::vec::Vec<(::std::option::Option<AnchoredWordLabel>, AnchoredWordChild)>,
}

// Manual Debug: prints span + child COUNT, never recursing into children.
// A derived Debug would recurse through Shared<T> children with no depth
// bound; tree depth is attacker-controlled for parsers over untrusted
// input, so `{:?}` on a deep tree would abort the process (stack
// exhaustion, uncatchable). Mirrors the Python __repr__'s content.
impl fmt::Debug for AnchoredWord {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("AnchoredWord")
            .field("span", &self.span)
            .field("children", &format_args!("<{} child(ren)>", self.children.len()))
            .finish()
    }
}

// Span-only PartialEq: no node-typed children, so this cannot recurse — depth-safe.
impl ::std::cmp::PartialEq for AnchoredWord {
    fn eq(&self, other: &Self) -> bool {
        self.span == other.span && self.children == other.children
    }
}

impl AnchoredWord {
    /// Construct a node with the given span and no children. GIL-free.
    pub fn new(span: Span) -> Self {
        AnchoredWord {
            span,
            children: ::std::vec::Vec::new(),
        }
    }

    /// Return the [`NodeKind`] discriminant for this node type.
    pub fn kind(&self) -> NodeKind {
        NodeKind::AnchoredWord
    }

    /// Return a reference to the stored [`Span`].
    pub fn span(&self) -> &Span {
        &self.span
    }

    /// Replace the node's span.
    pub fn set_span(&mut self, span: Span) {
        self.span = span;
    }

    /// Return a slice of all children (unfiltered).
    ///
    /// Each entry is `(label, child)`. Use the per-label accessors
    /// (`children_<lbl>`, `child_<lbl>`, `maybe_<lbl>`) for type-safe access.
    pub fn children(&self) -> &[(::std::option::Option<AnchoredWordLabel>, AnchoredWordChild)] {
        self.children.as_slice()
    }

    /// Push a child onto the children `Vec`.
    ///
    /// No type-checking is performed: any child variant may be stored under
    /// any label. Per-label typed mutators (`append_<lbl>`, `extend_<lbl>`)
    /// provide type-constrained alternatives.
    pub fn push_child(&mut self, label: ::std::option::Option<AnchoredWordLabel>, child: AnchoredWordChild) {
        self.children.push((label, child));
    }

    /// Return the single child (any label), or `Err` if there is not exactly one.
    ///
    /// Mirrors the Python `child()` method: count violation → `CstError::ChildCount`.
    pub fn child(&self) -> ::std::result::Result<&(::std::option::Option<AnchoredWordLabel>, AnchoredWordChild), CstError> {
        match self.children.as_slice() {
            [single] => Ok(single),
            slice => Err(CstError::ChildCount {
                label: "<any>",
                expected: "1",
                found: slice.len(),
            }),
        }
    }

    /// Copy all children from `other` into `self`, sharing the `Shared<T>` arcs.
    ///
    /// Children are appended (Arc reference-count bumps, not deep copies),
    /// matching the Python backend's reference-copy behavior. Labels are preserved.
    ///
    /// The borrow checker prevents `self.extend_children(self)` at the data-struct
    /// level (`&mut` + `&` of the same value don't coexist). For self-extend from
    /// Python, the handle pymethod handles it via snapshotting.
    pub fn extend_children(&mut self, other: &Self) {
        self.children.extend(other.children.iter().cloned());
    }

    /// Return an iterator over `Span` children labelled `value`.
    ///
    /// Off-type variants stored under the `value` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_value(&self) -> impl ::std::iter::Iterator<Item = &Span> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(AnchoredWordLabel::Value))
            .map(|(_, child)| match child { AnchoredWordChild::Span(s) => s })
    }

    /// Return the single child labelled `value`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_value(&self) -> ::std::result::Result<&Span, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(AnchoredWordLabel::Value));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                AnchoredWordChild::Span(s) => Ok(s),
            },
            _ => Err(CstError::ChildCount {
                label: "value",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(AnchoredWordLabel::Value))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `value`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_value(&self) -> ::std::result::Result<::std::option::Option<&Span>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(AnchoredWordLabel::Value));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                AnchoredWordChild::Span(s) => Ok(Some(s)),
            },
            _ => Err(CstError::ChildCount {
                label: "value",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(AnchoredWordLabel::Value))
                    .count(),
            }),
        }
    }

    /// Append a `Span` child with label `value`.
    pub fn append_value(&mut self, span: Span) {
        self.children.push((Some(AnchoredWordLabel::Value), AnchoredWordChild::Span(span)));
    }

    /// Append multiple `Span` children with label `value`.
    pub fn extend_value(&mut self, spans: impl ::std::iter::IntoIterator<Item = Span>) {
        self.children.extend(spans.into_iter().map(|s| (Some(AnchoredWordLabel::Value), AnchoredWordChild::Span(s))));
    }

    /// Return the child labelled `value`.
    ///
    /// Panics unless exactly one is present; use `child_value` for the checked form.
    pub fn value(&self) -> &Span {
        self.child_value()
            .unwrap_or_else(|e| panic!("AnchoredWord.value: {e}"))
    }

    /// Return the source text of the child labelled `value`.
    ///
    /// Borrows from the span's source; panics if the child is absent or its span
    /// carries no usable source.
    pub fn value_text(&self) -> &str {
        self.child_value()
            .unwrap_or_else(|e| panic!("AnchoredWord.value_text: {e}"))
            .text_or_message()
            .unwrap_or_else(|e| panic!("AnchoredWord.value_text: {e}"))
    }

    /// Return this node's own source text.
    ///
    /// Covers suppressed content inside the node's span; panics if the span carries no
    /// usable source.
    pub fn text(&self) -> &str {
        self.span
            .text_or_message()
            .unwrap_or_else(|e| panic!("AnchoredWord.text: {e}"))
    }

    /// Insert a child at `index` (Vec::insert semantics: panics if index > len).
    ///
    /// Python-facing clamping is in the `insert` pymethod; native callers must
    /// bounds-check. Unlike `list.insert`, Vec::insert panics on out-of-bounds.
    pub fn insert_child(&mut self, index: usize, label: ::std::option::Option<AnchoredWordLabel>, child: AnchoredWordChild) {
        self.children.insert(index, (label, child));
    }

    /// Remove and return the child at `index` (Vec::remove semantics: panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `remove_at` pymethod.
    pub fn remove_child(&mut self, index: usize) -> (::std::option::Option<AnchoredWordLabel>, AnchoredWordChild) {
        self.children.remove(index)
    }

    /// Replace the child at `index`, returning the old entry (panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `replace_at` pymethod.
    pub fn replace_child(
        &mut self, index: usize, label: ::std::option::Option<AnchoredWordLabel>, child: AnchoredWordChild,
    ) -> (::std::option::Option<AnchoredWordLabel>, AnchoredWordChild) {
        std::mem::replace(&mut self.children[index], (label, child))
    }

    /// Remove all children.
    pub fn clear_children(&mut self) {
        self.children.clear();
    }
}

#[cfg(feature = "python")]
#[pyclass(frozen, weakref, name = "AnchoredWord")]
pub struct PyAnchoredWord {
    // Not pub: all external access goes through shared() or to_py_canonical().
    // A pub field would let mixed-app Rust code construct an unregistered handle
    // (Py::new(py, PyFoo { inner: s.clone() })), silently breaking is-stability.
    inner: Shared<AnchoredWord>,
}

#[cfg(feature = "python")]
impl PyAnchoredWord {
    /// Return a reference to the inner `Shared<AnchoredWord>`.
    pub fn shared(&self) -> &Shared<AnchoredWord> {
        &self.inner
    }

    /// Wrap a `Shared<AnchoredWord>` into a canonical Python handle,
    /// looking up the registry first so the same handle is returned
    /// for the same `Shared` allocation.
    pub fn to_py_canonical(py: Python<'_>, s: &Shared<AnchoredWord>) -> pyo3::PyResult<Py<PyAnchoredWord>> {
        let addr = s.arc_ptr();
        let obj = registry::get_or_insert_with(py, addr, || {
            let handle = PyAnchoredWord { inner: s.clone() };
            Py::new(py, handle).map(|p| p.into_any())
        })?;
        obj.bind(py).cast::<PyAnchoredWord>().map(|b| b.clone().unbind()).map_err(|e| e.into())
    }

    /// Snapshot the children carrying `label` into a new Python list.
    fn py_children_snapshot(&self, py: Python<'_>, label: &AnchoredWordLabel) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Lock scope: filter by label under the read guard, cloning only matching
        // children (Arc bump or Span copy each); drop the guard before to_pyobject,
        // which performs Python work that must not happen while a node lock is held.
        let matching: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.iter()
                .filter(|(lbl, _)| lbl.as_ref() == Some(label))
                .map(|(_, child)| child.clone())
                .collect()
        };
        let result = pyo3::types::PyList::empty(py);
        for child in &matching {
            result.append(child.to_pyobject(py)?)?;
        }
        Ok(result.unbind())
    }
}

#[cfg(feature = "python")]
#[pymethods]
impl PyAnchoredWord {
    #[new]
    #[pyo3(signature = (*, span = None))]
    fn new(py: Python<'_>, span: ::std::option::Option<&Bound<'_, pyo3::PyAny>>) -> pyo3::PyResult<Py<PyAnchoredWord>> {
        let native_span = match span {
            Some(s) => extract_span(py, s)?,
            None => Span::unknown(),
        };
        let data = AnchoredWord {
            span: native_span,
            children: ::std::vec::Vec::new(),
        };
        let shared = Shared::new(data);
        let addr = shared.arc_ptr();
        let handle = PyAnchoredWord { inner: shared };
        let py_obj = Py::new(py, handle)?;
        // Register as canonical — fresh Shared, no alias can exist yet.
        registry::force_register(py, addr, py_obj.bind(py))?;
        Ok(py_obj)
    }

    #[getter]
    fn span(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Snapshot the span under the read lock, then drop the guard before
        // calling span_to_pyobject — which performs Python work (Py::new or
        // Python method calls) that must not happen while a node lock is held.
        let span = self.inner.read().span.clone();
        span_to_pyobject(py, &span)
    }

    #[setter]
    fn set_span(&self, py: Python<'_>, value: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        self.inner.write().span = extract_span(py, value)?;
        Ok(())
    }

    #[getter]
    fn kind(&self) -> NodeKind {
        NodeKind::AnchoredWord
    }

    #[classattr]
    #[allow(non_snake_case)]
    fn Label(py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        Ok(<AnchoredWordLabel as pyo3::PyTypeInfo>::type_object(py).into_any().unbind())
    }

    #[getter]
    fn children(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Snapshot the children vec (Arc clones for node children — O(n) refcount bumps).
        // Lock scope: acquire read, snapshot, release before touching Python.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.clone()
        };
        let result = pyo3::types::PyList::empty(py);
        for (label, child) in &snapshot {
            let label_obj: Py<pyo3::PyAny> = match label {
                None => py.None(),
                Some(lbl) => lbl.clone().into_pyobject(py)?.into_any().unbind(),
            };
            let child_obj = child.to_pyobject(py)?;
            let tup = pyo3::types::PyTuple::new(py, [label_obj, child_obj])?;
            result.append(tup)?;
        }
        Ok(result.unbind())
    }

    #[pyo3(signature = (child, label = None))]
    fn append(
        &self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>, label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<AnchoredWordLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| AnchoredWordLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "AnchoredWord.append: label argument is not a AnchoredWord_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = AnchoredWordChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((native_label, native_child));
        Ok(())
    }

    #[pyo3(signature = (children, label = None))]
    fn extend(
        &self,
        py: Python<'_>,
        children: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<AnchoredWordLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| AnchoredWordLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "AnchoredWord.extend: label argument is not a AnchoredWord_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must leave
        // the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = AnchoredWordChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((native_label.clone(), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn extend_children(&self, _py: Python<'_>, other: &PyAnchoredWord) -> pyo3::PyResult<()> {
        // Snapshot other's children first: the read guard is dropped at the end of
        // this block, so the write lock below is safe even when self and other are
        // the same node (self-extend). No ptr_eq call is needed here — the snapshot
        // approach handles self-extend structurally.
        // Lock scope: hold read only long enough to clone the Arc-based children vec.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = other.inner.read();
            guard.children.clone()
        };
        // Node-typed children are pushed directly as Shared<T> values.  Registry
        // consistency is maintained lazily: wrap-out registers on first Python read
        // via get_or_insert_with (registry.rs).  Eagerly registering here would be
        // a no-op — the WeakValueDictionary would evict handles held by nothing.
        self.inner.write().children.extend(snapshot);
        Ok(())
    }

    fn child(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: read len and clone at most the single entry under the guard;
        // drop the guard before any Python work (object conversion, exception raise).
        let (n, entry) = {
            let guard = self.inner.read();
            let n = guard.children.len();
            let entry = if n == 1 { Some(guard.children[0].clone()) } else { None };
            (n, entry)
        };
        let Some((label, child)) = entry else {
            return Err(PyValueError::new_err(format!(
                "Expected one child but have {n}"
            )));
        };
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn insert(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<AnchoredWordLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| AnchoredWordLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "AnchoredWord.insert: label argument is not a AnchoredWord_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = AnchoredWordChild::extract_from_pyobject(py, child, &span_type)?;
        // Index normalization via operator.index (PyNumber_Index semantics).
        // This raises TypeError (not AttributeError) for non-indexable inputs, matching Python's
        // operator.index contract. Must be done BEFORE taking any lock.
        // Overflow by sign: positive overflow clamps to len; negative overflow clamps to 0.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path for the common exact-int case; fall back to sign-based Python call for beyond-i64.
        let (is_negative_big, raw_i64) = if let Ok(i) = raw_idx.extract::<i64>() {
            (false, Some(i))
        } else {
            // Beyond i64: use Python __lt__ to determine sign.  The lt call is still outside
            // any lock, so lock discipline is maintained.
            let neg = raw_idx.lt(0i64)?;
            (neg, None)
        };
        // Now take a single write lock for the entire len-read + clamp + insert sequence.
        let mut guard = self.inner.write();
        let n = guard.children.len();
        let clamped: usize = match raw_i64 {
            Some(i) if i < 0 => {
                let normalized = n as i64 + i;
                if normalized < 0 { 0 } else { normalized as usize }
            }
            Some(i) => {
                let u = i as usize;
                if u > n { n } else { u }
            }
            None => if is_negative_big { 0 } else { n },
        };
        guard.children.insert(clamped, (native_label, native_child));
        Ok(())
    }

    fn remove_at(&self, py: Python<'_>, index: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Capture the caller's original string representation BEFORE normalization,
        // so error messages show the original value (e.g. `True` not `1`).
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError (not AttributeError) for
        // non-indexable inputs, matching Python's operator.index contract.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path: extract i64. Beyond i64 is always OOB for real trees.
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + Vec::remove atomically (no TOCTOU).
        // On OOB, capture n and return Err after releasing the guard.
        let result: ::std::result::Result<_, usize> = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            match resolved {
                Some(idx) => Ok(guard.children.remove(idx)),
                None => Err(n),
            }
        };
        let (label, child) = result.map_err(|n| {
            PyIndexError::new_err(format!(
                "AnchoredWord.remove_at: index {} out of range ({} children)",
                orig_str, n
            ))
        })?;
        // Python wrap-out happens after the guard is released.
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn replace_at(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<AnchoredWordLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| AnchoredWordLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "AnchoredWord.replace_at: label argument is not a AnchoredWord_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = AnchoredWordChild::extract_from_pyobject(py, child, &span_type)?;
        // Capture the caller's original string representation BEFORE normalization.
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError for non-indexable inputs.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + mem::replace atomically (no TOCTOU).
        let old = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            let idx = match resolved {
                Some(i) => i,
                None => {
                    return Err(PyIndexError::new_err(format!(
                        "AnchoredWord.replace_at: index {} out of range ({} children)",
                        orig_str, n
                    )));
                }
            };
            std::mem::replace(&mut guard.children[idx], (native_label, native_child))
        };
        // Drop old entry outside the lock to avoid recursive lock acquisition
        // if the child's drop chain re-enters Python.
        drop(old);
        Ok(())
    }

    fn clear(&self, _py: Python<'_>) -> pyo3::PyResult<()> {
        let old = {
            let mut guard = self.inner.write();
            std::mem::take(&mut guard.children)
        };
        // Drop old entries outside the lock.
        drop(old);
        Ok(())
    }

    fn append_value(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = AnchoredWordChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(AnchoredWordLabel::Value), native_child));
        Ok(())
    }

    fn extend_value(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = AnchoredWordChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(AnchoredWordLabel::Value), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_value(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &AnchoredWordLabel::Value)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_value(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(AnchoredWordLabel::Value) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one value child but have {count}"
            )));
        }
        first.expect("invariant: AnchoredWord.child_value: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_value(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(AnchoredWordLabel::Value) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one value child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn value(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        self.child_value(py)
    }

    fn value_text(&self) -> pyo3::PyResult<::std::string::String> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(AnchoredWordLabel::Value) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one value child but have {count}"
            )));
        }
        match first
            .expect("invariant: AnchoredWord.value_text: count==1 but first==None; logic error")
        {
            AnchoredWordChild::Span(s) => s
                .text_or_message()
                .map(str::to_owned)
                .map_err(PyValueError::new_err),
        }
    }

    fn text(&self) -> pyo3::PyResult<::std::string::String> {
        // Clone the span under the read guard, then release it before raising.
        let span = self.inner.read().span.clone();
        span.text_or_message()
            .map(str::to_owned)
            .map_err(PyValueError::new_err)
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if !other.is_instance_of::<PyAnchoredWord>() {
            return Ok(py.NotImplemented());
        }
        let other_handle: pyo3::PyRef<PyAnchoredWord> = other.extract()?;
        // Delegate to Shared<T>::PartialEq which applies the ptr_eq short-circuit
        // (avoids same-lock re-entry on `x == x`) then deep structural comparison.
        let eq = self.inner == other_handle.inner;
        Ok(eq.into_pyobject(py)?.to_owned().unbind().into_any())
    }

    fn __hash__(&self) -> pyo3::PyResult<isize> {
        Err(PyTypeError::new_err("unhashable type: 'AnchoredWord'"))
    }

    fn __repr__(&self, _py: Python<'_>) -> ::std::string::String {
        let guard = self.inner.read();
        let span_repr = format!("Span(start={}, end={})", guard.span.start(), guard.span.end());
        let children_len = guard.children.len();
        format!(
            "AnchoredWord(span={span_repr}, children=[<{children_len} child(ren)>])"
        )
    }

}

// ───────────────────────────────────────────────────────────────────────────
// PairLabel
// ───────────────────────────────────────────────────────────────────────────

/// Label discriminant enum for children of this node type.
///
/// Python-visible name is `Pair_Label` (preserved for compatibility).
/// Rust consumers use the CamelCase `PairLabel` name.
#[cfg(feature = "python")]
#[pyclass(frozen, from_py_object, name = "Pair_Label")]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum PairLabel {
    #[pyo3(name = "KEY")]
    Key,
    #[pyo3(name = "VAL")]
    Val,
}

#[cfg(not(feature = "python"))]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum PairLabel {
    Key,
    Val,
}

#[cfg(feature = "python")]
#[pymethods]
impl PairLabel {
    fn __repr__(&self) -> &'static str {
        match self {
            PairLabel::Key => "Pair.Label.KEY",
            PairLabel::Val => "Pair.Label.VAL",
        }
    }

    #[getter]
    fn _fltk_canonical_name(&self) -> &'static str {
        self.__repr__()
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if let Ok(other_kind) = other.extract::<PairLabel>() {
            return Ok((self == &other_kind).into_pyobject(py)?.to_owned().unbind().into_any());
        }
        if let Ok(cn) = other.getattr(pyo3::intern!(py, "_fltk_canonical_name")) {
            if let Ok(cn_str) = cn.extract::<&str>() {
                return Ok((self.__repr__() == cn_str).into_pyobject(py)?.to_owned().unbind().into_any());
            }
        }
        Ok(py.NotImplemented())
    }

    fn __hash__(&self, py: Python<'_>) -> pyo3::PyResult<isize> {
        pyo3::types::PyAnyMethods::hash(
            pyo3::types::PyString::new(py, self.__repr__()).as_any()
        )
    }
}

#[cfg(feature = "python")]
impl PairLabel {
    /// The variant with this cross-backend canonical name, if any.
    fn from_canonical_name(name: &str) -> ::std::option::Option<Self> {
        match name {
            "Pair.Label.KEY" => Some(PairLabel::Key),
            "Pair.Label.VAL" => Some(PairLabel::Val),
            _ => None,
        }
    }
}

/// Child value enum for `Pair` nodes.
///
/// Node-typed variants hold `Shared<T>` (`Arc<RwLock<T>>`); `Clone` is shallow
/// (increments the reference count, does not copy the node).
#[derive(Clone, Debug)]
pub enum PairChild {
    Name(Shared<Name>),
    Num(Shared<Num>),
}

impl ::std::cmp::PartialEq for PairChild {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (PairChild::Name(a), PairChild::Name(b)) => a == b,
            (PairChild::Num(a), PairChild::Num(b)) => a == b,
            _ => false,
        }
    }
}

impl PairChild {
    fn into_drop_item(self) -> ::std::option::Option<DropWorklistItem> {
        match self {
            Self::Name(s) => Some(DropWorklistItem::Name(s)),
            Self::Num(s) => Some(DropWorklistItem::Num(s)),
        }
    }

    /// Shallow structural equality for one child pair.
    /// Span pair: compare directly. Node pair: ptr_eq short-circuit (skip enqueue)
    /// or enqueue for the worklist. Variant mismatch: return false.
    fn eq_shallow_enqueue(&self, other: &Self, worklist: &mut ::std::vec::Vec<EqWorklistItem>) -> bool {
        match (self, other) {
            (Self::Name(a), Self::Name(b)) => {
                if !a.ptr_eq(b) {
                    worklist.push(EqWorklistItem::Name(a.clone(), b.clone()));
                }
                true
            }
            (Self::Num(a), Self::Num(b)) => {
                if !a.ptr_eq(b) {
                    worklist.push(EqWorklistItem::Num(a.clone(), b.clone()));
                }
                true
            }
            _ => false,
        }
    }
}

#[cfg(feature = "python")]
impl PairChild {
    fn to_pyobject(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        match self {
            Self::Name(shared) => {
                let addr = shared.arc_ptr();
                registry::get_or_insert_with(py, addr, || {
                    let handle = PyName { inner: shared.clone() };
                    Py::new(py, handle).map(|p| p.into_any())
                })
            }
            Self::Num(shared) => {
                let addr = shared.arc_ptr();
                registry::get_or_insert_with(py, addr, || {
                    let handle = PyNum { inner: shared.clone() };
                    Py::new(py, handle).map(|p| p.into_any())
                })
            }
        }
    }

    fn extract_from_pyobject(
        py: Python<'_>,
        obj: &Bound<'_, pyo3::PyAny>,
        _span_type: &Bound<'_, pyo3::types::PyType>,
    ) -> pyo3::PyResult<Self> {
        if obj.is_instance_of::<PyName>() {
            let handle: pyo3::PyRef<PyName> = obj.extract()?;
            let shared = handle.inner.clone();
            let addr = shared.arc_ptr();
            // Hand-in: register this Python handle as canonical for its Shared.
            drop(handle); // release the PyRef before calling Python
            // Propagate registry errors: a swallowed Err here would leave the
            // handle unregistered, causing the next wrap-out to mint a different
            // object and silently break is-stability.
            registry::register_if_absent(py, addr, obj)?;
            return Ok(Self::Name(shared));
        }
        if obj.is_instance_of::<PyNum>() {
            let handle: pyo3::PyRef<PyNum> = obj.extract()?;
            let shared = handle.inner.clone();
            let addr = shared.arc_ptr();
            // Hand-in: register this Python handle as canonical for its Shared.
            drop(handle); // release the PyRef before calling Python
            // Propagate registry errors: a swallowed Err here would leave the
            // handle unregistered, causing the next wrap-out to mint a different
            // object and silently break is-stability.
            registry::register_if_absent(py, addr, obj)?;
            return Ok(Self::Num(shared));
        }
        let rejected_type = obj.get_type();
        Err(pyo3::exceptions::PyTypeError::new_err(format!(
            "Pair: unsupported child type {}.{}",
            rejected_type.module()?,
            rejected_type.qualname()?
        )))
    }
}

// ───────────────────────────────────────────────────────────────────────────
// Pair
// ───────────────────────────────────────────────────────────────────────────

/// CST data struct for `Pair`. See [`fltk_cst_core::Shared`] for clone/equality/reference semantics.
///
/// `Debug` output is non-recursive: prints span + child count only. Traverse via `children()` to inspect subtrees.
/// Teardown is iterative: bounded stack at any depth.
/// Equality is iterative: bounded stack at any depth.
#[derive(Clone)]
pub struct Pair {
    // Not pub: use span() / children() / push_child() — the stable accessor API.
    // Direct field access bypasses any future validation logic on setters.
    span: Span,
    children: ::std::vec::Vec<(::std::option::Option<PairLabel>, PairChild)>,
}

// Manual Debug: prints span + child COUNT, never recursing into children.
// A derived Debug would recurse through Shared<T> children with no depth
// bound; tree depth is attacker-controlled for parsers over untrusted
// input, so `{:?}` on a deep tree would abort the process (stack
// exhaustion, uncatchable). Mirrors the Python __repr__'s content.
impl fmt::Debug for Pair {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Pair")
            .field("span", &self.span)
            .field("children", &format_args!("<{} child(ren)>", self.children.len()))
            .finish()
    }
}

// Iterative Drop: derived drop glue would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Drains the subtree via a worklist instead.
impl ::std::ops::Drop for Pair {
    fn drop(&mut self) {
        if self.children.is_empty() {
            return; // also the recursion terminator for nodes drained by the worklist
        }
        // Worklist is allocated lazily: Vec::new() does not heap-allocate until
        // the first push.  drain_into pushes only when it steals (count == 1).
        // In the common backtracking case (shared/memoized children) no steal
        // occurs and no allocation happens.  Owned deep chains allocate once.
        let mut worklist: ::std::vec::Vec<DropWorklistItem> = ::std::vec::Vec::new();
        for (_, child) in self.children.drain(..) {
            if let Some(item) = child.into_drop_item() {
                item.drain_into(&mut worklist);
            }
        }
        while let Some(item) = worklist.pop() {
            item.drain_into(&mut worklist);
        }
    }
}

// Iterative PartialEq: the recursive version would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Uses an explicit worklist of node pairs.
impl ::std::cmp::PartialEq for Pair {
    fn eq(&self, other: &Self) -> bool {
        if self.span != other.span || self.children.len() != other.children.len() {
            return false;
        }
        // Worklist allocated lazily (Vec::new does not heap-allocate until
        // first push); shallow trees and all-ptr_eq children never allocate.
        let mut worklist: ::std::vec::Vec<EqWorklistItem> = ::std::vec::Vec::new();
        for ((la, ca), (lb, cb)) in self.children.iter().zip(other.children.iter()) {
            if la != lb || !ca.eq_shallow_enqueue(cb, &mut worklist) {
                return false;
            }
        }
        while let Some(item) = worklist.pop() {
            if !item.compare(&mut worklist) {
                return false;
            }
        }
        true
    }
}

impl Pair {
    /// Construct a node with the given span and no children. GIL-free.
    pub fn new(span: Span) -> Self {
        Pair {
            span,
            children: ::std::vec::Vec::new(),
        }
    }

    /// Return the [`NodeKind`] discriminant for this node type.
    pub fn kind(&self) -> NodeKind {
        NodeKind::Pair
    }

    /// Return a reference to the stored [`Span`].
    pub fn span(&self) -> &Span {
        &self.span
    }

    /// Replace the node's span.
    pub fn set_span(&mut self, span: Span) {
        self.span = span;
    }

    /// Return a slice of all children (unfiltered).
    ///
    /// Each entry is `(label, child)`. Use the per-label accessors
    /// (`children_<lbl>`, `child_<lbl>`, `maybe_<lbl>`) for type-safe access.
    pub fn children(&self) -> &[(::std::option::Option<PairLabel>, PairChild)] {
        self.children.as_slice()
    }

    /// Push a child onto the children `Vec`.
    ///
    /// No type-checking is performed: any child variant may be stored under
    /// any label. Per-label typed mutators (`append_<lbl>`, `extend_<lbl>`)
    /// provide type-constrained alternatives.
    pub fn push_child(&mut self, label: ::std::option::Option<PairLabel>, child: PairChild) {
        self.children.push((label, child));
    }

    /// Return the single child (any label), or `Err` if there is not exactly one.
    ///
    /// Mirrors the Python `child()` method: count violation → `CstError::ChildCount`.
    pub fn child(&self) -> ::std::result::Result<&(::std::option::Option<PairLabel>, PairChild), CstError> {
        match self.children.as_slice() {
            [single] => Ok(single),
            slice => Err(CstError::ChildCount {
                label: "<any>",
                expected: "1",
                found: slice.len(),
            }),
        }
    }

    /// Copy all children from `other` into `self`, sharing the `Shared<T>` arcs.
    ///
    /// Children are appended (Arc reference-count bumps, not deep copies),
    /// matching the Python backend's reference-copy behavior. Labels are preserved.
    ///
    /// The borrow checker prevents `self.extend_children(self)` at the data-struct
    /// level (`&mut` + `&` of the same value don't coexist). For self-extend from
    /// Python, the handle pymethod handles it via snapshotting.
    pub fn extend_children(&mut self, other: &Self) {
        self.children.extend(other.children.iter().cloned());
    }

    /// Return an iterator over `Shared<Name>` children labelled `key`.
    ///
    /// Off-type variants stored under the `key` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_key(&self) -> impl ::std::iter::Iterator<Item = &Shared<Name>> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(PairLabel::Key))
            .filter_map(|(_, child)| match child {
                PairChild::Name(s) => Some(s),
                _ => None,
            })
    }

    /// Return the single child labelled `key`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_key(&self) -> ::std::result::Result<&Shared<Name>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(PairLabel::Key));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                PairChild::Name(s) => Ok(s),
                _ => Err(CstError::UnexpectedChildType { label: "key" }),
            },
            _ => Err(CstError::ChildCount {
                label: "key",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(PairLabel::Key))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `key`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_key(&self) -> ::std::result::Result<::std::option::Option<&Shared<Name>>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(PairLabel::Key));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                PairChild::Name(s) => Ok(Some(s)),
                _ => Err(CstError::UnexpectedChildType { label: "key" }),
            },
            _ => Err(CstError::ChildCount {
                label: "key",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(PairLabel::Key))
                    .count(),
            }),
        }
    }

    /// Append a child with label `key`, accepting `Name` or `Shared<Name>`.
    pub fn append_key(&mut self, child: impl ::std::convert::Into<Shared<Name>>) {
        self.children.push((Some(PairLabel::Key), PairChild::Name(child.into())));
    }

    /// Append multiple children with label `key`.
    pub fn extend_key(&mut self, children: impl ::std::iter::IntoIterator<Item = impl ::std::convert::Into<Shared<Name>>>) {
        self.children.extend(children.into_iter().map(|c| (Some(PairLabel::Key), PairChild::Name(c.into()))));
    }

    /// Return an iterator over `Shared<Num>` children labelled `val`.
    ///
    /// Off-type variants stored under the `val` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_val(&self) -> impl ::std::iter::Iterator<Item = &Shared<Num>> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(PairLabel::Val))
            .filter_map(|(_, child)| match child {
                PairChild::Num(s) => Some(s),
                _ => None,
            })
    }

    /// Return the single child labelled `val`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_val(&self) -> ::std::result::Result<&Shared<Num>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(PairLabel::Val));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                PairChild::Num(s) => Ok(s),
                _ => Err(CstError::UnexpectedChildType { label: "val" }),
            },
            _ => Err(CstError::ChildCount {
                label: "val",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(PairLabel::Val))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `val`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_val(&self) -> ::std::result::Result<::std::option::Option<&Shared<Num>>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(PairLabel::Val));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                PairChild::Num(s) => Ok(Some(s)),
                _ => Err(CstError::UnexpectedChildType { label: "val" }),
            },
            _ => Err(CstError::ChildCount {
                label: "val",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(PairLabel::Val))
                    .count(),
            }),
        }
    }

    /// Append a child with label `val`, accepting `Num` or `Shared<Num>`.
    pub fn append_val(&mut self, child: impl ::std::convert::Into<Shared<Num>>) {
        self.children.push((Some(PairLabel::Val), PairChild::Num(child.into())));
    }

    /// Append multiple children with label `val`.
    pub fn extend_val(&mut self, children: impl ::std::iter::IntoIterator<Item = impl ::std::convert::Into<Shared<Num>>>) {
        self.children.extend(children.into_iter().map(|c| (Some(PairLabel::Val), PairChild::Num(c.into()))));
    }

    /// Return the child labelled `key`.
    ///
    /// Panics unless exactly one is present; use `child_key` for the checked form.
    pub fn key(&self) -> &Shared<Name> {
        self.child_key()
            .unwrap_or_else(|e| panic!("Pair.key: {e}"))
    }

    /// Return the child labelled `val`.
    ///
    /// Panics unless exactly one is present; use `child_val` for the checked form.
    pub fn val(&self) -> &Shared<Num> {
        self.child_val()
            .unwrap_or_else(|e| panic!("Pair.val: {e}"))
    }

    /// Insert a child at `index` (Vec::insert semantics: panics if index > len).
    ///
    /// Python-facing clamping is in the `insert` pymethod; native callers must
    /// bounds-check. Unlike `list.insert`, Vec::insert panics on out-of-bounds.
    pub fn insert_child(&mut self, index: usize, label: ::std::option::Option<PairLabel>, child: PairChild) {
        self.children.insert(index, (label, child));
    }

    /// Remove and return the child at `index` (Vec::remove semantics: panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `remove_at` pymethod.
    pub fn remove_child(&mut self, index: usize) -> (::std::option::Option<PairLabel>, PairChild) {
        self.children.remove(index)
    }

    /// Replace the child at `index`, returning the old entry (panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `replace_at` pymethod.
    pub fn replace_child(
        &mut self, index: usize, label: ::std::option::Option<PairLabel>, child: PairChild,
    ) -> (::std::option::Option<PairLabel>, PairChild) {
        std::mem::replace(&mut self.children[index], (label, child))
    }

    /// Remove all children.
    pub fn clear_children(&mut self) {
        self.children.clear();
    }
}

#[cfg(feature = "python")]
#[pyclass(frozen, weakref, name = "Pair")]
pub struct PyPair {
    // Not pub: all external access goes through shared() or to_py_canonical().
    // A pub field would let mixed-app Rust code construct an unregistered handle
    // (Py::new(py, PyFoo { inner: s.clone() })), silently breaking is-stability.
    inner: Shared<Pair>,
}

#[cfg(feature = "python")]
impl PyPair {
    /// Return a reference to the inner `Shared<Pair>`.
    pub fn shared(&self) -> &Shared<Pair> {
        &self.inner
    }

    /// Wrap a `Shared<Pair>` into a canonical Python handle,
    /// looking up the registry first so the same handle is returned
    /// for the same `Shared` allocation.
    pub fn to_py_canonical(py: Python<'_>, s: &Shared<Pair>) -> pyo3::PyResult<Py<PyPair>> {
        let addr = s.arc_ptr();
        let obj = registry::get_or_insert_with(py, addr, || {
            let handle = PyPair { inner: s.clone() };
            Py::new(py, handle).map(|p| p.into_any())
        })?;
        obj.bind(py).cast::<PyPair>().map(|b| b.clone().unbind()).map_err(|e| e.into())
    }

    /// Snapshot the children carrying `label` into a new Python list.
    fn py_children_snapshot(&self, py: Python<'_>, label: &PairLabel) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Lock scope: filter by label under the read guard, cloning only matching
        // children (Arc bump or Span copy each); drop the guard before to_pyobject,
        // which performs Python work that must not happen while a node lock is held.
        let matching: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.iter()
                .filter(|(lbl, _)| lbl.as_ref() == Some(label))
                .map(|(_, child)| child.clone())
                .collect()
        };
        let result = pyo3::types::PyList::empty(py);
        for child in &matching {
            result.append(child.to_pyobject(py)?)?;
        }
        Ok(result.unbind())
    }
}

#[cfg(feature = "python")]
#[pymethods]
impl PyPair {
    #[new]
    #[pyo3(signature = (*, span = None))]
    fn new(py: Python<'_>, span: ::std::option::Option<&Bound<'_, pyo3::PyAny>>) -> pyo3::PyResult<Py<PyPair>> {
        let native_span = match span {
            Some(s) => extract_span(py, s)?,
            None => Span::unknown(),
        };
        let data = Pair {
            span: native_span,
            children: ::std::vec::Vec::new(),
        };
        let shared = Shared::new(data);
        let addr = shared.arc_ptr();
        let handle = PyPair { inner: shared };
        let py_obj = Py::new(py, handle)?;
        // Register as canonical — fresh Shared, no alias can exist yet.
        registry::force_register(py, addr, py_obj.bind(py))?;
        Ok(py_obj)
    }

    #[getter]
    fn span(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Snapshot the span under the read lock, then drop the guard before
        // calling span_to_pyobject — which performs Python work (Py::new or
        // Python method calls) that must not happen while a node lock is held.
        let span = self.inner.read().span.clone();
        span_to_pyobject(py, &span)
    }

    #[setter]
    fn set_span(&self, py: Python<'_>, value: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        self.inner.write().span = extract_span(py, value)?;
        Ok(())
    }

    #[getter]
    fn kind(&self) -> NodeKind {
        NodeKind::Pair
    }

    #[classattr]
    #[allow(non_snake_case)]
    fn Label(py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        Ok(<PairLabel as pyo3::PyTypeInfo>::type_object(py).into_any().unbind())
    }

    #[getter]
    fn children(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Snapshot the children vec (Arc clones for node children — O(n) refcount bumps).
        // Lock scope: acquire read, snapshot, release before touching Python.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.clone()
        };
        let result = pyo3::types::PyList::empty(py);
        for (label, child) in &snapshot {
            let label_obj: Py<pyo3::PyAny> = match label {
                None => py.None(),
                Some(lbl) => lbl.clone().into_pyobject(py)?.into_any().unbind(),
            };
            let child_obj = child.to_pyobject(py)?;
            let tup = pyo3::types::PyTuple::new(py, [label_obj, child_obj])?;
            result.append(tup)?;
        }
        Ok(result.unbind())
    }

    #[pyo3(signature = (child, label = None))]
    fn append(
        &self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>, label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<PairLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| PairLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Pair.append: label argument is not a Pair_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = PairChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((native_label, native_child));
        Ok(())
    }

    #[pyo3(signature = (children, label = None))]
    fn extend(
        &self,
        py: Python<'_>,
        children: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<PairLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| PairLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Pair.extend: label argument is not a Pair_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must leave
        // the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = PairChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((native_label.clone(), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn extend_children(&self, _py: Python<'_>, other: &PyPair) -> pyo3::PyResult<()> {
        // Snapshot other's children first: the read guard is dropped at the end of
        // this block, so the write lock below is safe even when self and other are
        // the same node (self-extend). No ptr_eq call is needed here — the snapshot
        // approach handles self-extend structurally.
        // Lock scope: hold read only long enough to clone the Arc-based children vec.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = other.inner.read();
            guard.children.clone()
        };
        // Node-typed children are pushed directly as Shared<T> values.  Registry
        // consistency is maintained lazily: wrap-out registers on first Python read
        // via get_or_insert_with (registry.rs).  Eagerly registering here would be
        // a no-op — the WeakValueDictionary would evict handles held by nothing.
        self.inner.write().children.extend(snapshot);
        Ok(())
    }

    fn child(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: read len and clone at most the single entry under the guard;
        // drop the guard before any Python work (object conversion, exception raise).
        let (n, entry) = {
            let guard = self.inner.read();
            let n = guard.children.len();
            let entry = if n == 1 { Some(guard.children[0].clone()) } else { None };
            (n, entry)
        };
        let Some((label, child)) = entry else {
            return Err(PyValueError::new_err(format!(
                "Expected one child but have {n}"
            )));
        };
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn insert(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<PairLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| PairLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Pair.insert: label argument is not a Pair_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = PairChild::extract_from_pyobject(py, child, &span_type)?;
        // Index normalization via operator.index (PyNumber_Index semantics).
        // This raises TypeError (not AttributeError) for non-indexable inputs, matching Python's
        // operator.index contract. Must be done BEFORE taking any lock.
        // Overflow by sign: positive overflow clamps to len; negative overflow clamps to 0.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path for the common exact-int case; fall back to sign-based Python call for beyond-i64.
        let (is_negative_big, raw_i64) = if let Ok(i) = raw_idx.extract::<i64>() {
            (false, Some(i))
        } else {
            // Beyond i64: use Python __lt__ to determine sign.  The lt call is still outside
            // any lock, so lock discipline is maintained.
            let neg = raw_idx.lt(0i64)?;
            (neg, None)
        };
        // Now take a single write lock for the entire len-read + clamp + insert sequence.
        let mut guard = self.inner.write();
        let n = guard.children.len();
        let clamped: usize = match raw_i64 {
            Some(i) if i < 0 => {
                let normalized = n as i64 + i;
                if normalized < 0 { 0 } else { normalized as usize }
            }
            Some(i) => {
                let u = i as usize;
                if u > n { n } else { u }
            }
            None => if is_negative_big { 0 } else { n },
        };
        guard.children.insert(clamped, (native_label, native_child));
        Ok(())
    }

    fn remove_at(&self, py: Python<'_>, index: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Capture the caller's original string representation BEFORE normalization,
        // so error messages show the original value (e.g. `True` not `1`).
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError (not AttributeError) for
        // non-indexable inputs, matching Python's operator.index contract.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path: extract i64. Beyond i64 is always OOB for real trees.
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + Vec::remove atomically (no TOCTOU).
        // On OOB, capture n and return Err after releasing the guard.
        let result: ::std::result::Result<_, usize> = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            match resolved {
                Some(idx) => Ok(guard.children.remove(idx)),
                None => Err(n),
            }
        };
        let (label, child) = result.map_err(|n| {
            PyIndexError::new_err(format!(
                "Pair.remove_at: index {} out of range ({} children)",
                orig_str, n
            ))
        })?;
        // Python wrap-out happens after the guard is released.
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn replace_at(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<PairLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| PairLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Pair.replace_at: label argument is not a Pair_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = PairChild::extract_from_pyobject(py, child, &span_type)?;
        // Capture the caller's original string representation BEFORE normalization.
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError for non-indexable inputs.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + mem::replace atomically (no TOCTOU).
        let old = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            let idx = match resolved {
                Some(i) => i,
                None => {
                    return Err(PyIndexError::new_err(format!(
                        "Pair.replace_at: index {} out of range ({} children)",
                        orig_str, n
                    )));
                }
            };
            std::mem::replace(&mut guard.children[idx], (native_label, native_child))
        };
        // Drop old entry outside the lock to avoid recursive lock acquisition
        // if the child's drop chain re-enters Python.
        drop(old);
        Ok(())
    }

    fn clear(&self, _py: Python<'_>) -> pyo3::PyResult<()> {
        let old = {
            let mut guard = self.inner.write();
            std::mem::take(&mut guard.children)
        };
        // Drop old entries outside the lock.
        drop(old);
        Ok(())
    }

    fn append_key(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = PairChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(PairLabel::Key), native_child));
        Ok(())
    }

    fn extend_key(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = PairChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(PairLabel::Key), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_key(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &PairLabel::Key)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_key(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(PairLabel::Key) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one key child but have {count}"
            )));
        }
        first.expect("invariant: Pair.child_key: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_key(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(PairLabel::Key) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one key child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn append_val(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = PairChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(PairLabel::Val), native_child));
        Ok(())
    }

    fn extend_val(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = PairChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(PairLabel::Val), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_val(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &PairLabel::Val)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_val(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(PairLabel::Val) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one val child but have {count}"
            )));
        }
        first.expect("invariant: Pair.child_val: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_val(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(PairLabel::Val) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one val child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn key(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        self.child_key(py)
    }

    fn val(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        self.child_val(py)
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if !other.is_instance_of::<PyPair>() {
            return Ok(py.NotImplemented());
        }
        let other_handle: pyo3::PyRef<PyPair> = other.extract()?;
        // Delegate to Shared<T>::PartialEq which applies the ptr_eq short-circuit
        // (avoids same-lock re-entry on `x == x`) then deep structural comparison.
        let eq = self.inner == other_handle.inner;
        Ok(eq.into_pyobject(py)?.to_owned().unbind().into_any())
    }

    fn __hash__(&self) -> pyo3::PyResult<isize> {
        Err(PyTypeError::new_err("unhashable type: 'Pair'"))
    }

    fn __repr__(&self, _py: Python<'_>) -> ::std::string::String {
        let guard = self.inner.read();
        let span_repr = format!("Span(start={}, end={})", guard.span.start(), guard.span.end());
        let children_len = guard.children.len();
        format!(
            "Pair(span={span_repr}, children=[<{children_len} child(ren)>])"
        )
    }

}

// ───────────────────────────────────────────────────────────────────────────
// WrapperLabel
// ───────────────────────────────────────────────────────────────────────────

/// Label discriminant enum for children of this node type.
///
/// Python-visible name is `Wrapper_Label` (preserved for compatibility).
/// Rust consumers use the CamelCase `WrapperLabel` name.
#[cfg(feature = "python")]
#[pyclass(frozen, from_py_object, name = "Wrapper_Label")]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum WrapperLabel {
    #[pyo3(name = "KEY")]
    Key,
    #[pyo3(name = "VAL")]
    Val,
}

#[cfg(not(feature = "python"))]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum WrapperLabel {
    Key,
    Val,
}

#[cfg(feature = "python")]
#[pymethods]
impl WrapperLabel {
    fn __repr__(&self) -> &'static str {
        match self {
            WrapperLabel::Key => "Wrapper.Label.KEY",
            WrapperLabel::Val => "Wrapper.Label.VAL",
        }
    }

    #[getter]
    fn _fltk_canonical_name(&self) -> &'static str {
        self.__repr__()
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if let Ok(other_kind) = other.extract::<WrapperLabel>() {
            return Ok((self == &other_kind).into_pyobject(py)?.to_owned().unbind().into_any());
        }
        if let Ok(cn) = other.getattr(pyo3::intern!(py, "_fltk_canonical_name")) {
            if let Ok(cn_str) = cn.extract::<&str>() {
                return Ok((self.__repr__() == cn_str).into_pyobject(py)?.to_owned().unbind().into_any());
            }
        }
        Ok(py.NotImplemented())
    }

    fn __hash__(&self, py: Python<'_>) -> pyo3::PyResult<isize> {
        pyo3::types::PyAnyMethods::hash(
            pyo3::types::PyString::new(py, self.__repr__()).as_any()
        )
    }
}

#[cfg(feature = "python")]
impl WrapperLabel {
    /// The variant with this cross-backend canonical name, if any.
    fn from_canonical_name(name: &str) -> ::std::option::Option<Self> {
        match name {
            "Wrapper.Label.KEY" => Some(WrapperLabel::Key),
            "Wrapper.Label.VAL" => Some(WrapperLabel::Val),
            _ => None,
        }
    }
}

/// Child value enum for `Wrapper` nodes.
///
/// Node-typed variants hold `Shared<T>` (`Arc<RwLock<T>>`); `Clone` is shallow
/// (increments the reference count, does not copy the node).
#[derive(Clone, Debug)]
pub enum WrapperChild {
    Name(Shared<Name>),
    Num(Shared<Num>),
}

impl ::std::cmp::PartialEq for WrapperChild {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (WrapperChild::Name(a), WrapperChild::Name(b)) => a == b,
            (WrapperChild::Num(a), WrapperChild::Num(b)) => a == b,
            _ => false,
        }
    }
}

impl WrapperChild {
    fn into_drop_item(self) -> ::std::option::Option<DropWorklistItem> {
        match self {
            Self::Name(s) => Some(DropWorklistItem::Name(s)),
            Self::Num(s) => Some(DropWorklistItem::Num(s)),
        }
    }

    /// Shallow structural equality for one child pair.
    /// Span pair: compare directly. Node pair: ptr_eq short-circuit (skip enqueue)
    /// or enqueue for the worklist. Variant mismatch: return false.
    fn eq_shallow_enqueue(&self, other: &Self, worklist: &mut ::std::vec::Vec<EqWorklistItem>) -> bool {
        match (self, other) {
            (Self::Name(a), Self::Name(b)) => {
                if !a.ptr_eq(b) {
                    worklist.push(EqWorklistItem::Name(a.clone(), b.clone()));
                }
                true
            }
            (Self::Num(a), Self::Num(b)) => {
                if !a.ptr_eq(b) {
                    worklist.push(EqWorklistItem::Num(a.clone(), b.clone()));
                }
                true
            }
            _ => false,
        }
    }
}

#[cfg(feature = "python")]
impl WrapperChild {
    fn to_pyobject(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        match self {
            Self::Name(shared) => {
                let addr = shared.arc_ptr();
                registry::get_or_insert_with(py, addr, || {
                    let handle = PyName { inner: shared.clone() };
                    Py::new(py, handle).map(|p| p.into_any())
                })
            }
            Self::Num(shared) => {
                let addr = shared.arc_ptr();
                registry::get_or_insert_with(py, addr, || {
                    let handle = PyNum { inner: shared.clone() };
                    Py::new(py, handle).map(|p| p.into_any())
                })
            }
        }
    }

    fn extract_from_pyobject(
        py: Python<'_>,
        obj: &Bound<'_, pyo3::PyAny>,
        _span_type: &Bound<'_, pyo3::types::PyType>,
    ) -> pyo3::PyResult<Self> {
        if obj.is_instance_of::<PyName>() {
            let handle: pyo3::PyRef<PyName> = obj.extract()?;
            let shared = handle.inner.clone();
            let addr = shared.arc_ptr();
            // Hand-in: register this Python handle as canonical for its Shared.
            drop(handle); // release the PyRef before calling Python
            // Propagate registry errors: a swallowed Err here would leave the
            // handle unregistered, causing the next wrap-out to mint a different
            // object and silently break is-stability.
            registry::register_if_absent(py, addr, obj)?;
            return Ok(Self::Name(shared));
        }
        if obj.is_instance_of::<PyNum>() {
            let handle: pyo3::PyRef<PyNum> = obj.extract()?;
            let shared = handle.inner.clone();
            let addr = shared.arc_ptr();
            // Hand-in: register this Python handle as canonical for its Shared.
            drop(handle); // release the PyRef before calling Python
            // Propagate registry errors: a swallowed Err here would leave the
            // handle unregistered, causing the next wrap-out to mint a different
            // object and silently break is-stability.
            registry::register_if_absent(py, addr, obj)?;
            return Ok(Self::Num(shared));
        }
        let rejected_type = obj.get_type();
        Err(pyo3::exceptions::PyTypeError::new_err(format!(
            "Wrapper: unsupported child type {}.{}",
            rejected_type.module()?,
            rejected_type.qualname()?
        )))
    }
}

// ───────────────────────────────────────────────────────────────────────────
// Wrapper
// ───────────────────────────────────────────────────────────────────────────

/// CST data struct for `Wrapper`. See [`fltk_cst_core::Shared`] for clone/equality/reference semantics.
///
/// `Debug` output is non-recursive: prints span + child count only. Traverse via `children()` to inspect subtrees.
/// Teardown is iterative: bounded stack at any depth.
/// Equality is iterative: bounded stack at any depth.
#[derive(Clone)]
pub struct Wrapper {
    // Not pub: use span() / children() / push_child() — the stable accessor API.
    // Direct field access bypasses any future validation logic on setters.
    span: Span,
    children: ::std::vec::Vec<(::std::option::Option<WrapperLabel>, WrapperChild)>,
}

// Manual Debug: prints span + child COUNT, never recursing into children.
// A derived Debug would recurse through Shared<T> children with no depth
// bound; tree depth is attacker-controlled for parsers over untrusted
// input, so `{:?}` on a deep tree would abort the process (stack
// exhaustion, uncatchable). Mirrors the Python __repr__'s content.
impl fmt::Debug for Wrapper {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Wrapper")
            .field("span", &self.span)
            .field("children", &format_args!("<{} child(ren)>", self.children.len()))
            .finish()
    }
}

// Iterative Drop: derived drop glue would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Drains the subtree via a worklist instead.
impl ::std::ops::Drop for Wrapper {
    fn drop(&mut self) {
        if self.children.is_empty() {
            return; // also the recursion terminator for nodes drained by the worklist
        }
        // Worklist is allocated lazily: Vec::new() does not heap-allocate until
        // the first push.  drain_into pushes only when it steals (count == 1).
        // In the common backtracking case (shared/memoized children) no steal
        // occurs and no allocation happens.  Owned deep chains allocate once.
        let mut worklist: ::std::vec::Vec<DropWorklistItem> = ::std::vec::Vec::new();
        for (_, child) in self.children.drain(..) {
            if let Some(item) = child.into_drop_item() {
                item.drain_into(&mut worklist);
            }
        }
        while let Some(item) = worklist.pop() {
            item.drain_into(&mut worklist);
        }
    }
}

// Iterative PartialEq: the recursive version would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Uses an explicit worklist of node pairs.
impl ::std::cmp::PartialEq for Wrapper {
    fn eq(&self, other: &Self) -> bool {
        if self.span != other.span || self.children.len() != other.children.len() {
            return false;
        }
        // Worklist allocated lazily (Vec::new does not heap-allocate until
        // first push); shallow trees and all-ptr_eq children never allocate.
        let mut worklist: ::std::vec::Vec<EqWorklistItem> = ::std::vec::Vec::new();
        for ((la, ca), (lb, cb)) in self.children.iter().zip(other.children.iter()) {
            if la != lb || !ca.eq_shallow_enqueue(cb, &mut worklist) {
                return false;
            }
        }
        while let Some(item) = worklist.pop() {
            if !item.compare(&mut worklist) {
                return false;
            }
        }
        true
    }
}

impl Wrapper {
    /// Construct a node with the given span and no children. GIL-free.
    pub fn new(span: Span) -> Self {
        Wrapper {
            span,
            children: ::std::vec::Vec::new(),
        }
    }

    /// Return the [`NodeKind`] discriminant for this node type.
    pub fn kind(&self) -> NodeKind {
        NodeKind::Wrapper
    }

    /// Return a reference to the stored [`Span`].
    pub fn span(&self) -> &Span {
        &self.span
    }

    /// Replace the node's span.
    pub fn set_span(&mut self, span: Span) {
        self.span = span;
    }

    /// Return a slice of all children (unfiltered).
    ///
    /// Each entry is `(label, child)`. Use the per-label accessors
    /// (`children_<lbl>`, `child_<lbl>`, `maybe_<lbl>`) for type-safe access.
    pub fn children(&self) -> &[(::std::option::Option<WrapperLabel>, WrapperChild)] {
        self.children.as_slice()
    }

    /// Push a child onto the children `Vec`.
    ///
    /// No type-checking is performed: any child variant may be stored under
    /// any label. Per-label typed mutators (`append_<lbl>`, `extend_<lbl>`)
    /// provide type-constrained alternatives.
    pub fn push_child(&mut self, label: ::std::option::Option<WrapperLabel>, child: WrapperChild) {
        self.children.push((label, child));
    }

    /// Return the single child (any label), or `Err` if there is not exactly one.
    ///
    /// Mirrors the Python `child()` method: count violation → `CstError::ChildCount`.
    pub fn child(&self) -> ::std::result::Result<&(::std::option::Option<WrapperLabel>, WrapperChild), CstError> {
        match self.children.as_slice() {
            [single] => Ok(single),
            slice => Err(CstError::ChildCount {
                label: "<any>",
                expected: "1",
                found: slice.len(),
            }),
        }
    }

    /// Copy all children from `other` into `self`, sharing the `Shared<T>` arcs.
    ///
    /// Children are appended (Arc reference-count bumps, not deep copies),
    /// matching the Python backend's reference-copy behavior. Labels are preserved.
    ///
    /// The borrow checker prevents `self.extend_children(self)` at the data-struct
    /// level (`&mut` + `&` of the same value don't coexist). For self-extend from
    /// Python, the handle pymethod handles it via snapshotting.
    pub fn extend_children(&mut self, other: &Self) {
        self.children.extend(other.children.iter().cloned());
    }

    /// Return an iterator over `Shared<Name>` children labelled `key`.
    ///
    /// Off-type variants stored under the `key` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_key(&self) -> impl ::std::iter::Iterator<Item = &Shared<Name>> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(WrapperLabel::Key))
            .filter_map(|(_, child)| match child {
                WrapperChild::Name(s) => Some(s),
                _ => None,
            })
    }

    /// Return the single child labelled `key`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_key(&self) -> ::std::result::Result<&Shared<Name>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(WrapperLabel::Key));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                WrapperChild::Name(s) => Ok(s),
                _ => Err(CstError::UnexpectedChildType { label: "key" }),
            },
            _ => Err(CstError::ChildCount {
                label: "key",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(WrapperLabel::Key))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `key`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_key(&self) -> ::std::result::Result<::std::option::Option<&Shared<Name>>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(WrapperLabel::Key));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                WrapperChild::Name(s) => Ok(Some(s)),
                _ => Err(CstError::UnexpectedChildType { label: "key" }),
            },
            _ => Err(CstError::ChildCount {
                label: "key",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(WrapperLabel::Key))
                    .count(),
            }),
        }
    }

    /// Append a child with label `key`, accepting `Name` or `Shared<Name>`.
    pub fn append_key(&mut self, child: impl ::std::convert::Into<Shared<Name>>) {
        self.children.push((Some(WrapperLabel::Key), WrapperChild::Name(child.into())));
    }

    /// Append multiple children with label `key`.
    pub fn extend_key(&mut self, children: impl ::std::iter::IntoIterator<Item = impl ::std::convert::Into<Shared<Name>>>) {
        self.children.extend(children.into_iter().map(|c| (Some(WrapperLabel::Key), WrapperChild::Name(c.into()))));
    }

    /// Return an iterator over `Shared<Num>` children labelled `val`.
    ///
    /// Off-type variants stored under the `val` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_val(&self) -> impl ::std::iter::Iterator<Item = &Shared<Num>> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(WrapperLabel::Val))
            .filter_map(|(_, child)| match child {
                WrapperChild::Num(s) => Some(s),
                _ => None,
            })
    }

    /// Return the single child labelled `val`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_val(&self) -> ::std::result::Result<&Shared<Num>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(WrapperLabel::Val));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                WrapperChild::Num(s) => Ok(s),
                _ => Err(CstError::UnexpectedChildType { label: "val" }),
            },
            _ => Err(CstError::ChildCount {
                label: "val",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(WrapperLabel::Val))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `val`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_val(&self) -> ::std::result::Result<::std::option::Option<&Shared<Num>>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(WrapperLabel::Val));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                WrapperChild::Num(s) => Ok(Some(s)),
                _ => Err(CstError::UnexpectedChildType { label: "val" }),
            },
            _ => Err(CstError::ChildCount {
                label: "val",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(WrapperLabel::Val))
                    .count(),
            }),
        }
    }

    /// Append a child with label `val`, accepting `Num` or `Shared<Num>`.
    pub fn append_val(&mut self, child: impl ::std::convert::Into<Shared<Num>>) {
        self.children.push((Some(WrapperLabel::Val), WrapperChild::Num(child.into())));
    }

    /// Append multiple children with label `val`.
    pub fn extend_val(&mut self, children: impl ::std::iter::IntoIterator<Item = impl ::std::convert::Into<Shared<Num>>>) {
        self.children.extend(children.into_iter().map(|c| (Some(WrapperLabel::Val), WrapperChild::Num(c.into()))));
    }

    /// Return the child labelled `key`.
    ///
    /// Panics unless exactly one is present; use `child_key` for the checked form.
    pub fn key(&self) -> &Shared<Name> {
        self.child_key()
            .unwrap_or_else(|e| panic!("Wrapper.key: {e}"))
    }

    /// Return the child labelled `val`.
    ///
    /// Panics unless exactly one is present; use `child_val` for the checked form.
    pub fn val(&self) -> &Shared<Num> {
        self.child_val()
            .unwrap_or_else(|e| panic!("Wrapper.val: {e}"))
    }

    /// Insert a child at `index` (Vec::insert semantics: panics if index > len).
    ///
    /// Python-facing clamping is in the `insert` pymethod; native callers must
    /// bounds-check. Unlike `list.insert`, Vec::insert panics on out-of-bounds.
    pub fn insert_child(&mut self, index: usize, label: ::std::option::Option<WrapperLabel>, child: WrapperChild) {
        self.children.insert(index, (label, child));
    }

    /// Remove and return the child at `index` (Vec::remove semantics: panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `remove_at` pymethod.
    pub fn remove_child(&mut self, index: usize) -> (::std::option::Option<WrapperLabel>, WrapperChild) {
        self.children.remove(index)
    }

    /// Replace the child at `index`, returning the old entry (panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `replace_at` pymethod.
    pub fn replace_child(
        &mut self, index: usize, label: ::std::option::Option<WrapperLabel>, child: WrapperChild,
    ) -> (::std::option::Option<WrapperLabel>, WrapperChild) {
        std::mem::replace(&mut self.children[index], (label, child))
    }

    /// Remove all children.
    pub fn clear_children(&mut self) {
        self.children.clear();
    }
}

#[cfg(feature = "python")]
#[pyclass(frozen, weakref, name = "Wrapper")]
pub struct PyWrapper {
    // Not pub: all external access goes through shared() or to_py_canonical().
    // A pub field would let mixed-app Rust code construct an unregistered handle
    // (Py::new(py, PyFoo { inner: s.clone() })), silently breaking is-stability.
    inner: Shared<Wrapper>,
}

#[cfg(feature = "python")]
impl PyWrapper {
    /// Return a reference to the inner `Shared<Wrapper>`.
    pub fn shared(&self) -> &Shared<Wrapper> {
        &self.inner
    }

    /// Wrap a `Shared<Wrapper>` into a canonical Python handle,
    /// looking up the registry first so the same handle is returned
    /// for the same `Shared` allocation.
    pub fn to_py_canonical(py: Python<'_>, s: &Shared<Wrapper>) -> pyo3::PyResult<Py<PyWrapper>> {
        let addr = s.arc_ptr();
        let obj = registry::get_or_insert_with(py, addr, || {
            let handle = PyWrapper { inner: s.clone() };
            Py::new(py, handle).map(|p| p.into_any())
        })?;
        obj.bind(py).cast::<PyWrapper>().map(|b| b.clone().unbind()).map_err(|e| e.into())
    }

    /// Snapshot the children carrying `label` into a new Python list.
    fn py_children_snapshot(&self, py: Python<'_>, label: &WrapperLabel) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Lock scope: filter by label under the read guard, cloning only matching
        // children (Arc bump or Span copy each); drop the guard before to_pyobject,
        // which performs Python work that must not happen while a node lock is held.
        let matching: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.iter()
                .filter(|(lbl, _)| lbl.as_ref() == Some(label))
                .map(|(_, child)| child.clone())
                .collect()
        };
        let result = pyo3::types::PyList::empty(py);
        for child in &matching {
            result.append(child.to_pyobject(py)?)?;
        }
        Ok(result.unbind())
    }
}

#[cfg(feature = "python")]
#[pymethods]
impl PyWrapper {
    #[new]
    #[pyo3(signature = (*, span = None))]
    fn new(py: Python<'_>, span: ::std::option::Option<&Bound<'_, pyo3::PyAny>>) -> pyo3::PyResult<Py<PyWrapper>> {
        let native_span = match span {
            Some(s) => extract_span(py, s)?,
            None => Span::unknown(),
        };
        let data = Wrapper {
            span: native_span,
            children: ::std::vec::Vec::new(),
        };
        let shared = Shared::new(data);
        let addr = shared.arc_ptr();
        let handle = PyWrapper { inner: shared };
        let py_obj = Py::new(py, handle)?;
        // Register as canonical — fresh Shared, no alias can exist yet.
        registry::force_register(py, addr, py_obj.bind(py))?;
        Ok(py_obj)
    }

    #[getter]
    fn span(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Snapshot the span under the read lock, then drop the guard before
        // calling span_to_pyobject — which performs Python work (Py::new or
        // Python method calls) that must not happen while a node lock is held.
        let span = self.inner.read().span.clone();
        span_to_pyobject(py, &span)
    }

    #[setter]
    fn set_span(&self, py: Python<'_>, value: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        self.inner.write().span = extract_span(py, value)?;
        Ok(())
    }

    #[getter]
    fn kind(&self) -> NodeKind {
        NodeKind::Wrapper
    }

    #[classattr]
    #[allow(non_snake_case)]
    fn Label(py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        Ok(<WrapperLabel as pyo3::PyTypeInfo>::type_object(py).into_any().unbind())
    }

    #[getter]
    fn children(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Snapshot the children vec (Arc clones for node children — O(n) refcount bumps).
        // Lock scope: acquire read, snapshot, release before touching Python.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.clone()
        };
        let result = pyo3::types::PyList::empty(py);
        for (label, child) in &snapshot {
            let label_obj: Py<pyo3::PyAny> = match label {
                None => py.None(),
                Some(lbl) => lbl.clone().into_pyobject(py)?.into_any().unbind(),
            };
            let child_obj = child.to_pyobject(py)?;
            let tup = pyo3::types::PyTuple::new(py, [label_obj, child_obj])?;
            result.append(tup)?;
        }
        Ok(result.unbind())
    }

    #[pyo3(signature = (child, label = None))]
    fn append(
        &self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>, label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<WrapperLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| WrapperLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Wrapper.append: label argument is not a Wrapper_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = WrapperChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((native_label, native_child));
        Ok(())
    }

    #[pyo3(signature = (children, label = None))]
    fn extend(
        &self,
        py: Python<'_>,
        children: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<WrapperLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| WrapperLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Wrapper.extend: label argument is not a Wrapper_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must leave
        // the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = WrapperChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((native_label.clone(), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn extend_children(&self, _py: Python<'_>, other: &PyWrapper) -> pyo3::PyResult<()> {
        // Snapshot other's children first: the read guard is dropped at the end of
        // this block, so the write lock below is safe even when self and other are
        // the same node (self-extend). No ptr_eq call is needed here — the snapshot
        // approach handles self-extend structurally.
        // Lock scope: hold read only long enough to clone the Arc-based children vec.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = other.inner.read();
            guard.children.clone()
        };
        // Node-typed children are pushed directly as Shared<T> values.  Registry
        // consistency is maintained lazily: wrap-out registers on first Python read
        // via get_or_insert_with (registry.rs).  Eagerly registering here would be
        // a no-op — the WeakValueDictionary would evict handles held by nothing.
        self.inner.write().children.extend(snapshot);
        Ok(())
    }

    fn child(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: read len and clone at most the single entry under the guard;
        // drop the guard before any Python work (object conversion, exception raise).
        let (n, entry) = {
            let guard = self.inner.read();
            let n = guard.children.len();
            let entry = if n == 1 { Some(guard.children[0].clone()) } else { None };
            (n, entry)
        };
        let Some((label, child)) = entry else {
            return Err(PyValueError::new_err(format!(
                "Expected one child but have {n}"
            )));
        };
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn insert(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<WrapperLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| WrapperLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Wrapper.insert: label argument is not a Wrapper_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = WrapperChild::extract_from_pyobject(py, child, &span_type)?;
        // Index normalization via operator.index (PyNumber_Index semantics).
        // This raises TypeError (not AttributeError) for non-indexable inputs, matching Python's
        // operator.index contract. Must be done BEFORE taking any lock.
        // Overflow by sign: positive overflow clamps to len; negative overflow clamps to 0.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path for the common exact-int case; fall back to sign-based Python call for beyond-i64.
        let (is_negative_big, raw_i64) = if let Ok(i) = raw_idx.extract::<i64>() {
            (false, Some(i))
        } else {
            // Beyond i64: use Python __lt__ to determine sign.  The lt call is still outside
            // any lock, so lock discipline is maintained.
            let neg = raw_idx.lt(0i64)?;
            (neg, None)
        };
        // Now take a single write lock for the entire len-read + clamp + insert sequence.
        let mut guard = self.inner.write();
        let n = guard.children.len();
        let clamped: usize = match raw_i64 {
            Some(i) if i < 0 => {
                let normalized = n as i64 + i;
                if normalized < 0 { 0 } else { normalized as usize }
            }
            Some(i) => {
                let u = i as usize;
                if u > n { n } else { u }
            }
            None => if is_negative_big { 0 } else { n },
        };
        guard.children.insert(clamped, (native_label, native_child));
        Ok(())
    }

    fn remove_at(&self, py: Python<'_>, index: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Capture the caller's original string representation BEFORE normalization,
        // so error messages show the original value (e.g. `True` not `1`).
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError (not AttributeError) for
        // non-indexable inputs, matching Python's operator.index contract.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path: extract i64. Beyond i64 is always OOB for real trees.
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + Vec::remove atomically (no TOCTOU).
        // On OOB, capture n and return Err after releasing the guard.
        let result: ::std::result::Result<_, usize> = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            match resolved {
                Some(idx) => Ok(guard.children.remove(idx)),
                None => Err(n),
            }
        };
        let (label, child) = result.map_err(|n| {
            PyIndexError::new_err(format!(
                "Wrapper.remove_at: index {} out of range ({} children)",
                orig_str, n
            ))
        })?;
        // Python wrap-out happens after the guard is released.
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn replace_at(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<WrapperLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| WrapperLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "Wrapper.replace_at: label argument is not a Wrapper_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = WrapperChild::extract_from_pyobject(py, child, &span_type)?;
        // Capture the caller's original string representation BEFORE normalization.
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError for non-indexable inputs.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + mem::replace atomically (no TOCTOU).
        let old = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            let idx = match resolved {
                Some(i) => i,
                None => {
                    return Err(PyIndexError::new_err(format!(
                        "Wrapper.replace_at: index {} out of range ({} children)",
                        orig_str, n
                    )));
                }
            };
            std::mem::replace(&mut guard.children[idx], (native_label, native_child))
        };
        // Drop old entry outside the lock to avoid recursive lock acquisition
        // if the child's drop chain re-enters Python.
        drop(old);
        Ok(())
    }

    fn clear(&self, _py: Python<'_>) -> pyo3::PyResult<()> {
        let old = {
            let mut guard = self.inner.write();
            std::mem::take(&mut guard.children)
        };
        // Drop old entries outside the lock.
        drop(old);
        Ok(())
    }

    fn append_key(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = WrapperChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(WrapperLabel::Key), native_child));
        Ok(())
    }

    fn extend_key(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = WrapperChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(WrapperLabel::Key), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_key(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &WrapperLabel::Key)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_key(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(WrapperLabel::Key) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one key child but have {count}"
            )));
        }
        first.expect("invariant: Wrapper.child_key: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_key(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(WrapperLabel::Key) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one key child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn append_val(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = WrapperChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(WrapperLabel::Val), native_child));
        Ok(())
    }

    fn extend_val(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = WrapperChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(WrapperLabel::Val), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_val(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &WrapperLabel::Val)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_val(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(WrapperLabel::Val) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one val child but have {count}"
            )));
        }
        first.expect("invariant: Wrapper.child_val: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_val(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(WrapperLabel::Val) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one val child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn key(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        self.child_key(py)
    }

    fn val(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        self.child_val(py)
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if !other.is_instance_of::<PyWrapper>() {
            return Ok(py.NotImplemented());
        }
        let other_handle: pyo3::PyRef<PyWrapper> = other.extract()?;
        // Delegate to Shared<T>::PartialEq which applies the ptr_eq short-circuit
        // (avoids same-lock re-entry on `x == x`) then deep structural comparison.
        let eq = self.inner == other_handle.inner;
        Ok(eq.into_pyobject(py)?.to_owned().unbind().into_any())
    }

    fn __hash__(&self) -> pyo3::PyResult<isize> {
        Err(PyTypeError::new_err("unhashable type: 'Wrapper'"))
    }

    fn __repr__(&self, _py: Python<'_>) -> ::std::string::String {
        let guard = self.inner.read();
        let span_repr = format!("Span(start={}, end={})", guard.span.start(), guard.span.end());
        let children_len = guard.children.len();
        format!(
            "Wrapper(span={span_repr}, children=[<{children_len} child(ren)>])"
        )
    }

}

// ───────────────────────────────────────────────────────────────────────────
// OptWrapperLabel
// ───────────────────────────────────────────────────────────────────────────

/// Label discriminant enum for children of this node type.
///
/// Python-visible name is `OptWrapper_Label` (preserved for compatibility).
/// Rust consumers use the CamelCase `OptWrapperLabel` name.
#[cfg(feature = "python")]
#[pyclass(frozen, from_py_object, name = "OptWrapper_Label")]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum OptWrapperLabel {
    #[pyo3(name = "KEY")]
    Key,
    #[pyo3(name = "VAL")]
    Val,
}

#[cfg(not(feature = "python"))]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum OptWrapperLabel {
    Key,
    Val,
}

#[cfg(feature = "python")]
#[pymethods]
impl OptWrapperLabel {
    fn __repr__(&self) -> &'static str {
        match self {
            OptWrapperLabel::Key => "OptWrapper.Label.KEY",
            OptWrapperLabel::Val => "OptWrapper.Label.VAL",
        }
    }

    #[getter]
    fn _fltk_canonical_name(&self) -> &'static str {
        self.__repr__()
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if let Ok(other_kind) = other.extract::<OptWrapperLabel>() {
            return Ok((self == &other_kind).into_pyobject(py)?.to_owned().unbind().into_any());
        }
        if let Ok(cn) = other.getattr(pyo3::intern!(py, "_fltk_canonical_name")) {
            if let Ok(cn_str) = cn.extract::<&str>() {
                return Ok((self.__repr__() == cn_str).into_pyobject(py)?.to_owned().unbind().into_any());
            }
        }
        Ok(py.NotImplemented())
    }

    fn __hash__(&self, py: Python<'_>) -> pyo3::PyResult<isize> {
        pyo3::types::PyAnyMethods::hash(
            pyo3::types::PyString::new(py, self.__repr__()).as_any()
        )
    }
}

#[cfg(feature = "python")]
impl OptWrapperLabel {
    /// The variant with this cross-backend canonical name, if any.
    fn from_canonical_name(name: &str) -> ::std::option::Option<Self> {
        match name {
            "OptWrapper.Label.KEY" => Some(OptWrapperLabel::Key),
            "OptWrapper.Label.VAL" => Some(OptWrapperLabel::Val),
            _ => None,
        }
    }
}

/// Child value enum for `OptWrapper` nodes.
///
/// Node-typed variants hold `Shared<T>` (`Arc<RwLock<T>>`); `Clone` is shallow
/// (increments the reference count, does not copy the node).
#[derive(Clone, Debug)]
pub enum OptWrapperChild {
    Name(Shared<Name>),
    Num(Shared<Num>),
}

impl ::std::cmp::PartialEq for OptWrapperChild {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (OptWrapperChild::Name(a), OptWrapperChild::Name(b)) => a == b,
            (OptWrapperChild::Num(a), OptWrapperChild::Num(b)) => a == b,
            _ => false,
        }
    }
}

impl OptWrapperChild {
    fn into_drop_item(self) -> ::std::option::Option<DropWorklistItem> {
        match self {
            Self::Name(s) => Some(DropWorklistItem::Name(s)),
            Self::Num(s) => Some(DropWorklistItem::Num(s)),
        }
    }

    /// Shallow structural equality for one child pair.
    /// Span pair: compare directly. Node pair: ptr_eq short-circuit (skip enqueue)
    /// or enqueue for the worklist. Variant mismatch: return false.
    fn eq_shallow_enqueue(&self, other: &Self, worklist: &mut ::std::vec::Vec<EqWorklistItem>) -> bool {
        match (self, other) {
            (Self::Name(a), Self::Name(b)) => {
                if !a.ptr_eq(b) {
                    worklist.push(EqWorklistItem::Name(a.clone(), b.clone()));
                }
                true
            }
            (Self::Num(a), Self::Num(b)) => {
                if !a.ptr_eq(b) {
                    worklist.push(EqWorklistItem::Num(a.clone(), b.clone()));
                }
                true
            }
            _ => false,
        }
    }
}

#[cfg(feature = "python")]
impl OptWrapperChild {
    fn to_pyobject(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        match self {
            Self::Name(shared) => {
                let addr = shared.arc_ptr();
                registry::get_or_insert_with(py, addr, || {
                    let handle = PyName { inner: shared.clone() };
                    Py::new(py, handle).map(|p| p.into_any())
                })
            }
            Self::Num(shared) => {
                let addr = shared.arc_ptr();
                registry::get_or_insert_with(py, addr, || {
                    let handle = PyNum { inner: shared.clone() };
                    Py::new(py, handle).map(|p| p.into_any())
                })
            }
        }
    }

    fn extract_from_pyobject(
        py: Python<'_>,
        obj: &Bound<'_, pyo3::PyAny>,
        _span_type: &Bound<'_, pyo3::types::PyType>,
    ) -> pyo3::PyResult<Self> {
        if obj.is_instance_of::<PyName>() {
            let handle: pyo3::PyRef<PyName> = obj.extract()?;
            let shared = handle.inner.clone();
            let addr = shared.arc_ptr();
            // Hand-in: register this Python handle as canonical for its Shared.
            drop(handle); // release the PyRef before calling Python
            // Propagate registry errors: a swallowed Err here would leave the
            // handle unregistered, causing the next wrap-out to mint a different
            // object and silently break is-stability.
            registry::register_if_absent(py, addr, obj)?;
            return Ok(Self::Name(shared));
        }
        if obj.is_instance_of::<PyNum>() {
            let handle: pyo3::PyRef<PyNum> = obj.extract()?;
            let shared = handle.inner.clone();
            let addr = shared.arc_ptr();
            // Hand-in: register this Python handle as canonical for its Shared.
            drop(handle); // release the PyRef before calling Python
            // Propagate registry errors: a swallowed Err here would leave the
            // handle unregistered, causing the next wrap-out to mint a different
            // object and silently break is-stability.
            registry::register_if_absent(py, addr, obj)?;
            return Ok(Self::Num(shared));
        }
        let rejected_type = obj.get_type();
        Err(pyo3::exceptions::PyTypeError::new_err(format!(
            "OptWrapper: unsupported child type {}.{}",
            rejected_type.module()?,
            rejected_type.qualname()?
        )))
    }
}

// ───────────────────────────────────────────────────────────────────────────
// OptWrapper
// ───────────────────────────────────────────────────────────────────────────

/// CST data struct for `OptWrapper`. See [`fltk_cst_core::Shared`] for clone/equality/reference semantics.
///
/// `Debug` output is non-recursive: prints span + child count only. Traverse via `children()` to inspect subtrees.
/// Teardown is iterative: bounded stack at any depth.
/// Equality is iterative: bounded stack at any depth.
#[derive(Clone)]
pub struct OptWrapper {
    // Not pub: use span() / children() / push_child() — the stable accessor API.
    // Direct field access bypasses any future validation logic on setters.
    span: Span,
    children: ::std::vec::Vec<(::std::option::Option<OptWrapperLabel>, OptWrapperChild)>,
}

// Manual Debug: prints span + child COUNT, never recursing into children.
// A derived Debug would recurse through Shared<T> children with no depth
// bound; tree depth is attacker-controlled for parsers over untrusted
// input, so `{:?}` on a deep tree would abort the process (stack
// exhaustion, uncatchable). Mirrors the Python __repr__'s content.
impl fmt::Debug for OptWrapper {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("OptWrapper")
            .field("span", &self.span)
            .field("children", &format_args!("<{} child(ren)>", self.children.len()))
            .finish()
    }
}

// Iterative Drop: derived drop glue would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Drains the subtree via a worklist instead.
impl ::std::ops::Drop for OptWrapper {
    fn drop(&mut self) {
        if self.children.is_empty() {
            return; // also the recursion terminator for nodes drained by the worklist
        }
        // Worklist is allocated lazily: Vec::new() does not heap-allocate until
        // the first push.  drain_into pushes only when it steals (count == 1).
        // In the common backtracking case (shared/memoized children) no steal
        // occurs and no allocation happens.  Owned deep chains allocate once.
        let mut worklist: ::std::vec::Vec<DropWorklistItem> = ::std::vec::Vec::new();
        for (_, child) in self.children.drain(..) {
            if let Some(item) = child.into_drop_item() {
                item.drain_into(&mut worklist);
            }
        }
        while let Some(item) = worklist.pop() {
            item.drain_into(&mut worklist);
        }
    }
}

// Iterative PartialEq: the recursive version would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Uses an explicit worklist of node pairs.
impl ::std::cmp::PartialEq for OptWrapper {
    fn eq(&self, other: &Self) -> bool {
        if self.span != other.span || self.children.len() != other.children.len() {
            return false;
        }
        // Worklist allocated lazily (Vec::new does not heap-allocate until
        // first push); shallow trees and all-ptr_eq children never allocate.
        let mut worklist: ::std::vec::Vec<EqWorklistItem> = ::std::vec::Vec::new();
        for ((la, ca), (lb, cb)) in self.children.iter().zip(other.children.iter()) {
            if la != lb || !ca.eq_shallow_enqueue(cb, &mut worklist) {
                return false;
            }
        }
        while let Some(item) = worklist.pop() {
            if !item.compare(&mut worklist) {
                return false;
            }
        }
        true
    }
}

impl OptWrapper {
    /// Construct a node with the given span and no children. GIL-free.
    pub fn new(span: Span) -> Self {
        OptWrapper {
            span,
            children: ::std::vec::Vec::new(),
        }
    }

    /// Return the [`NodeKind`] discriminant for this node type.
    pub fn kind(&self) -> NodeKind {
        NodeKind::OptWrapper
    }

    /// Return a reference to the stored [`Span`].
    pub fn span(&self) -> &Span {
        &self.span
    }

    /// Replace the node's span.
    pub fn set_span(&mut self, span: Span) {
        self.span = span;
    }

    /// Return a slice of all children (unfiltered).
    ///
    /// Each entry is `(label, child)`. Use the per-label accessors
    /// (`children_<lbl>`, `child_<lbl>`, `maybe_<lbl>`) for type-safe access.
    pub fn children(&self) -> &[(::std::option::Option<OptWrapperLabel>, OptWrapperChild)] {
        self.children.as_slice()
    }

    /// Push a child onto the children `Vec`.
    ///
    /// No type-checking is performed: any child variant may be stored under
    /// any label. Per-label typed mutators (`append_<lbl>`, `extend_<lbl>`)
    /// provide type-constrained alternatives.
    pub fn push_child(&mut self, label: ::std::option::Option<OptWrapperLabel>, child: OptWrapperChild) {
        self.children.push((label, child));
    }

    /// Return the single child (any label), or `Err` if there is not exactly one.
    ///
    /// Mirrors the Python `child()` method: count violation → `CstError::ChildCount`.
    pub fn child(&self) -> ::std::result::Result<&(::std::option::Option<OptWrapperLabel>, OptWrapperChild), CstError> {
        match self.children.as_slice() {
            [single] => Ok(single),
            slice => Err(CstError::ChildCount {
                label: "<any>",
                expected: "1",
                found: slice.len(),
            }),
        }
    }

    /// Copy all children from `other` into `self`, sharing the `Shared<T>` arcs.
    ///
    /// Children are appended (Arc reference-count bumps, not deep copies),
    /// matching the Python backend's reference-copy behavior. Labels are preserved.
    ///
    /// The borrow checker prevents `self.extend_children(self)` at the data-struct
    /// level (`&mut` + `&` of the same value don't coexist). For self-extend from
    /// Python, the handle pymethod handles it via snapshotting.
    pub fn extend_children(&mut self, other: &Self) {
        self.children.extend(other.children.iter().cloned());
    }

    /// Return an iterator over `Shared<Name>` children labelled `key`.
    ///
    /// Off-type variants stored under the `key` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_key(&self) -> impl ::std::iter::Iterator<Item = &Shared<Name>> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(OptWrapperLabel::Key))
            .filter_map(|(_, child)| match child {
                OptWrapperChild::Name(s) => Some(s),
                _ => None,
            })
    }

    /// Return the single child labelled `key`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_key(&self) -> ::std::result::Result<&Shared<Name>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(OptWrapperLabel::Key));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                OptWrapperChild::Name(s) => Ok(s),
                _ => Err(CstError::UnexpectedChildType { label: "key" }),
            },
            _ => Err(CstError::ChildCount {
                label: "key",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(OptWrapperLabel::Key))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `key`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_key(&self) -> ::std::result::Result<::std::option::Option<&Shared<Name>>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(OptWrapperLabel::Key));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                OptWrapperChild::Name(s) => Ok(Some(s)),
                _ => Err(CstError::UnexpectedChildType { label: "key" }),
            },
            _ => Err(CstError::ChildCount {
                label: "key",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(OptWrapperLabel::Key))
                    .count(),
            }),
        }
    }

    /// Append a child with label `key`, accepting `Name` or `Shared<Name>`.
    pub fn append_key(&mut self, child: impl ::std::convert::Into<Shared<Name>>) {
        self.children.push((Some(OptWrapperLabel::Key), OptWrapperChild::Name(child.into())));
    }

    /// Append multiple children with label `key`.
    pub fn extend_key(&mut self, children: impl ::std::iter::IntoIterator<Item = impl ::std::convert::Into<Shared<Name>>>) {
        self.children.extend(children.into_iter().map(|c| (Some(OptWrapperLabel::Key), OptWrapperChild::Name(c.into()))));
    }

    /// Return an iterator over `Shared<Num>` children labelled `val`.
    ///
    /// Off-type variants stored under the `val` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_val(&self) -> impl ::std::iter::Iterator<Item = &Shared<Num>> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(OptWrapperLabel::Val))
            .filter_map(|(_, child)| match child {
                OptWrapperChild::Num(s) => Some(s),
                _ => None,
            })
    }

    /// Return the single child labelled `val`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_val(&self) -> ::std::result::Result<&Shared<Num>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(OptWrapperLabel::Val));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                OptWrapperChild::Num(s) => Ok(s),
                _ => Err(CstError::UnexpectedChildType { label: "val" }),
            },
            _ => Err(CstError::ChildCount {
                label: "val",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(OptWrapperLabel::Val))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `val`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_val(&self) -> ::std::result::Result<::std::option::Option<&Shared<Num>>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(OptWrapperLabel::Val));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                OptWrapperChild::Num(s) => Ok(Some(s)),
                _ => Err(CstError::UnexpectedChildType { label: "val" }),
            },
            _ => Err(CstError::ChildCount {
                label: "val",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(OptWrapperLabel::Val))
                    .count(),
            }),
        }
    }

    /// Append a child with label `val`, accepting `Num` or `Shared<Num>`.
    pub fn append_val(&mut self, child: impl ::std::convert::Into<Shared<Num>>) {
        self.children.push((Some(OptWrapperLabel::Val), OptWrapperChild::Num(child.into())));
    }

    /// Append multiple children with label `val`.
    pub fn extend_val(&mut self, children: impl ::std::iter::IntoIterator<Item = impl ::std::convert::Into<Shared<Num>>>) {
        self.children.extend(children.into_iter().map(|c| (Some(OptWrapperLabel::Val), OptWrapperChild::Num(c.into()))));
    }

    /// Return the optional child labelled `key`.
    ///
    /// Panics if more than one is present; use `maybe_key` for the checked form.
    pub fn key(&self) -> ::std::option::Option<&Shared<Name>> {
        self.maybe_key()
            .unwrap_or_else(|e| panic!("OptWrapper.key: {e}"))
    }

    /// Return the optional child labelled `val`.
    ///
    /// Panics if more than one is present; use `maybe_val` for the checked form.
    pub fn val(&self) -> ::std::option::Option<&Shared<Num>> {
        self.maybe_val()
            .unwrap_or_else(|e| panic!("OptWrapper.val: {e}"))
    }

    /// Insert a child at `index` (Vec::insert semantics: panics if index > len).
    ///
    /// Python-facing clamping is in the `insert` pymethod; native callers must
    /// bounds-check. Unlike `list.insert`, Vec::insert panics on out-of-bounds.
    pub fn insert_child(&mut self, index: usize, label: ::std::option::Option<OptWrapperLabel>, child: OptWrapperChild) {
        self.children.insert(index, (label, child));
    }

    /// Remove and return the child at `index` (Vec::remove semantics: panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `remove_at` pymethod.
    pub fn remove_child(&mut self, index: usize) -> (::std::option::Option<OptWrapperLabel>, OptWrapperChild) {
        self.children.remove(index)
    }

    /// Replace the child at `index`, returning the old entry (panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `replace_at` pymethod.
    pub fn replace_child(
        &mut self, index: usize, label: ::std::option::Option<OptWrapperLabel>, child: OptWrapperChild,
    ) -> (::std::option::Option<OptWrapperLabel>, OptWrapperChild) {
        std::mem::replace(&mut self.children[index], (label, child))
    }

    /// Remove all children.
    pub fn clear_children(&mut self) {
        self.children.clear();
    }
}

#[cfg(feature = "python")]
#[pyclass(frozen, weakref, name = "OptWrapper")]
pub struct PyOptWrapper {
    // Not pub: all external access goes through shared() or to_py_canonical().
    // A pub field would let mixed-app Rust code construct an unregistered handle
    // (Py::new(py, PyFoo { inner: s.clone() })), silently breaking is-stability.
    inner: Shared<OptWrapper>,
}

#[cfg(feature = "python")]
impl PyOptWrapper {
    /// Return a reference to the inner `Shared<OptWrapper>`.
    pub fn shared(&self) -> &Shared<OptWrapper> {
        &self.inner
    }

    /// Wrap a `Shared<OptWrapper>` into a canonical Python handle,
    /// looking up the registry first so the same handle is returned
    /// for the same `Shared` allocation.
    pub fn to_py_canonical(py: Python<'_>, s: &Shared<OptWrapper>) -> pyo3::PyResult<Py<PyOptWrapper>> {
        let addr = s.arc_ptr();
        let obj = registry::get_or_insert_with(py, addr, || {
            let handle = PyOptWrapper { inner: s.clone() };
            Py::new(py, handle).map(|p| p.into_any())
        })?;
        obj.bind(py).cast::<PyOptWrapper>().map(|b| b.clone().unbind()).map_err(|e| e.into())
    }

    /// Snapshot the children carrying `label` into a new Python list.
    fn py_children_snapshot(&self, py: Python<'_>, label: &OptWrapperLabel) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Lock scope: filter by label under the read guard, cloning only matching
        // children (Arc bump or Span copy each); drop the guard before to_pyobject,
        // which performs Python work that must not happen while a node lock is held.
        let matching: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.iter()
                .filter(|(lbl, _)| lbl.as_ref() == Some(label))
                .map(|(_, child)| child.clone())
                .collect()
        };
        let result = pyo3::types::PyList::empty(py);
        for child in &matching {
            result.append(child.to_pyobject(py)?)?;
        }
        Ok(result.unbind())
    }
}

#[cfg(feature = "python")]
#[pymethods]
impl PyOptWrapper {
    #[new]
    #[pyo3(signature = (*, span = None))]
    fn new(py: Python<'_>, span: ::std::option::Option<&Bound<'_, pyo3::PyAny>>) -> pyo3::PyResult<Py<PyOptWrapper>> {
        let native_span = match span {
            Some(s) => extract_span(py, s)?,
            None => Span::unknown(),
        };
        let data = OptWrapper {
            span: native_span,
            children: ::std::vec::Vec::new(),
        };
        let shared = Shared::new(data);
        let addr = shared.arc_ptr();
        let handle = PyOptWrapper { inner: shared };
        let py_obj = Py::new(py, handle)?;
        // Register as canonical — fresh Shared, no alias can exist yet.
        registry::force_register(py, addr, py_obj.bind(py))?;
        Ok(py_obj)
    }

    #[getter]
    fn span(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Snapshot the span under the read lock, then drop the guard before
        // calling span_to_pyobject — which performs Python work (Py::new or
        // Python method calls) that must not happen while a node lock is held.
        let span = self.inner.read().span.clone();
        span_to_pyobject(py, &span)
    }

    #[setter]
    fn set_span(&self, py: Python<'_>, value: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        self.inner.write().span = extract_span(py, value)?;
        Ok(())
    }

    #[getter]
    fn kind(&self) -> NodeKind {
        NodeKind::OptWrapper
    }

    #[classattr]
    #[allow(non_snake_case)]
    fn Label(py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        Ok(<OptWrapperLabel as pyo3::PyTypeInfo>::type_object(py).into_any().unbind())
    }

    #[getter]
    fn children(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Snapshot the children vec (Arc clones for node children — O(n) refcount bumps).
        // Lock scope: acquire read, snapshot, release before touching Python.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.clone()
        };
        let result = pyo3::types::PyList::empty(py);
        for (label, child) in &snapshot {
            let label_obj: Py<pyo3::PyAny> = match label {
                None => py.None(),
                Some(lbl) => lbl.clone().into_pyobject(py)?.into_any().unbind(),
            };
            let child_obj = child.to_pyobject(py)?;
            let tup = pyo3::types::PyTuple::new(py, [label_obj, child_obj])?;
            result.append(tup)?;
        }
        Ok(result.unbind())
    }

    #[pyo3(signature = (child, label = None))]
    fn append(
        &self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>, label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<OptWrapperLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| OptWrapperLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "OptWrapper.append: label argument is not a OptWrapper_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = OptWrapperChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((native_label, native_child));
        Ok(())
    }

    #[pyo3(signature = (children, label = None))]
    fn extend(
        &self,
        py: Python<'_>,
        children: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<OptWrapperLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| OptWrapperLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "OptWrapper.extend: label argument is not a OptWrapper_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must leave
        // the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = OptWrapperChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((native_label.clone(), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn extend_children(&self, _py: Python<'_>, other: &PyOptWrapper) -> pyo3::PyResult<()> {
        // Snapshot other's children first: the read guard is dropped at the end of
        // this block, so the write lock below is safe even when self and other are
        // the same node (self-extend). No ptr_eq call is needed here — the snapshot
        // approach handles self-extend structurally.
        // Lock scope: hold read only long enough to clone the Arc-based children vec.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = other.inner.read();
            guard.children.clone()
        };
        // Node-typed children are pushed directly as Shared<T> values.  Registry
        // consistency is maintained lazily: wrap-out registers on first Python read
        // via get_or_insert_with (registry.rs).  Eagerly registering here would be
        // a no-op — the WeakValueDictionary would evict handles held by nothing.
        self.inner.write().children.extend(snapshot);
        Ok(())
    }

    fn child(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: read len and clone at most the single entry under the guard;
        // drop the guard before any Python work (object conversion, exception raise).
        let (n, entry) = {
            let guard = self.inner.read();
            let n = guard.children.len();
            let entry = if n == 1 { Some(guard.children[0].clone()) } else { None };
            (n, entry)
        };
        let Some((label, child)) = entry else {
            return Err(PyValueError::new_err(format!(
                "Expected one child but have {n}"
            )));
        };
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn insert(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<OptWrapperLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| OptWrapperLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "OptWrapper.insert: label argument is not a OptWrapper_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = OptWrapperChild::extract_from_pyobject(py, child, &span_type)?;
        // Index normalization via operator.index (PyNumber_Index semantics).
        // This raises TypeError (not AttributeError) for non-indexable inputs, matching Python's
        // operator.index contract. Must be done BEFORE taking any lock.
        // Overflow by sign: positive overflow clamps to len; negative overflow clamps to 0.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path for the common exact-int case; fall back to sign-based Python call for beyond-i64.
        let (is_negative_big, raw_i64) = if let Ok(i) = raw_idx.extract::<i64>() {
            (false, Some(i))
        } else {
            // Beyond i64: use Python __lt__ to determine sign.  The lt call is still outside
            // any lock, so lock discipline is maintained.
            let neg = raw_idx.lt(0i64)?;
            (neg, None)
        };
        // Now take a single write lock for the entire len-read + clamp + insert sequence.
        let mut guard = self.inner.write();
        let n = guard.children.len();
        let clamped: usize = match raw_i64 {
            Some(i) if i < 0 => {
                let normalized = n as i64 + i;
                if normalized < 0 { 0 } else { normalized as usize }
            }
            Some(i) => {
                let u = i as usize;
                if u > n { n } else { u }
            }
            None => if is_negative_big { 0 } else { n },
        };
        guard.children.insert(clamped, (native_label, native_child));
        Ok(())
    }

    fn remove_at(&self, py: Python<'_>, index: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Capture the caller's original string representation BEFORE normalization,
        // so error messages show the original value (e.g. `True` not `1`).
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError (not AttributeError) for
        // non-indexable inputs, matching Python's operator.index contract.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path: extract i64. Beyond i64 is always OOB for real trees.
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + Vec::remove atomically (no TOCTOU).
        // On OOB, capture n and return Err after releasing the guard.
        let result: ::std::result::Result<_, usize> = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            match resolved {
                Some(idx) => Ok(guard.children.remove(idx)),
                None => Err(n),
            }
        };
        let (label, child) = result.map_err(|n| {
            PyIndexError::new_err(format!(
                "OptWrapper.remove_at: index {} out of range ({} children)",
                orig_str, n
            ))
        })?;
        // Python wrap-out happens after the guard is released.
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn replace_at(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<OptWrapperLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| OptWrapperLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "OptWrapper.replace_at: label argument is not a OptWrapper_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = OptWrapperChild::extract_from_pyobject(py, child, &span_type)?;
        // Capture the caller's original string representation BEFORE normalization.
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError for non-indexable inputs.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + mem::replace atomically (no TOCTOU).
        let old = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            let idx = match resolved {
                Some(i) => i,
                None => {
                    return Err(PyIndexError::new_err(format!(
                        "OptWrapper.replace_at: index {} out of range ({} children)",
                        orig_str, n
                    )));
                }
            };
            std::mem::replace(&mut guard.children[idx], (native_label, native_child))
        };
        // Drop old entry outside the lock to avoid recursive lock acquisition
        // if the child's drop chain re-enters Python.
        drop(old);
        Ok(())
    }

    fn clear(&self, _py: Python<'_>) -> pyo3::PyResult<()> {
        let old = {
            let mut guard = self.inner.write();
            std::mem::take(&mut guard.children)
        };
        // Drop old entries outside the lock.
        drop(old);
        Ok(())
    }

    fn append_key(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = OptWrapperChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(OptWrapperLabel::Key), native_child));
        Ok(())
    }

    fn extend_key(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = OptWrapperChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(OptWrapperLabel::Key), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_key(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &OptWrapperLabel::Key)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_key(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(OptWrapperLabel::Key) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one key child but have {count}"
            )));
        }
        first.expect("invariant: OptWrapper.child_key: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_key(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(OptWrapperLabel::Key) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one key child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn append_val(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = OptWrapperChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(OptWrapperLabel::Val), native_child));
        Ok(())
    }

    fn extend_val(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = OptWrapperChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(OptWrapperLabel::Val), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_val(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &OptWrapperLabel::Val)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_val(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(OptWrapperLabel::Val) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one val child but have {count}"
            )));
        }
        first.expect("invariant: OptWrapper.child_val: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_val(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(OptWrapperLabel::Val) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one val child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn key(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        self.maybe_key(py)
    }

    fn val(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        self.maybe_val(py)
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if !other.is_instance_of::<PyOptWrapper>() {
            return Ok(py.NotImplemented());
        }
        let other_handle: pyo3::PyRef<PyOptWrapper> = other.extract()?;
        // Delegate to Shared<T>::PartialEq which applies the ptr_eq short-circuit
        // (avoids same-lock re-entry on `x == x`) then deep structural comparison.
        let eq = self.inner == other_handle.inner;
        Ok(eq.into_pyobject(py)?.to_owned().unbind().into_any())
    }

    fn __hash__(&self) -> pyo3::PyResult<isize> {
        Err(PyTypeError::new_err("unhashable type: 'OptWrapper'"))
    }

    fn __repr__(&self, _py: Python<'_>) -> ::std::string::String {
        let guard = self.inner.read();
        let span_repr = format!("Span(start={}, end={})", guard.span.start(), guard.span.end());
        let children_len = guard.children.len();
        format!(
            "OptWrapper(span={span_repr}, children=[<{children_len} child(ren)>])"
        )
    }

}

// ───────────────────────────────────────────────────────────────────────────
// RepWrapperLabel
// ───────────────────────────────────────────────────────────────────────────

/// Label discriminant enum for children of this node type.
///
/// Python-visible name is `RepWrapper_Label` (preserved for compatibility).
/// Rust consumers use the CamelCase `RepWrapperLabel` name.
#[cfg(feature = "python")]
#[pyclass(frozen, from_py_object, name = "RepWrapper_Label")]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum RepWrapperLabel {
    #[pyo3(name = "KEY")]
    Key,
    #[pyo3(name = "VAL")]
    Val,
}

#[cfg(not(feature = "python"))]
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum RepWrapperLabel {
    Key,
    Val,
}

#[cfg(feature = "python")]
#[pymethods]
impl RepWrapperLabel {
    fn __repr__(&self) -> &'static str {
        match self {
            RepWrapperLabel::Key => "RepWrapper.Label.KEY",
            RepWrapperLabel::Val => "RepWrapper.Label.VAL",
        }
    }

    #[getter]
    fn _fltk_canonical_name(&self) -> &'static str {
        self.__repr__()
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if let Ok(other_kind) = other.extract::<RepWrapperLabel>() {
            return Ok((self == &other_kind).into_pyobject(py)?.to_owned().unbind().into_any());
        }
        if let Ok(cn) = other.getattr(pyo3::intern!(py, "_fltk_canonical_name")) {
            if let Ok(cn_str) = cn.extract::<&str>() {
                return Ok((self.__repr__() == cn_str).into_pyobject(py)?.to_owned().unbind().into_any());
            }
        }
        Ok(py.NotImplemented())
    }

    fn __hash__(&self, py: Python<'_>) -> pyo3::PyResult<isize> {
        pyo3::types::PyAnyMethods::hash(
            pyo3::types::PyString::new(py, self.__repr__()).as_any()
        )
    }
}

#[cfg(feature = "python")]
impl RepWrapperLabel {
    /// The variant with this cross-backend canonical name, if any.
    fn from_canonical_name(name: &str) -> ::std::option::Option<Self> {
        match name {
            "RepWrapper.Label.KEY" => Some(RepWrapperLabel::Key),
            "RepWrapper.Label.VAL" => Some(RepWrapperLabel::Val),
            _ => None,
        }
    }
}

/// Child value enum for `RepWrapper` nodes.
///
/// Node-typed variants hold `Shared<T>` (`Arc<RwLock<T>>`); `Clone` is shallow
/// (increments the reference count, does not copy the node).
#[derive(Clone, Debug)]
pub enum RepWrapperChild {
    Name(Shared<Name>),
    Num(Shared<Num>),
}

impl ::std::cmp::PartialEq for RepWrapperChild {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (RepWrapperChild::Name(a), RepWrapperChild::Name(b)) => a == b,
            (RepWrapperChild::Num(a), RepWrapperChild::Num(b)) => a == b,
            _ => false,
        }
    }
}

impl RepWrapperChild {
    fn into_drop_item(self) -> ::std::option::Option<DropWorklistItem> {
        match self {
            Self::Name(s) => Some(DropWorklistItem::Name(s)),
            Self::Num(s) => Some(DropWorklistItem::Num(s)),
        }
    }

    /// Shallow structural equality for one child pair.
    /// Span pair: compare directly. Node pair: ptr_eq short-circuit (skip enqueue)
    /// or enqueue for the worklist. Variant mismatch: return false.
    fn eq_shallow_enqueue(&self, other: &Self, worklist: &mut ::std::vec::Vec<EqWorklistItem>) -> bool {
        match (self, other) {
            (Self::Name(a), Self::Name(b)) => {
                if !a.ptr_eq(b) {
                    worklist.push(EqWorklistItem::Name(a.clone(), b.clone()));
                }
                true
            }
            (Self::Num(a), Self::Num(b)) => {
                if !a.ptr_eq(b) {
                    worklist.push(EqWorklistItem::Num(a.clone(), b.clone()));
                }
                true
            }
            _ => false,
        }
    }
}

#[cfg(feature = "python")]
impl RepWrapperChild {
    fn to_pyobject(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        match self {
            Self::Name(shared) => {
                let addr = shared.arc_ptr();
                registry::get_or_insert_with(py, addr, || {
                    let handle = PyName { inner: shared.clone() };
                    Py::new(py, handle).map(|p| p.into_any())
                })
            }
            Self::Num(shared) => {
                let addr = shared.arc_ptr();
                registry::get_or_insert_with(py, addr, || {
                    let handle = PyNum { inner: shared.clone() };
                    Py::new(py, handle).map(|p| p.into_any())
                })
            }
        }
    }

    fn extract_from_pyobject(
        py: Python<'_>,
        obj: &Bound<'_, pyo3::PyAny>,
        _span_type: &Bound<'_, pyo3::types::PyType>,
    ) -> pyo3::PyResult<Self> {
        if obj.is_instance_of::<PyName>() {
            let handle: pyo3::PyRef<PyName> = obj.extract()?;
            let shared = handle.inner.clone();
            let addr = shared.arc_ptr();
            // Hand-in: register this Python handle as canonical for its Shared.
            drop(handle); // release the PyRef before calling Python
            // Propagate registry errors: a swallowed Err here would leave the
            // handle unregistered, causing the next wrap-out to mint a different
            // object and silently break is-stability.
            registry::register_if_absent(py, addr, obj)?;
            return Ok(Self::Name(shared));
        }
        if obj.is_instance_of::<PyNum>() {
            let handle: pyo3::PyRef<PyNum> = obj.extract()?;
            let shared = handle.inner.clone();
            let addr = shared.arc_ptr();
            // Hand-in: register this Python handle as canonical for its Shared.
            drop(handle); // release the PyRef before calling Python
            // Propagate registry errors: a swallowed Err here would leave the
            // handle unregistered, causing the next wrap-out to mint a different
            // object and silently break is-stability.
            registry::register_if_absent(py, addr, obj)?;
            return Ok(Self::Num(shared));
        }
        let rejected_type = obj.get_type();
        Err(pyo3::exceptions::PyTypeError::new_err(format!(
            "RepWrapper: unsupported child type {}.{}",
            rejected_type.module()?,
            rejected_type.qualname()?
        )))
    }
}

// ───────────────────────────────────────────────────────────────────────────
// RepWrapper
// ───────────────────────────────────────────────────────────────────────────

/// CST data struct for `RepWrapper`. See [`fltk_cst_core::Shared`] for clone/equality/reference semantics.
///
/// `Debug` output is non-recursive: prints span + child count only. Traverse via `children()` to inspect subtrees.
/// Teardown is iterative: bounded stack at any depth.
/// Equality is iterative: bounded stack at any depth.
#[derive(Clone)]
pub struct RepWrapper {
    // Not pub: use span() / children() / push_child() — the stable accessor API.
    // Direct field access bypasses any future validation logic on setters.
    span: Span,
    children: ::std::vec::Vec<(::std::option::Option<RepWrapperLabel>, RepWrapperChild)>,
}

// Manual Debug: prints span + child COUNT, never recursing into children.
// A derived Debug would recurse through Shared<T> children with no depth
// bound; tree depth is attacker-controlled for parsers over untrusted
// input, so `{:?}` on a deep tree would abort the process (stack
// exhaustion, uncatchable). Mirrors the Python __repr__'s content.
impl fmt::Debug for RepWrapper {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("RepWrapper")
            .field("span", &self.span)
            .field("children", &format_args!("<{} child(ren)>", self.children.len()))
            .finish()
    }
}

// Iterative Drop: derived drop glue would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Drains the subtree via a worklist instead.
impl ::std::ops::Drop for RepWrapper {
    fn drop(&mut self) {
        if self.children.is_empty() {
            return; // also the recursion terminator for nodes drained by the worklist
        }
        // Worklist is allocated lazily: Vec::new() does not heap-allocate until
        // the first push.  drain_into pushes only when it steals (count == 1).
        // In the common backtracking case (shared/memoized children) no steal
        // occurs and no allocation happens.  Owned deep chains allocate once.
        let mut worklist: ::std::vec::Vec<DropWorklistItem> = ::std::vec::Vec::new();
        for (_, child) in self.children.drain(..) {
            if let Some(item) = child.into_drop_item() {
                item.drain_into(&mut worklist);
            }
        }
        while let Some(item) = worklist.pop() {
            item.drain_into(&mut worklist);
        }
    }
}

// Iterative PartialEq: the recursive version would recurse through Shared children
// one frame set per tree level (attacker-controlled depth → stack
// exhaustion, uncatchable abort). Uses an explicit worklist of node pairs.
impl ::std::cmp::PartialEq for RepWrapper {
    fn eq(&self, other: &Self) -> bool {
        if self.span != other.span || self.children.len() != other.children.len() {
            return false;
        }
        // Worklist allocated lazily (Vec::new does not heap-allocate until
        // first push); shallow trees and all-ptr_eq children never allocate.
        let mut worklist: ::std::vec::Vec<EqWorklistItem> = ::std::vec::Vec::new();
        for ((la, ca), (lb, cb)) in self.children.iter().zip(other.children.iter()) {
            if la != lb || !ca.eq_shallow_enqueue(cb, &mut worklist) {
                return false;
            }
        }
        while let Some(item) = worklist.pop() {
            if !item.compare(&mut worklist) {
                return false;
            }
        }
        true
    }
}

impl RepWrapper {
    /// Construct a node with the given span and no children. GIL-free.
    pub fn new(span: Span) -> Self {
        RepWrapper {
            span,
            children: ::std::vec::Vec::new(),
        }
    }

    /// Return the [`NodeKind`] discriminant for this node type.
    pub fn kind(&self) -> NodeKind {
        NodeKind::RepWrapper
    }

    /// Return a reference to the stored [`Span`].
    pub fn span(&self) -> &Span {
        &self.span
    }

    /// Replace the node's span.
    pub fn set_span(&mut self, span: Span) {
        self.span = span;
    }

    /// Return a slice of all children (unfiltered).
    ///
    /// Each entry is `(label, child)`. Use the per-label accessors
    /// (`children_<lbl>`, `child_<lbl>`, `maybe_<lbl>`) for type-safe access.
    pub fn children(&self) -> &[(::std::option::Option<RepWrapperLabel>, RepWrapperChild)] {
        self.children.as_slice()
    }

    /// Push a child onto the children `Vec`.
    ///
    /// No type-checking is performed: any child variant may be stored under
    /// any label. Per-label typed mutators (`append_<lbl>`, `extend_<lbl>`)
    /// provide type-constrained alternatives.
    pub fn push_child(&mut self, label: ::std::option::Option<RepWrapperLabel>, child: RepWrapperChild) {
        self.children.push((label, child));
    }

    /// Return the single child (any label), or `Err` if there is not exactly one.
    ///
    /// Mirrors the Python `child()` method: count violation → `CstError::ChildCount`.
    pub fn child(&self) -> ::std::result::Result<&(::std::option::Option<RepWrapperLabel>, RepWrapperChild), CstError> {
        match self.children.as_slice() {
            [single] => Ok(single),
            slice => Err(CstError::ChildCount {
                label: "<any>",
                expected: "1",
                found: slice.len(),
            }),
        }
    }

    /// Copy all children from `other` into `self`, sharing the `Shared<T>` arcs.
    ///
    /// Children are appended (Arc reference-count bumps, not deep copies),
    /// matching the Python backend's reference-copy behavior. Labels are preserved.
    ///
    /// The borrow checker prevents `self.extend_children(self)` at the data-struct
    /// level (`&mut` + `&` of the same value don't coexist). For self-extend from
    /// Python, the handle pymethod handles it via snapshotting.
    pub fn extend_children(&mut self, other: &Self) {
        self.children.extend(other.children.iter().cloned());
    }

    /// Return an iterator over `Shared<Name>` children labelled `key`.
    ///
    /// Off-type variants stored under the `key` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_key(&self) -> impl ::std::iter::Iterator<Item = &Shared<Name>> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(RepWrapperLabel::Key))
            .filter_map(|(_, child)| match child {
                RepWrapperChild::Name(s) => Some(s),
                _ => None,
            })
    }

    /// Return the single child labelled `key`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_key(&self) -> ::std::result::Result<&Shared<Name>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(RepWrapperLabel::Key));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                RepWrapperChild::Name(s) => Ok(s),
                _ => Err(CstError::UnexpectedChildType { label: "key" }),
            },
            _ => Err(CstError::ChildCount {
                label: "key",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(RepWrapperLabel::Key))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `key`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_key(&self) -> ::std::result::Result<::std::option::Option<&Shared<Name>>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(RepWrapperLabel::Key));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                RepWrapperChild::Name(s) => Ok(Some(s)),
                _ => Err(CstError::UnexpectedChildType { label: "key" }),
            },
            _ => Err(CstError::ChildCount {
                label: "key",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(RepWrapperLabel::Key))
                    .count(),
            }),
        }
    }

    /// Append a child with label `key`, accepting `Name` or `Shared<Name>`.
    pub fn append_key(&mut self, child: impl ::std::convert::Into<Shared<Name>>) {
        self.children.push((Some(RepWrapperLabel::Key), RepWrapperChild::Name(child.into())));
    }

    /// Append multiple children with label `key`.
    pub fn extend_key(&mut self, children: impl ::std::iter::IntoIterator<Item = impl ::std::convert::Into<Shared<Name>>>) {
        self.children.extend(children.into_iter().map(|c| (Some(RepWrapperLabel::Key), RepWrapperChild::Name(c.into()))));
    }

    /// Return an iterator over `Shared<Num>` children labelled `val`.
    ///
    /// Off-type variants stored under the `val` label are silently skipped.
    /// Use `children()` (the untyped slice) for a lossless view.
    pub fn children_val(&self) -> impl ::std::iter::Iterator<Item = &Shared<Num>> + '_ {
        self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(RepWrapperLabel::Val))
            .filter_map(|(_, child)| match child {
                RepWrapperChild::Num(s) => Some(s),
                _ => None,
            })
    }

    /// Return the single child labelled `val`, or `Err` if not exactly one.
    ///
    /// Count is checked by label match first (`CstError::ChildCount`); if the
    /// count is valid and the surviving child has the wrong variant type,
    /// `CstError::UnexpectedChildType` is returned (single-typed labels only).
    pub fn child_val(&self) -> ::std::result::Result<&Shared<Num>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(RepWrapperLabel::Val));
        match (it.next(), it.next()) {
            (Some((_, child)), None) => match child {
                RepWrapperChild::Num(s) => Ok(s),
                _ => Err(CstError::UnexpectedChildType { label: "val" }),
            },
            _ => Err(CstError::ChildCount {
                label: "val",
                expected: "1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(RepWrapperLabel::Val))
                    .count(),
            }),
        }
    }

    /// Return the optional child labelled `val`, or `Err` if more than one.
    ///
    /// Returns `Ok(None)` for zero, `Ok(Some(...))` for one,
    /// `Err(CstError::ChildCount)` for two or more.
    pub fn maybe_val(&self) -> ::std::result::Result<::std::option::Option<&Shared<Num>>, CstError> {
        let mut it = self.children.iter()
            .filter(|(lbl, _)| *lbl == Some(RepWrapperLabel::Val));
        match (it.next(), it.next()) {
            (None, _) => Ok(None),
            (Some((_, child)), None) => match child {
                RepWrapperChild::Num(s) => Ok(Some(s)),
                _ => Err(CstError::UnexpectedChildType { label: "val" }),
            },
            _ => Err(CstError::ChildCount {
                label: "val",
                expected: "0 or 1",
                found: self.children.iter()
                    .filter(|(lbl, _)| *lbl == Some(RepWrapperLabel::Val))
                    .count(),
            }),
        }
    }

    /// Append a child with label `val`, accepting `Num` or `Shared<Num>`.
    pub fn append_val(&mut self, child: impl ::std::convert::Into<Shared<Num>>) {
        self.children.push((Some(RepWrapperLabel::Val), RepWrapperChild::Num(child.into())));
    }

    /// Append multiple children with label `val`.
    pub fn extend_val(&mut self, children: impl ::std::iter::IntoIterator<Item = impl ::std::convert::Into<Shared<Num>>>) {
        self.children.extend(children.into_iter().map(|c| (Some(RepWrapperLabel::Val), RepWrapperChild::Num(c.into()))));
    }

    /// Return an iterator over the children labelled `key`.
    ///
    /// Arity-named alias of `children_key`.
    pub fn key(&self) -> impl ::std::iter::Iterator<Item = &Shared<Name>> + '_ {
        self.children_key()
    }

    /// Return an iterator over the children labelled `val`.
    ///
    /// Arity-named alias of `children_val`.
    pub fn val(&self) -> impl ::std::iter::Iterator<Item = &Shared<Num>> + '_ {
        self.children_val()
    }

    /// Insert a child at `index` (Vec::insert semantics: panics if index > len).
    ///
    /// Python-facing clamping is in the `insert` pymethod; native callers must
    /// bounds-check. Unlike `list.insert`, Vec::insert panics on out-of-bounds.
    pub fn insert_child(&mut self, index: usize, label: ::std::option::Option<RepWrapperLabel>, child: RepWrapperChild) {
        self.children.insert(index, (label, child));
    }

    /// Remove and return the child at `index` (Vec::remove semantics: panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `remove_at` pymethod.
    pub fn remove_child(&mut self, index: usize) -> (::std::option::Option<RepWrapperLabel>, RepWrapperChild) {
        self.children.remove(index)
    }

    /// Replace the child at `index`, returning the old entry (panics if out of range).
    ///
    /// Panics on out-of-range. Python-facing IndexError is in the `replace_at` pymethod.
    pub fn replace_child(
        &mut self, index: usize, label: ::std::option::Option<RepWrapperLabel>, child: RepWrapperChild,
    ) -> (::std::option::Option<RepWrapperLabel>, RepWrapperChild) {
        std::mem::replace(&mut self.children[index], (label, child))
    }

    /// Remove all children.
    pub fn clear_children(&mut self) {
        self.children.clear();
    }
}

#[cfg(feature = "python")]
#[pyclass(frozen, weakref, name = "RepWrapper")]
pub struct PyRepWrapper {
    // Not pub: all external access goes through shared() or to_py_canonical().
    // A pub field would let mixed-app Rust code construct an unregistered handle
    // (Py::new(py, PyFoo { inner: s.clone() })), silently breaking is-stability.
    inner: Shared<RepWrapper>,
}

#[cfg(feature = "python")]
impl PyRepWrapper {
    /// Return a reference to the inner `Shared<RepWrapper>`.
    pub fn shared(&self) -> &Shared<RepWrapper> {
        &self.inner
    }

    /// Wrap a `Shared<RepWrapper>` into a canonical Python handle,
    /// looking up the registry first so the same handle is returned
    /// for the same `Shared` allocation.
    pub fn to_py_canonical(py: Python<'_>, s: &Shared<RepWrapper>) -> pyo3::PyResult<Py<PyRepWrapper>> {
        let addr = s.arc_ptr();
        let obj = registry::get_or_insert_with(py, addr, || {
            let handle = PyRepWrapper { inner: s.clone() };
            Py::new(py, handle).map(|p| p.into_any())
        })?;
        obj.bind(py).cast::<PyRepWrapper>().map(|b| b.clone().unbind()).map_err(|e| e.into())
    }

    /// Snapshot the children carrying `label` into a new Python list.
    fn py_children_snapshot(&self, py: Python<'_>, label: &RepWrapperLabel) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Lock scope: filter by label under the read guard, cloning only matching
        // children (Arc bump or Span copy each); drop the guard before to_pyobject,
        // which performs Python work that must not happen while a node lock is held.
        let matching: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.iter()
                .filter(|(lbl, _)| lbl.as_ref() == Some(label))
                .map(|(_, child)| child.clone())
                .collect()
        };
        let result = pyo3::types::PyList::empty(py);
        for child in &matching {
            result.append(child.to_pyobject(py)?)?;
        }
        Ok(result.unbind())
    }
}

#[cfg(feature = "python")]
#[pymethods]
impl PyRepWrapper {
    #[new]
    #[pyo3(signature = (*, span = None))]
    fn new(py: Python<'_>, span: ::std::option::Option<&Bound<'_, pyo3::PyAny>>) -> pyo3::PyResult<Py<PyRepWrapper>> {
        let native_span = match span {
            Some(s) => extract_span(py, s)?,
            None => Span::unknown(),
        };
        let data = RepWrapper {
            span: native_span,
            children: ::std::vec::Vec::new(),
        };
        let shared = Shared::new(data);
        let addr = shared.arc_ptr();
        let handle = PyRepWrapper { inner: shared };
        let py_obj = Py::new(py, handle)?;
        // Register as canonical — fresh Shared, no alias can exist yet.
        registry::force_register(py, addr, py_obj.bind(py))?;
        Ok(py_obj)
    }

    #[getter]
    fn span(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Snapshot the span under the read lock, then drop the guard before
        // calling span_to_pyobject — which performs Python work (Py::new or
        // Python method calls) that must not happen while a node lock is held.
        let span = self.inner.read().span.clone();
        span_to_pyobject(py, &span)
    }

    #[setter]
    fn set_span(&self, py: Python<'_>, value: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        self.inner.write().span = extract_span(py, value)?;
        Ok(())
    }

    #[getter]
    fn kind(&self) -> NodeKind {
        NodeKind::RepWrapper
    }

    #[classattr]
    #[allow(non_snake_case)]
    fn Label(py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        Ok(<RepWrapperLabel as pyo3::PyTypeInfo>::type_object(py).into_any().unbind())
    }

    #[getter]
    fn children(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        // Snapshot the children vec (Arc clones for node children — O(n) refcount bumps).
        // Lock scope: acquire read, snapshot, release before touching Python.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = self.inner.read();
            guard.children.clone()
        };
        let result = pyo3::types::PyList::empty(py);
        for (label, child) in &snapshot {
            let label_obj: Py<pyo3::PyAny> = match label {
                None => py.None(),
                Some(lbl) => lbl.clone().into_pyobject(py)?.into_any().unbind(),
            };
            let child_obj = child.to_pyobject(py)?;
            let tup = pyo3::types::PyTuple::new(py, [label_obj, child_obj])?;
            result.append(tup)?;
        }
        Ok(result.unbind())
    }

    #[pyo3(signature = (child, label = None))]
    fn append(
        &self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>, label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<RepWrapperLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| RepWrapperLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "RepWrapper.append: label argument is not a RepWrapper_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = RepWrapperChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((native_label, native_child));
        Ok(())
    }

    #[pyo3(signature = (children, label = None))]
    fn extend(
        &self,
        py: Python<'_>,
        children: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<RepWrapperLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| RepWrapperLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "RepWrapper.extend: label argument is not a RepWrapper_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must leave
        // the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = RepWrapperChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((native_label.clone(), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn extend_children(&self, _py: Python<'_>, other: &PyRepWrapper) -> pyo3::PyResult<()> {
        // Snapshot other's children first: the read guard is dropped at the end of
        // this block, so the write lock below is safe even when self and other are
        // the same node (self-extend). No ptr_eq call is needed here — the snapshot
        // approach handles self-extend structurally.
        // Lock scope: hold read only long enough to clone the Arc-based children vec.
        let snapshot: ::std::vec::Vec<_> = {
            let guard = other.inner.read();
            guard.children.clone()
        };
        // Node-typed children are pushed directly as Shared<T> values.  Registry
        // consistency is maintained lazily: wrap-out registers on first Python read
        // via get_or_insert_with (registry.rs).  Eagerly registering here would be
        // a no-op — the WeakValueDictionary would evict handles held by nothing.
        self.inner.write().children.extend(snapshot);
        Ok(())
    }

    fn child(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: read len and clone at most the single entry under the guard;
        // drop the guard before any Python work (object conversion, exception raise).
        let (n, entry) = {
            let guard = self.inner.read();
            let n = guard.children.len();
            let entry = if n == 1 { Some(guard.children[0].clone()) } else { None };
            (n, entry)
        };
        let Some((label, child)) = entry else {
            return Err(PyValueError::new_err(format!(
                "Expected one child but have {n}"
            )));
        };
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn insert(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<RepWrapperLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| RepWrapperLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "RepWrapper.insert: label argument is not a RepWrapper_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = RepWrapperChild::extract_from_pyobject(py, child, &span_type)?;
        // Index normalization via operator.index (PyNumber_Index semantics).
        // This raises TypeError (not AttributeError) for non-indexable inputs, matching Python's
        // operator.index contract. Must be done BEFORE taking any lock.
        // Overflow by sign: positive overflow clamps to len; negative overflow clamps to 0.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path for the common exact-int case; fall back to sign-based Python call for beyond-i64.
        let (is_negative_big, raw_i64) = if let Ok(i) = raw_idx.extract::<i64>() {
            (false, Some(i))
        } else {
            // Beyond i64: use Python __lt__ to determine sign.  The lt call is still outside
            // any lock, so lock discipline is maintained.
            let neg = raw_idx.lt(0i64)?;
            (neg, None)
        };
        // Now take a single write lock for the entire len-read + clamp + insert sequence.
        let mut guard = self.inner.write();
        let n = guard.children.len();
        let clamped: usize = match raw_i64 {
            Some(i) if i < 0 => {
                let normalized = n as i64 + i;
                if normalized < 0 { 0 } else { normalized as usize }
            }
            Some(i) => {
                let u = i as usize;
                if u > n { n } else { u }
            }
            None => if is_negative_big { 0 } else { n },
        };
        guard.children.insert(clamped, (native_label, native_child));
        Ok(())
    }

    fn remove_at(&self, py: Python<'_>, index: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Capture the caller's original string representation BEFORE normalization,
        // so error messages show the original value (e.g. `True` not `1`).
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError (not AttributeError) for
        // non-indexable inputs, matching Python's operator.index contract.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        // Fast path: extract i64. Beyond i64 is always OOB for real trees.
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + Vec::remove atomically (no TOCTOU).
        // On OOB, capture n and return Err after releasing the guard.
        let result: ::std::result::Result<_, usize> = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            match resolved {
                Some(idx) => Ok(guard.children.remove(idx)),
                None => Err(n),
            }
        };
        let (label, child) = result.map_err(|n| {
            PyIndexError::new_err(format!(
                "RepWrapper.remove_at: index {} out of range ({} children)",
                orig_str, n
            ))
        })?;
        // Python wrap-out happens after the guard is released.
        let label_obj: Py<pyo3::PyAny> = match label {
            None => py.None(),
            Some(lbl) => lbl.into_pyobject(py)?.into_any().unbind(),
        };
        let child_obj = child.to_pyobject(py)?;
        Ok(pyo3::types::PyTuple::new(py, [label_obj, child_obj])?.into_any().unbind())
    }

    #[pyo3(signature = (index, child, label = None))]
    fn replace_at(
        &self,
        py: Python<'_>,
        index: &Bound<'_, pyo3::PyAny>,
        child: &Bound<'_, pyo3::PyAny>,
        label: ::std::option::Option<Py<pyo3::PyAny>>,
    ) -> pyo3::PyResult<()> {
        // Validate label and child BEFORE taking the write lock; label first, as
        // every mutator on both backends does.
        let native_label = match label {
            None => None,
            Some(lbl) => {
                let bound = lbl.bind(py);
                if let Ok(native_lbl) = bound.extract::<RepWrapperLabel>() {
                    Some(native_lbl)
                } else {
                    // Only AttributeError means "not a label" and falls through to the
                    // TypeError below.  Anything else the lookup raises — a property that
                    // fails, a broken __getattr__, an interrupt — is the caller's real
                    // error and propagates unchanged.
                    use pyo3::exceptions::PyAttributeError;
                    let canonical: ::std::option::Option<::std::string::String> = match bound
                        .getattr(pyo3::intern!(py, "_fltk_canonical_name"))
                    {
                        Ok(attr) => attr.extract::<::std::string::String>().ok(),
                        Err(e) if e.is_instance_of::<PyAttributeError>(py) => None,
                        Err(e) => return Err(e),
                    };
                    match canonical.and_then(|cn| RepWrapperLabel::from_canonical_name(&cn)) {
                        Some(resolved) => Some(resolved),
                        None => {
                            return Err(PyTypeError::new_err(format!(
                                "RepWrapper.replace_at: label argument is not a RepWrapper_Label; got {}",
                                bound.get_type().name()?
                            )));
                        }
                    }
                }
            }
        };
        let span_type = get_span_type(py)?;
        let native_child = RepWrapperChild::extract_from_pyobject(py, child, &span_type)?;
        // Capture the caller's original string representation BEFORE normalization.
        let orig_str = index.str()?.to_string_lossy().into_owned();
        // Normalize via operator.index: raises TypeError for non-indexable inputs.
        // All Python work must happen before any lock.
        let raw_idx = py
            .import(pyo3::intern!(py, "operator"))?
            .getattr(pyo3::intern!(py, "index"))?
            .call1((index,))?;
        let maybe_i64: ::std::option::Option<i64> = raw_idx.extract::<i64>().ok();
        // Single write lock: resolve + bounds-check + mem::replace atomically (no TOCTOU).
        let old = {
            let mut guard = self.inner.write();
            let n = guard.children.len();
            let resolved: ::std::option::Option<usize> = match maybe_i64 {
                Some(i) if i < 0 => {
                    let normalized = n as i64 + i;
                    if normalized < 0 || normalized as usize >= n { None }
                    else { Some(normalized as usize) }
                }
                Some(i) if (i as usize) < n => Some(i as usize),
                _ => None,
            };
            let idx = match resolved {
                Some(i) => i,
                None => {
                    return Err(PyIndexError::new_err(format!(
                        "RepWrapper.replace_at: index {} out of range ({} children)",
                        orig_str, n
                    )));
                }
            };
            std::mem::replace(&mut guard.children[idx], (native_label, native_child))
        };
        // Drop old entry outside the lock to avoid recursive lock acquisition
        // if the child's drop chain re-enters Python.
        drop(old);
        Ok(())
    }

    fn clear(&self, _py: Python<'_>) -> pyo3::PyResult<()> {
        let old = {
            let mut guard = self.inner.write();
            std::mem::take(&mut guard.children)
        };
        // Drop old entries outside the lock.
        drop(old);
        Ok(())
    }

    fn append_key(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = RepWrapperChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(RepWrapperLabel::Key), native_child));
        Ok(())
    }

    fn extend_key(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = RepWrapperChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(RepWrapperLabel::Key), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_key(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &RepWrapperLabel::Key)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_key(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(RepWrapperLabel::Key) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one key child but have {count}"
            )));
        }
        first.expect("invariant: RepWrapper.child_key: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_key(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(RepWrapperLabel::Key) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one key child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn append_val(&self, py: Python<'_>, child: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let native_child = RepWrapperChild::extract_from_pyobject(py, child, &span_type)?;
        self.inner.write().children.push((Some(RepWrapperLabel::Val), native_child));
        Ok(())
    }

    fn extend_val(&self, py: Python<'_>, children: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<()> {
        let span_type = get_span_type(py)?;
        let iter = children.try_iter()?;
        // Extract every child before touching the node: a rejected element must
        // leave the node unmutated (no partial extend).
        let cap = children.len().unwrap_or(0).min(EXTEND_CAPACITY_HINT_CAP);
        let mut pending: ::std::vec::Vec<_> = ::std::vec::Vec::with_capacity(cap);
        for child_result in iter {
            let child = child_result?;
            let native_child = RepWrapperChild::extract_from_pyobject(py, &child, &span_type)?;
            pending.push((Some(RepWrapperLabel::Val), native_child));
        }
        self.inner.write().children.extend(pending);
        Ok(())
    }

    fn children_val(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyIterator>> {
        let snapshot = self.py_children_snapshot(py, &RepWrapperLabel::Val)?;
        Ok(snapshot.bind(py).try_iter()?.unbind())
    }

    fn child_val(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(RepWrapperLabel::Val) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count != 1 {
            return Err(PyValueError::new_err(format!(
                "Expected one val child but have {count}"
            )));
        }
        first.expect("invariant: RepWrapper.child_val: count==1 but first==None; logic error")
            .to_pyobject(py)
    }

    fn maybe_val(&self, py: Python<'_>) -> pyo3::PyResult<::std::option::Option<Py<pyo3::PyAny>>> {
        // Lock scope: count label matches and clone only the first under the guard;
        // drop the guard before to_pyobject / exception raise (Python work).
        let (count, first) = {
            let guard = self.inner.read();
            let mut count = 0usize;
            let mut first = None;
            for (lbl, child) in &guard.children {
                if *lbl == Some(RepWrapperLabel::Val) {
                    count += 1;
                    if count == 1 {
                        first = Some(child.clone());
                    }
                }
            }
            (count, first)
        };
        if count > 1 {
            return Err(PyValueError::new_err(
                "Expected at most one val child but have at least 2",
            ));
        }
        match first {
            None => Ok(None),
            Some(child) => Ok(Some(child.to_pyobject(py)?)),
        }
    }

    fn key(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        self.py_children_snapshot(py, &RepWrapperLabel::Key)
    }

    fn val(&self, py: Python<'_>) -> pyo3::PyResult<Py<pyo3::types::PyList>> {
        self.py_children_snapshot(py, &RepWrapperLabel::Val)
    }

    fn __eq__(&self, py: Python<'_>, other: &Bound<'_, pyo3::PyAny>) -> pyo3::PyResult<Py<pyo3::PyAny>> {
        if !other.is_instance_of::<PyRepWrapper>() {
            return Ok(py.NotImplemented());
        }
        let other_handle: pyo3::PyRef<PyRepWrapper> = other.extract()?;
        // Delegate to Shared<T>::PartialEq which applies the ptr_eq short-circuit
        // (avoids same-lock re-entry on `x == x`) then deep structural comparison.
        let eq = self.inner == other_handle.inner;
        Ok(eq.into_pyobject(py)?.to_owned().unbind().into_any())
    }

    fn __hash__(&self) -> pyo3::PyResult<isize> {
        Err(PyTypeError::new_err("unhashable type: 'RepWrapper'"))
    }

    fn __repr__(&self, _py: Python<'_>) -> ::std::string::String {
        let guard = self.inner.read();
        let span_repr = format!("Span(start={}, end={})", guard.span.start(), guard.span.end());
        let children_len = guard.children.len();
        format!(
            "RepWrapper(span={span_repr}, children=[<{children_len} child(ren)>])"
        )
    }

}

