#[cfg(all(feature = "python", feature = "test-introspection"))]
#[pyfunction]
fn _registry_snapshot(py: Python<'_>) -> pyo3::PyResult<pyo3::Bound<'_, pyo3::types::PyDict>> {
    registry::snapshot(py)
}

